window.FRAGEN=[{"id":"ar-01","typ":"single","frage":"By when must a taxi operator give a new driver the details on pay and working time in writing?","optionen":["At the latest on the first working day","Within 7 days","Within one month","Only if the driver asks"],"richtig":0,"erklaerung":"Names, pay and working time must be provided by the first day of work at the latest. In passenger transport on paper with a signature.","quelle":"§ 2 Abs. 1 NachwG","lc":true,"lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Bis wann muss ein Taxiunternehmer einem neuen Fahrer die Angaben zu Arbeitsentgelt und Arbeitszeit schriftlich aushändigen?","erklaerung":"Namen, Entgelt und Arbeitszeit gehören zu den Angaben, die spätestens am ersten Tag der Arbeitsleistung vorliegen müssen. Im Personenbeförderungsgewerbe auf Papier mit Unterschrift.","optionen":["Spätestens am ersten Arbeitstag","Innerhalb von 7 Tagen","Innerhalb eines Monats","Nur wenn der Fahrer danach fragt"]}},{"id":"ar-02","typ":"zahl","frage":"A taxi driver works 150 hours in February 2026, including waiting time at the rank. He gets 38 % of the net revenue of 5.000 €. How much must the operator pay at least (gross)?","richtig":2085,"einheit":"€","tol":0.5,"loesung":"Revenue-based pay: 38 % × 5.000 € = 1.900,00 €\nMinimum wage: 150 h × 13,90 € = 2.085,00 €\n→ At least 2.085,00 € (the higher amount)","erklaerung":"The minimum wage (13,90 € from 2026) must be reached for every working hour. Standby time counts.","quelle":"§ 1 MiLoG, MiLoV5","lc":true,"lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Ein Taxifahrer arbeitet im Februar 2026 insgesamt 150 Stunden, inklusive Wartezeiten am Taxistand. Er bekommt 38 % vom Netto-Umsatz von 5.000 €. Wie viel muss der Unternehmer mindestens zahlen (brutto)?","erklaerung":"Der Mindestlohn (13,90 € ab 2026) muss für jede Arbeitsstunde erreicht werden. Standzeiten in Bereitschaft zählen mit.","loesung":"Umsatzlohn: 38 % × 5.000 € = 1.900,00 €\nMindestlohn: 150 h × 13,90 € = 2.085,00 €\n→ Mindestens 2.085,00 € (der höhere Betrag)","einheit":"€"}},{"id":"ar-03","typ":"multi","frage":"Which duties apply in the taxi trade because of the fight against undeclared work? Select all correct answers.","optionen":["Drivers must carry an ID card, passport or substitute document.","Record start, end and length of working time by the 7th day at the latest.","Keep the records for at least 2 years.","Register every driver with customs each week.","Pay the driver only in cash."],"richtig":[0,1,2],"erklaerung":"The passenger transport trade is listed in § 2a SchwarzArbG. This leads to the ID duty and the recording duty under § 17 MiLoG.","quelle":"§ 2a SchwarzArbG, § 17 MiLoG","lc":true,"lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Welche Pflichten gelten im Taxigewerbe wegen der Schwarzarbeitsbekämpfung? Wähle alle richtigen.","erklaerung":"Das Personenbeförderungsgewerbe steht in § 2a SchwarzArbG. Daraus folgen Ausweispflicht und die Aufzeichnungspflicht nach § 17 MiLoG.","optionen":["Fahrer müssen Personalausweis, Pass oder Ersatzpapier mitführen.","Beginn, Ende und Dauer der Arbeitszeit spätestens am 7. Tag aufzeichnen.","Die Aufzeichnungen mindestens 2 Jahre aufbewahren.","Jeden Fahrer wöchentlich beim Zoll anmelden.","Den Fahrer nur bar bezahlen."]}},{"id":"ar-04","typ":"zahl","frage":"A driver works 4 days a week. How many days of statutory minimum holiday does she get per year?","richtig":16,"einheit":"days","tol":0,"dez":0,"loesung":"24 working days ÷ 6 × 4 days = 16 days of holiday","erklaerung":"Statutory holiday is 24 working days based on a 6-day week. With fewer days you calculate proportionally.","quelle":"§ 3 BUrlG","lc":true,"lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Eine Fahrerin arbeitet an 4 Tagen pro Woche. Wie viele Tage gesetzlichen Mindesturlaub hat sie im Jahr?","erklaerung":"Der gesetzliche Urlaub beträgt 24 Werktage bei einer 6-Tage-Woche. Bei weniger Arbeitstagen rechnet man anteilig um.","loesung":"24 Werktage ÷ 6 × 4 Arbeitstage = 16 Urlaubstage","einheit":"Tage"}},{"id":"ar-05","typ":"single","frage":"For how long does the employer continue to pay wages during illness?","optionen":["3 days","2 weeks","6 weeks","6 months"],"fest":true,"richtig":2,"erklaerung":"Up to 6 weeks, then sickness benefit from the health insurer. Condition: 4 weeks of uninterrupted employment.","quelle":"§ 3 EFZG","lc":true,"lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Wie lange zahlt der Arbeitgeber den Lohn bei Krankheit weiter?","erklaerung":"Bis zu 6 Wochen, danach Krankengeld der Krankenkasse. Voraussetzung: 4 Wochen ununterbrochene Beschäftigung.","optionen":["3 Tage","2 Wochen","6 Wochen","6 Monate"]}},{"id":"ar-06","typ":"single","frage":"How must a dismissal be given to be valid?","optionen":["Orally is enough if there is a witness.","In writing with a handwritten signature; email or text message is not enough.","By email with read receipt","By WhatsApp, if the recipient sees the tick"],"richtig":1,"erklaerung":"Termination by dismissal requires written form; electronic form is excluded.","quelle":"§ 623 BGB","lc":true,"lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Wie muss eine Kündigung erfolgen, damit sie wirksam ist?","erklaerung":"Die Beendigung durch Kündigung bedarf der Schriftform; die elektronische Form ist ausgeschlossen.","optionen":["Mündlich reicht, wenn ein Zeuge dabei ist.","Schriftlich mit eigenhändiger Unterschrift; E-Mail oder SMS reichen nicht.","Per E-Mail mit Lesebestätigung","Per WhatsApp, wenn der Empfänger den Haken sieht"]}},{"id":"ar-07","typ":"single","frage":"Which notice period applies during probation?","optionen":["1 week","2 weeks","4 weeks to the 15th or end of month","1 month"],"richtig":1,"erklaerung":"During an agreed probation period of at most 6 months, notice can be given with 2 weeks.","quelle":"§ 622 Abs. 3 BGB","lc":true,"lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Welche Kündigungsfrist gilt in der Probezeit?","erklaerung":"Während einer vereinbarten Probezeit von höchstens 6 Monaten kann mit einer Frist von 2 Wochen gekündigt werden.","optionen":["1 Woche","2 Wochen","4 Wochen zum 15. oder Monatsende","1 Monat"]}},{"id":"ar-08","typ":"single","frage":"What is the statutory basic notice period?","optionen":["2 weeks to the end of the month","4 weeks to the 15th or the end of a calendar month","3 months to the end of the quarter","6 weeks to the end of the quarter"],"richtig":1,"erklaerung":"The basic period applies to employees and employers. With longer service it increases for dismissals by the employer.","quelle":"§ 622 Abs. 1 BGB","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Was ist die gesetzliche Grundkündigungsfrist?","erklaerung":"Die Grundfrist gilt für Arbeitnehmer und Arbeitgeber. Bei längerer Betriebszugehörigkeit verlängert sie sich für Kündigungen durch den Arbeitgeber.","optionen":["2 Wochen zum Monatsende","4 Wochen zum 15. oder zum Ende eines Kalendermonats","3 Monate zum Quartalsende","6 Wochen zum Quartalsende"]}},{"id":"ar-09","typ":"single","frage":"A driver has been with the company for 8 years. The employer gives ordinary notice. Which period applies at least?","optionen":["4 weeks to the 15th or end of month","1 month to the end of the month","3 months to the end of a calendar month","7 months to the end of the month"],"richtig":2,"erklaerung":"After 8 years of service: 3 months to the end of a calendar month.","quelle":"§ 622 Abs. 2 BGB","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Ein Fahrer ist seit 8 Jahren im Betrieb. Der Arbeitgeber kündigt ordentlich. Welche Frist gilt mindestens?","erklaerung":"Nach 8 Jahren Betriebszugehörigkeit: 3 Monate zum Ende eines Kalendermonats.","optionen":["4 Wochen zum 15. oder Monatsende","1 Monat zum Monatsende","3 Monate zum Ende eines Kalendermonats","7 Monate zum Monatsende"]}},{"id":"ar-10","typ":"multi","frage":"What applies to a fixed-term contract without an objective reason? Select all correct answers.","optionen":["Maximum duration 2 years","At most 3 extensions within this time","Must be agreed in writing before work starts","Can be extended as often as you like","Orally is enough"],"richtig":[0,1,2],"erklaerung":"Without written form the contract is deemed open-ended.","quelle":"§§ 14, 16 TzBfG","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Was gilt für eine Befristung ohne sachlichen Grund? Wähle alle richtigen.","erklaerung":"Ohne Schriftform gilt der Vertrag als unbefristet.","optionen":["Höchstdauer 2 Jahre","Höchstens 3 Verlängerungen innerhalb dieser Zeit","Muss schriftlich vor Arbeitsbeginn vereinbart werden","Unbegrenzt oft verlängerbar","Mündlich reicht"]}},{"id":"ar-11","typ":"single","frage":"When does the Protection Against Dismissal Act (KSchG) apply?","optionen":["In every business from day one","With more than 10 employees in the business and an employment of more than 6 months","Only to civil servants","Only in businesses with a works council"],"richtig":1,"erklaerung":"Threshold: more than 10 employees (§ 23 KSchG), waiting period: more than 6 months (§ 1 KSchG).","quelle":"§§ 1, 23 KSchG","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Wann gilt das Kündigungsschutzgesetz?","erklaerung":"Schwellenwert: mehr als 10 Arbeitnehmer (§ 23 KSchG), Wartezeit: mehr als 6 Monate (§ 1 KSchG).","optionen":["In jedem Betrieb ab dem ersten Tag","Bei mehr als 10 Arbeitnehmern im Betrieb und einem Arbeitsverhältnis von mehr als 6 Monaten","Nur für Beamte","Nur bei Betrieben mit Betriebsrat"]}},{"id":"ar-12","typ":"single","frage":"Within which period must a summary dismissal be given after learning of the reason?","optionen":["3 days","2 weeks","1 month","3 months"],"fest":true,"richtig":1,"erklaerung":"Dismissal for an important reason can only be given within two weeks of learning the relevant facts.","quelle":"§ 626 Abs. 2 BGB","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Innerhalb welcher Frist muss eine fristlose Kündigung nach Kenntnis des Grundes ausgesprochen werden?","erklaerung":"Die Kündigung aus wichtigem Grund kann nur innerhalb von zwei Wochen ab Kenntnis der maßgebenden Tatsachen erfolgen.","optionen":["3 Tage","2 Wochen","1 Monat","3 Monate"]}},{"id":"ar-13","typ":"tf","frage":"The minimum wage does not apply to mini-jobbers.","richtig":false,"erklaerung":"The minimum wage also applies to marginal employment. The recording duty under § 17 MiLoG also applies to them.","quelle":"MiLoG","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Für Minijobber gilt der Mindestlohn nicht.","erklaerung":"Der Mindestlohn gilt auch für geringfügig Beschäftigte. Außerdem gilt für sie die Aufzeichnungspflicht nach § 17 MiLoG."}},{"id":"ar-14","typ":"single","frage":"What is the mini-job earnings limit in 2026?","optionen":["520 €","556 €","603 €","700 €"],"fest":true,"richtig":2,"erklaerung":"The limit is calculated from the minimum wage: 13,90 € × 130 ÷ 3 = 602,33 €, rounded up to 603 €.","quelle":"§ 8 Abs. 1a SGB IV","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Wie hoch ist die Minijob-Grenze im Jahr 2026?","erklaerung":"Die Grenze wird aus dem Mindestlohn berechnet: 13,90 € × 130 ÷ 3 = 602,33 €, aufgerundet 603 €.","optionen":["520 €","556 €","603 €","700 €"]}},{"id":"ar-15","typ":"single","frage":"How long are the protection periods under the Maternity Protection Act?","optionen":["2 weeks before and 4 weeks after birth","6 weeks before and 8 weeks after birth","3 months before and 3 months after birth","Only 8 weeks after birth"],"richtig":1,"erklaerung":"6 weeks before and 8 weeks after birth (longer for premature or multiple births).","quelle":"§ 3 MuSchG","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Wie lange sind Schutzfristen nach dem Mutterschutzgesetz?","erklaerung":"6 Wochen vor und 8 Wochen nach der Entbindung (bei Früh- und Mehrlingsgeburten länger).","optionen":["2 Wochen vor und 4 Wochen nach der Geburt","6 Wochen vor und 8 Wochen nach der Geburt","3 Monate vor und 3 Monate nach der Geburt","Nur 8 Wochen nach der Geburt"]}},{"id":"ar-16","typ":"tf","frage":"Anyone who wants to fight a dismissal must file a claim at the labour court within 3 weeks of receiving it.","richtig":true,"erklaerung":"Deadline under § 4 KSchG.","quelle":"§ 4 KSchG","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Wer sich gegen eine Kündigung wehren will, muss innerhalb von 3 Wochen nach Zugang Klage beim Arbeitsgericht erheben.","erklaerung":"Klagefrist nach § 4 KSchG."}},{"id":"ar-17","typ":"offen","frage":"A taxi operator hires a driver on a mini-job basis. What employment law duties does he have? Name at least four.","muster":"<ul><li>Pay the minimum wage (13,90 € from 2026), earnings up to 603 € per month</li><li>Record working time (start, end, length) by day 7 and keep it 2 years (§ 17 MiLoG)</li><li>Written statement of working conditions (NachwG), in the taxi trade with signature</li><li>Grant proportional holidays (BUrlG), sick pay (EFZG)</li><li>Immediate notification and registration with the Minijob-Zentrale</li><li>Tell the driver about the ID duty (§ 2a SchwarzArbG), check the P-Schein</li></ul>","punkte_liste":[{"t":"Minimum wage / mini-job limit","p":1},{"t":"Record working time (7 days, 2 years)","p":1},{"t":"Written statement of working conditions","p":1},{"t":"Holidays and/or sick pay","p":1},{"t":"Another duty (Minijob-Zentrale/immediate notification, ID, P-Schein)","p":1}],"quelle":"MiLoG, NachwG, BUrlG, EFZG, SchwarzArbG","lek":"arbeitsrecht","sg":"1.4","de":{"frage":"Ein Taxiunternehmer stellt einen Fahrer auf Minijob-Basis ein. Welche arbeitsrechtlichen Pflichten hat er? Nennen Sie mindestens vier.","muster":"<ul><li>Mindestlohn zahlen (13,90 € ab 2026), Verdienst bis 603 € im Monat</li><li>Arbeitszeit (Beginn, Ende, Dauer) bis zum 7. Tag aufzeichnen und 2 Jahre aufbewahren (§ 17 MiLoG)</li><li>Wesentliche Arbeitsbedingungen schriftlich nachweisen (NachwG), im Taxigewerbe mit Unterschrift</li><li>Urlaub anteilig gewähren (BUrlG), Lohnfortzahlung bei Krankheit (EFZG)</li><li>Sofortmeldung und Anmeldung bei der Minijob-Zentrale</li><li>Fahrer auf Ausweispflicht hinweisen (§ 2a SchwarzArbG), P-Schein prüfen</li></ul>","punkte_liste":["Mindestlohn / Minijob-Grenze","Arbeitszeit aufzeichnen (7 Tage, 2 Jahre)","Schriftlicher Nachweis der Arbeitsbedingungen","Urlaub und/oder Lohnfortzahlung","Weitere Pflicht (Anmeldung Minijob-Zentrale/Sofortmeldung, Ausweis, P-Schein)"]}},{"id":"az-01","typ":"single","frage":"An employed taxi driver works 9 hours and 30 minutes. How long must his break be at least?","optionen":["15 minutes","30 minutes","45 minutes","60 minutes"],"fest":true,"richtig":2,"erklaerung":"With more than 9 hours of working time at least 45 minutes. With more than 6 up to 9 hours, 30 minutes.","quelle":"§ 4 ArbZG","lc":true,"lek":"arbeitszeit","sg":"1.4","de":{"frage":"Ein angestellter Taxifahrer arbeitet 9 Stunden und 30 Minuten. Wie lang muss seine Pause mindestens sein?","erklaerung":"Bei mehr als 9 Stunden Arbeitszeit mindestens 45 Minuten. Bei mehr als 6 bis 9 Stunden 30 Minuten.","optionen":["15 Minuten","30 Minuten","45 Minuten","60 Minuten"]}},{"id":"az-02","typ":"single","frage":"A driver ends his shift at 2:00 am. When may he start again at the earliest if no shortening is used?","optionen":["8:00 am","11:00 am","1:00 pm","2:00 pm"],"fest":true,"richtig":2,"erklaerung":"Uninterrupted rest period of at least 11 hours: 2:00 + 11 h = 1:00 pm. In a transport company 12:00 would also be possible with compensation.","quelle":"§ 5 ArbZG","lc":true,"lek":"arbeitszeit","sg":"1.4","de":{"frage":"Ein Fahrer beendet seine Schicht um 2:00 Uhr. Wann darf er frühestens wieder anfangen, wenn keine Verkürzung genutzt wird?","erklaerung":"Ununterbrochene Ruhezeit von mindestens 11 Stunden: 2:00 + 11 h = 13:00 Uhr. Im Verkehrsbetrieb wäre mit Ausgleich auch 12:00 Uhr möglich.","optionen":["8:00 Uhr","11:00 Uhr","13:00 Uhr","14:00 Uhr"]}},{"id":"az-03","typ":"multi","frage":"What applies to Sunday work by employed taxi drivers? Select all correct answers.","optionen":["It is generally allowed in transport companies.","At least 15 Sundays per year must stay free.","For a working Sunday there is a substitute day off within 2 weeks.","Sunday work is forbidden for taxi drivers.","There is never compensation for Sunday work."],"richtig":[0,1,2],"erklaerung":"§ 10 (1) No. 10 ArbZG allows Sunday work in transport companies; § 11 regulates the compensation.","quelle":"§§ 10, 11 ArbZG","lc":true,"lek":"arbeitszeit","sg":"1.4","de":{"frage":"Was gilt für Sonntagsarbeit von angestellten Taxifahrern? Wähle alle richtigen.","erklaerung":"§ 10 Abs. 1 Nr. 10 ArbZG erlaubt Sonntagsarbeit in Verkehrsbetrieben; § 11 regelt den Ausgleich.","optionen":["Sie ist in Verkehrsbetrieben grundsätzlich erlaubt.","Mindestens 15 Sonntage im Jahr müssen frei bleiben.","Für einen Arbeitssonntag gibt es einen Ersatzruhetag innerhalb von 2 Wochen.","Sonntagsarbeit ist für Taxifahrer verboten.","Für Sonntagsarbeit gibt es nie einen Ausgleich."]}},{"id":"az-04","typ":"tf","frage":"Taxis must have a tachograph because the EU driving and rest times (Reg. 561/2006) apply to them.","richtig":false,"erklaerung":"Reg. 561/2006 only applies in passenger transport to vehicles for more than 9 persons including the driver. Taxis and Mietwagen are not covered. For employed drivers the ArbZG applies.","quelle":"Art. 2 VO (EG) 561/2006","lc":true,"lek":"arbeitszeit","sg":"1.4","de":{"frage":"Taxis müssen einen Fahrtenschreiber haben, weil für sie die EU-Lenk- und Ruhezeiten (VO 561/2006) gelten.","erklaerung":"Die VO 561/2006 gilt im Personenverkehr nur für Fahrzeuge für mehr als 9 Personen einschließlich Fahrer. Taxis und Mietwagen fallen nicht darunter. Für angestellte Fahrer gilt das ArbZG."}},{"id":"az-05","typ":"single","frage":"How long may an employee work on a working day at most?","optionen":["8 hours, without exception","10 hours, if an average of 8 hours per working day is not exceeded over 6 months or 24 weeks","12 hours","Unlimited if he agrees"],"richtig":1,"erklaerung":"Rule: 8 hours; extension to 10 hours with compensation.","quelle":"§ 3 ArbZG","lek":"arbeitszeit","sg":"1.4","de":{"frage":"Wie lange darf ein Arbeitnehmer an einem Werktag höchstens arbeiten?","erklaerung":"Regel 8 Stunden; Verlängerung auf 10 Stunden mit Ausgleich.","optionen":["8 Stunden, ohne Ausnahme","10 Stunden, wenn im Durchschnitt von 6 Monaten oder 24 Wochen 8 Stunden pro Werktag nicht überschritten werden","12 Stunden","Unbegrenzt, wenn er zustimmt"]}},{"id":"az-06","typ":"single","frage":"By how much may the rest period be shortened in transport companies, and how is it balanced?","optionen":["By 3 hours, no compensation needed","By 1 hour; compensation by another rest period of at least 12 hours within one calendar month or 4 weeks","By 2 hours; compensation within one year","Not at all"],"richtig":1,"erklaerung":"§ 5 (2) ArbZG expressly names transport companies.","quelle":"§ 5 Abs. 2 ArbZG","lek":"arbeitszeit","sg":"1.4","de":{"frage":"Um wie viel darf die Ruhezeit in Verkehrsbetrieben verkürzt werden, und wie wird ausgeglichen?","erklaerung":"§ 5 Abs. 2 ArbZG nennt ausdrücklich Verkehrsbetriebe.","optionen":["Um 3 Stunden, kein Ausgleich nötig","Um 1 Stunde; Ausgleich durch eine andere Ruhezeit von mindestens 12 Stunden innerhalb eines Kalendermonats oder 4 Wochen","Um 2 Stunden; Ausgleich innerhalb eines Jahres","Gar nicht"]}},{"id":"az-07","typ":"tf","frage":"The Working Hours Act also applies to the self-employed taxi operator who drives himself.","richtig":false,"erklaerung":"The ArbZG applies to employees. Self-employed people are not covered.","quelle":"§ 2 Abs. 2 ArbZG","lek":"arbeitszeit","sg":"1.4","de":{"frage":"Das Arbeitszeitgesetz gilt auch für den selbständigen Taxiunternehmer, der selbst fährt.","erklaerung":"Das ArbZG gilt für Arbeitnehmer. Selbständige fallen nicht darunter."}},{"id":"az-08","typ":"single","frage":"Which period is night time under the ArbZG?","optionen":["8 pm to 4 am","10 pm to 5 am","11 pm to 6 am","midnight to 6 am"],"fest":true,"richtig":2,"erklaerung":"Night time is from 11 pm to 6 am. Night work is work covering more than 2 hours of night time.","quelle":"§ 2 Abs. 3 und 4 ArbZG","lek":"arbeitszeit","sg":"1.4","de":{"frage":"Welcher Zeitraum ist nach dem ArbZG die Nachtzeit?","erklaerung":"Nachtzeit ist die Zeit von 23 bis 6 Uhr. Nachtarbeit ist Arbeit, die mehr als 2 Stunden der Nachtzeit umfasst.","optionen":["20 bis 4 Uhr","22 bis 5 Uhr","23 bis 6 Uhr","0 bis 6 Uhr"]}},{"id":"az-09","typ":"tf","frage":"Waiting time at the taxi rank, during which the driver must be ready to leave at any time, counts as a break.","richtig":false,"erklaerung":"A break is an interruption fixed in advance during which the employee is free. Standby at the rank is working time.","quelle":"§ 4 ArbZG","lek":"arbeitszeit","sg":"1.4","de":{"frage":"Wartezeit am Taxistand, in der der Fahrer jederzeit losfahren muss, zählt als Pause.","erklaerung":"Eine Pause ist eine im Voraus feststehende Unterbrechung, in der der Arbeitnehmer frei ist. Bereitschaft am Stand ist Arbeitszeit."}},{"id":"az-10","typ":"zahl","frage":"A driver starts at 4:00 pm and finishes at 2:15 am. He takes a 45-minute break. How long is his working time in hours? (e.g. 8,5)","richtig":9.5,"einheit":"h","tol":0.01,"loesung":"4:00 pm to 2:15 am = 10 h 15 min\n10 h 15 min − 45 min break = 9 h 30 min = 9,5 h","erklaerung":"Working time = time from start to end without breaks. 9.5 h is over 8 h: only allowed with compensation, and the 45-minute break is required.","quelle":"§§ 2–4 ArbZG","lek":"arbeitszeit","sg":"1.4","de":{"frage":"Ein Fahrer beginnt um 16:00 Uhr und hört um 2:15 Uhr auf. Er macht 45 Minuten Pause. Wie lang ist seine Arbeitszeit in Stunden? (z. B. 8,5)","erklaerung":"Arbeitszeit = Zeit von Beginn bis Ende ohne Pausen. 9,5 h liegt über 8 h: nur mit Ausgleich erlaubt, und die Pause von 45 min ist nötig.","loesung":"16:00 bis 2:15 = 10 h 15 min\n10 h 15 min − 45 min Pause = 9 h 30 min = 9,5 h","einheit":"h"}},{"id":"az-11","typ":"offen","frage":"Explain the rules of the Working Hours Act on maximum working time, breaks and rest periods for employed taxi drivers.","muster":"<p>Maximum working time: 8 hours per working day, up to 10 hours if an average of 8 hours is not exceeded within 6 months or 24 weeks (§ 3). Breaks: more than 6 hours at least 30 minutes, more than 9 hours 45 minutes, in parts of at least 15 minutes; no more than 6 hours without a break (§ 4). Rest period: at least 11 hours uninterrupted; in transport companies it can be shortened by 1 hour, balanced to 12 hours within one month or 4 weeks (§ 5).</p><p lang=\"de\"><i>Key German terms: Höchstarbeitszeit, Ruhepause, Ruhezeit, Verkehrsbetrieb, Ausgleich.</i></p>","punkte_liste":[{"t":"8 hours, up to 10 hours with compensation (6 months/24 weeks)","p":1},{"t":"Breaks 30 min (> 6 h) / 45 min (> 9 h)","p":1},{"t":"Break parts 15 min, max. 6 h without break","p":1},{"t":"Rest period 11 h","p":1},{"t":"Transport company: shortening by 1 h, compensation to 12 h","p":1}],"quelle":"§§ 3–5 ArbZG","lek":"arbeitszeit","sg":"1.4","de":{"frage":"Erläutern Sie die Regeln des Arbeitszeitgesetzes zu Höchstarbeitszeit, Pausen und Ruhezeit für angestellte Taxifahrer.","muster":"<p>Höchstarbeitszeit: 8 Stunden pro Werktag, bis zu 10 Stunden, wenn innerhalb von 6 Monaten oder 24 Wochen im Durchschnitt 8 Stunden nicht überschritten werden (§ 3). Pausen: mehr als 6 Stunden mindestens 30 Minuten, mehr als 9 Stunden 45 Minuten, in Abschnitten von mindestens 15 Minuten; nicht länger als 6 Stunden ohne Pause (§ 4). Ruhezeit: mindestens 11 Stunden ununterbrochen; in Verkehrsbetrieben Verkürzung um 1 Stunde möglich, Ausgleich auf 12 Stunden innerhalb eines Monats oder 4 Wochen (§ 5).</p>","punkte_liste":["8 Stunden, bis 10 Stunden mit Ausgleich (6 Monate/24 Wochen)","Pausen 30 min (> 6 h) / 45 min (> 9 h)","Pausenabschnitte 15 min, max. 6 h ohne Pause","Ruhezeit 11 h","Verkehrsbetrieb: Verkürzung um 1 h, Ausgleich auf 12 h"]}},{"id":"au-01","typ":"zuordnung","frage":"What applies to whom?","kategorien":["taxi only","Mietwagen only","both"],"paare":[{"t":"Alarm system, triggered from the driver's seat","k":2,"w":"§ 25 (2) BOKraft applies to taxis and Mietwagen."},{"t":"Navigation device with real-time traffic data","k":0,"w":"§ 28a BOKraft: taxis."},{"t":"Distance meter","k":1,"w":"§ 30 BOKraft."},{"t":"At least 2 doors on the right-hand side","k":2,"w":"§ 25 (1) BOKraft."},{"t":"Space for at least 50 kg of luggage when fully occupied","k":0,"w":"§ 29 BOKraft."},{"t":"Licence number on the rear window","k":2,"w":"§ 27 BOKraft."}],"erklaerung":"For Mietwagen §§ 25, 27, 30 BOKraft apply (§ 31).","quelle":"BOKraft","lc":true,"lek":"ausruestung","sg":"3.3","de":{"frage":"Was gilt für wen?","erklaerung":"Für Mietwagen gelten §§ 25, 27, 30 BOKraft (§ 31).","kategorien":["nur Taxi","nur Mietwagen","beide"],"paare":["Alarmanlage, vom Fahrersitz auslösbar","Navigationsgerät mit Echtzeit-Verkehrsdaten","Wegstreckenzähler","Mindestens 2 Türen auf der rechten Seite","Platz für mindestens 50 kg Gepäck bei voller Besetzung","Ordnungsnummer an der Heckscheibe"]}},{"id":"au-02","typ":"single","frage":"What must the alarm system in a taxi be able to do?","optionen":["Only call the police","Triggered from the driver's seat: horn sounds at intervals, headlights and rear indicators flash","Only make the taxi sign light up red","Lock the doors"],"richtig":1,"erklaerung":"§ 25 (2) BOKraft. The taxi sign may also flash, but this is not mandatory.","quelle":"§ 25 BOKraft","lc":true,"lek":"ausruestung","sg":"3.3","de":{"frage":"Was muss die Alarmanlage in einem Taxi können?","erklaerung":"§ 25 Abs. 2 BOKraft. Das Taxischild darf zusätzlich blinken, das ist aber nicht Pflicht.","optionen":["Nur die Polizei anrufen","Vom Fahrersitz auslösbar: Hupe ertönt im Intervall, Scheinwerfer und hintere Blinker blinken","Nur das Taxischild rot leuchten lassen","Die Türen verriegeln"]}},{"id":"au-03","typ":"single","frage":"What is the legal minimum tyre tread depth?","optionen":["1,0 mm","1,6 mm","3,0 mm","4,0 mm"],"fest":true,"richtig":1,"erklaerung":"1,6 mm under § 36 StVZO. Recommended: 3 mm (summer) or 4 mm (winter).","quelle":"§ 36 Abs. 2 StVZO","lc":true,"lek":"ausruestung","sg":"3.3","de":{"frage":"Wie tief muss das Reifenprofil gesetzlich mindestens sein?","erklaerung":"1,6 mm nach § 36 StVZO. Empfohlen werden 3 mm (Sommer) bzw. 4 mm (Winter).","optionen":["1,0 mm","1,6 mm","3,0 mm","4,0 mm"]}},{"id":"au-04","typ":"tf","frage":"A partition between driver and passengers is mandatory in taxis.","richtig":false,"erklaerung":"A partition is allowed. If fitted, it must be sufficiently bullet-resistant.","quelle":"§ 25 Abs. 3 BOKraft","lek":"ausruestung","sg":"3.3","de":{"frage":"Eine Trennwand zwischen Fahrer und Fahrgästen ist in Taxis vorgeschrieben.","erklaerung":"Eine Trennwand ist erlaubt. Wenn eingebaut, muss sie ausreichend schusshemmend sein."}},{"id":"au-05","typ":"multi","frage":"What is part of the mandatory equipment of every car? Select all correct answers.","optionen":["First-aid kit","Warning triangle","High-visibility vest","Fire extinguisher","Tow rope"],"richtig":[0,1,2],"erklaerung":"Fire extinguishers are mandatory for buses. § 18 BOKraft only requires a tow rope if circumstances demand it.","quelle":"§§ 35h, 53a StVZO","lek":"ausruestung","sg":"3.3","de":{"frage":"Was gehört zur Pflichtausrüstung jedes Pkw? Wähle alle richtigen.","erklaerung":"Feuerlöscher sind für Busse Pflicht. Ein Abschleppseil verlangt § 18 BOKraft nur, wenn die Umstände es erfordern.","optionen":["Verbandkasten","Warndreieck","Warnweste","Feuerlöscher","Abschleppseil"]}},{"id":"au-06","typ":"tf","frage":"Since October 2024 only tyres with the Alpine symbol count as winter-suitable.","richtig":true,"erklaerung":"The transition period for pure M+S tyres ended on 30.9.2024.","quelle":"§ 36 Abs. 4 StVZO, § 2 Abs. 3a StVO","lek":"ausruestung","sg":"3.3","de":{"frage":"Seit Oktober 2024 gelten nur noch Reifen mit Alpine-Symbol als wintertauglich.","erklaerung":"Die Übergangsfrist für reine M+S-Reifen ist am 30.9.2024 abgelaufen."}},{"id":"au-07","typ":"single","frage":"A vehicle has licences as a taxi and as a Mietwagen. It is currently driving a Mietwagen booking. What applies to the taxi sign?","optionen":["It must be lit.","It must not be used.","It must flash red.","It doesn't matter."],"richtig":1,"erklaerung":"When used in Mietwagen transport the taxi sign must not be used (§ 31 BOKraft).","quelle":"§ 31 BOKraft","lek":"ausruestung","sg":"3.3","de":{"frage":"Ein Fahrzeug hat Genehmigungen als Taxi und als Mietwagen. Es fährt gerade einen Mietwagenauftrag. Was gilt für das Taxischild?","erklaerung":"Bei Verwendung im Mietwagenverkehr darf das Taxischild nicht verwendet werden (§ 31 BOKraft).","optionen":["Es muss leuchten.","Es darf nicht benutzt werden.","Es muss rot blinken.","Egal"]}},{"id":"au-08","typ":"offen","frage":"Name six equipment features that a taxi must have under BOKraft.","muster":"<ul><li>At least 2 doors on the right (§ 25)</li><li>Alarm system (§ 25)</li><li>Light ivory RAL 1015 (§ 26)</li><li>Illuminated taxi sign (§ 26)</li><li>Licence number and operator's address (§ 27)</li><li>Calibrated taximeter (§ 28)</li><li>Navigation device with real-time data (§ 28a)</li><li>50 kg luggage when fully occupied (§ 29)</li></ul><p lang=\"de\"><i>Key German terms: Alarmanlage, hell-elfenbein, Taxischild, Ordnungsnummer, Fahrpreisanzeiger.</i></p>","punkte_liste":[{"t":"Two correct features","p":1},{"t":"Four correct features","p":1},{"t":"Six correct features","p":1}],"quelle":"§§ 25–29 BOKraft","lek":"ausruestung","sg":"3.3","de":{"frage":"Nennen Sie sechs Ausrüstungsmerkmale, die ein Taxi nach der BOKraft haben muss.","muster":"<ul><li>Mindestens 2 Türen rechts (§ 25)</li><li>Alarmanlage (§ 25)</li><li>Hell-elfenbein RAL 1015 (§ 26)</li><li>Beleuchtetes Taxischild (§ 26)</li><li>Ordnungsnummer und Unternehmeranschrift (§ 27)</li><li>Geeichter Fahrpreisanzeiger (§ 28)</li><li>Navigationsgerät mit Echtzeitdaten (§ 28a)</li><li>50 kg Gepäck bei voller Besetzung (§ 29)</li></ul>","punkte_liste":["Zwei richtige Merkmale","Vier richtige Merkmale","Sechs richtige Merkmale"]}},{"id":"bf-01","typ":"single","frage":"From which limits is a trader obliged to keep books under § 141 AO?","optionen":["Turnover over 100.000 € or profit over 25.000 €","Turnover over 800.000 € or profit over 80.000 €","From 2 vehicles","From the first employee"],"richtig":1,"erklaerung":"Since 2024 the limits are 800.000 € turnover or 80.000 € profit. Merchants under the HGB must keep books regardless (sole merchants below these limits can be exempt).","quelle":"§ 141 AO","lc":true,"lek":"buchfuehrung","sg":"2.5","de":{"frage":"Ab welchen Grenzen ist ein Gewerbetreibender nach § 141 AO zur Buchführung verpflichtet?","erklaerung":"Seit 2024 gelten 800.000 € Umsatz oder 80.000 € Gewinn. Kaufleute nach HGB sind unabhängig davon buchführungspflichtig (Einzelkaufleute unter diesen Grenzen können befreit sein).","optionen":["Umsatz über 100.000 € oder Gewinn über 25.000 €","Umsatz über 800.000 € oder Gewinn über 80.000 €","Ab 2 Fahrzeugen","Ab dem ersten Angestellten"]}},{"id":"bf-02","typ":"zuordnung","frage":"How long must you keep it?","kategorien":["6 years","8 years","10 years"],"paare":[{"t":"Fuel receipt","k":1,"w":"Accounting voucher: 8 years (since 2025)."},{"t":"Annual accounts / balance sheet","k":2,"w":"Books and accounts: 10 years."},{"t":"Cash book","k":2,"w":"Books and records: 10 years."},{"t":"Email with a quote to a business customer","k":0,"w":"Business letter: 6 years."},{"t":"Garage invoice","k":1,"w":"Accounting voucher: 8 years."}],"erklaerung":"The period always starts at the end of the calendar year.","quelle":"§ 147 AO","lc":true,"lek":"buchfuehrung","sg":"2.5","de":{"frage":"Wie lange musst du aufbewahren?","erklaerung":"Die Frist beginnt jeweils am Ende des Kalenderjahres.","kategorien":["6 Jahre","8 Jahre","10 Jahre"],"paare":["Tankquittung","Jahresabschluss / Bilanz","Kassenbuch","E-Mail mit einem Angebot an einen Firmenkunden","Werkstattrechnung"]}},{"id":"bf-03","typ":"zahl","frage":"The cash book in the lesson shows a balance of 133,90 € at the end of 01.03. On 02.03. cash receipts of 268,10 € are added. What is the new cash balance?","richtig":402,"einheit":"€","tol":0.005,"loesung":"133,90 € + 268,10 € = 402,00 €","erklaerung":"Balance + receipts − payments.","quelle":"Kassenbuch","lc":true,"lek":"buchfuehrung","sg":"2.5","de":{"frage":"Im Kassenbuch der Lektion steht am Ende des 01.03. ein Bestand von 133,90 €. Am 02.03. kommen 268,10 € Bareinnahmen dazu. Wie hoch ist der neue Kassenbestand?","erklaerung":"Bestand + Einnahmen − Ausgaben.","loesung":"133,90 € + 268,10 € = 402,00 €","einheit":"€"}},{"id":"bf-04","typ":"multi","frage":"What applies to a proper cash book? Select all correct answers.","optionen":["Kept daily and promptly","The cash balance may never be negative","The counted cash must match the book (ready for a cash count)","A monthly total of all receipts is enough","Changes with correction fluid are allowed if they look tidy"],"richtig":[0,1,2],"erklaerung":"Cash transactions must be recorded individually and daily. Changes must remain visible.","quelle":"§ 146 AO, GoBD","lc":true,"lek":"buchfuehrung","sg":"2.5","de":{"frage":"Was gilt für ein ordnungsgemäßes Kassenbuch? Wähle alle richtigen.","erklaerung":"Bargeschäfte sind einzeln und täglich aufzuzeichnen. Änderungen müssen erkennbar bleiben.","optionen":["Täglich und zeitnah führen","Der Kassenbestand darf nie negativ sein","Der gezählte Bestand muss mit dem Buch übereinstimmen (Kassensturzfähigkeit)","Am Monatsende reicht eine Summe aller Einnahmen","Änderungen mit Tipp-Ex sind erlaubt, wenn sie ordentlich aussehen"]}},{"id":"bf-05","typ":"single","frage":"In December 2026 a taxi operator sends a collective invoice to a health insurer. It pays on 20 January 2027. When is this business income in the EÜR?","optionen":["2026, because the trips were in 2026","2027, because the money arrives in 2027","Half each","Not at all"],"richtig":1,"erklaerung":"Cash principle under § 11 EStG. The 10-day rule only applies to regularly recurring income and only up to 10 January.","quelle":"§ 11 EStG","lc":true,"lek":"buchfuehrung","sg":"2.5","de":{"frage":"Ein Taxiunternehmer schickt im Dezember 2026 eine Sammelrechnung an eine Krankenkasse. Sie zahlt am 20. Januar 2027. Wann ist das bei der EÜR eine Betriebseinnahme?","erklaerung":"Zuflussprinzip nach § 11 EStG. Die 10-Tage-Regel gilt nur für regelmäßig wiederkehrende Einnahmen und nur bis 10. Januar.","optionen":["2026, weil die Fahrten 2026 waren","2027, weil das Geld 2027 zufließt","Je zur Hälfte","Gar nicht"]}},{"id":"bf-06","typ":"zahl","frage":"A taxi for 40.000 € net is bought on 1 July. Useful life according to the depreciation table: 5 years. What is the depreciation in the year of purchase?","richtig":4000,"einheit":"€","tol":0.5,"loesung":"40.000 € ÷ 5 = 8.000 € per year\nJuly to December = 6 months\n8.000 € × 6/12 = 4.000 €","erklaerung":"In the year of purchase pro rata by full months. For tax without residual value.","quelle":"§ 7 EStG","lc":true,"lek":"buchfuehrung","sg":"2.5","de":{"frage":"Ein Taxi für 40.000 € netto wird am 1. Juli angeschafft. Nutzungsdauer laut AfA-Tabelle: 5 Jahre. Wie hoch ist die AfA im Anschaffungsjahr?","erklaerung":"Im Anschaffungsjahr zeitanteilig nach vollen Monaten. Steuerlich ohne Restwert.","loesung":"40.000 € ÷ 5 = 8.000 € pro Jahr\nJuli bis Dezember = 6 Monate\n8.000 € × 6/12 = 4.000 €","einheit":"€"}},{"id":"bf-07","typ":"single","frage":"Which booking entry is correct? The operator takes 600 € cash from the till to the bank.","optionen":["Cash to bank 600 €","Bank to cash 600 €","Revenue to cash 600 €","Private to bank 600 €"],"richtig":1,"erklaerung":"The bank account increases (debit), cash decreases (credit): bank to cash.","quelle":"Buchungssatz","lc":true,"lek":"buchfuehrung","sg":"2.5","de":{"frage":"Welcher Buchungssatz ist richtig? Der Unternehmer bringt 600 € Bargeld aus der Kasse zur Bank.","erklaerung":"Das Bankkonto nimmt zu (Soll), die Kasse nimmt ab (Haben): Bank an Kasse.","optionen":["Kasse an Bank 600 €","Bank an Kasse 600 €","Erlöse an Kasse 600 €","Privat an Bank 600 €"]}},{"id":"bf-08","typ":"single","frage":"What is a low-value asset that may be written off immediately?","optionen":["Anything under 5.000 €","An independently usable asset up to 800 € net, e.g. a card terminal","Every used vehicle","Only office supplies"],"richtig":1,"erklaerung":"§ 6 (2) EStG: up to 800 € net immediate deduction.","quelle":"§ 6 Abs. 2 EStG","lek":"buchfuehrung","sg":"2.5","de":{"frage":"Was ist ein geringwertiges Wirtschaftsgut, das sofort abgeschrieben werden darf?","erklaerung":"§ 6 Abs. 2 EStG: bis 800 € netto Sofortabzug.","optionen":["Alles unter 5.000 €","Ein selbständig nutzbares Wirtschaftsgut bis 800 € netto, z. B. ein Kartenterminal","Jedes gebrauchte Fahrzeug","Nur Büromaterial"]}},{"id":"bf-09","typ":"single","frage":"What is the difference between stocktaking (Inventur) and inventory (Inventar)?","optionen":["There is no difference.","Stocktaking is the counting (activity), the inventory is the resulting list.","The inventory is the activity, stocktaking the result.","Stocktaking only concerns vehicles."],"richtig":1,"erklaerung":"Inventur = counting, measuring, valuing. Inventar = detailed list of assets and debts.","quelle":"§ 240 HGB","lek":"buchfuehrung","sg":"2.5","de":{"frage":"Was ist der Unterschied zwischen Inventur und Inventar?","erklaerung":"Inventur = zählen, messen, bewerten. Inventar = ausführliches Verzeichnis von Vermögen und Schulden.","optionen":["Es gibt keinen Unterschied.","Inventur ist die Bestandsaufnahme (Tätigkeit), Inventar das Verzeichnis als Ergebnis.","Inventar ist die Tätigkeit, Inventur das Ergebnis.","Inventur betrifft nur Fahrzeuge."]}},{"id":"bf-10","typ":"tf","frage":"In cash-basis accounting the imputed owner's salary is deducted as a business expense.","richtig":false,"erklaerung":"Imputed costs (owner's salary, imputed interest) only exist in cost accounting. In the EÜR the profit is the owner's income.","quelle":"§ 4 Abs. 3 EStG","lek":"buchfuehrung","sg":"2.5","de":{"frage":"In der Einnahmen-Überschuss-Rechnung wird der kalkulatorische Unternehmerlohn als Betriebsausgabe abgezogen.","erklaerung":"Kalkulatorische Kosten (Unternehmerlohn, kalkulatorische Zinsen) gibt es nur in der Kostenrechnung. In der EÜR ist der Gewinn das Einkommen des Unternehmers."}},{"id":"bf-11","typ":"single","frage":"A receipt is dated 15 May 2026. When may it be destroyed at the earliest?","optionen":["15 May 2034","1 January 2035","1 January 2037","15 May 2036"],"richtig":1,"erklaerung":"Accounting voucher: 8 years from the end of 2026 → end of 2034 → from 1 January 2035.","quelle":"§ 147 Abs. 3 und 4 AO","lek":"buchfuehrung","sg":"2.5","de":{"frage":"Eine Quittung stammt vom 15. Mai 2026. Ab wann darf sie frühestens vernichtet werden?","erklaerung":"Buchungsbeleg: 8 Jahre ab Ende des Kalenderjahres 2026 → Ende 2034 → ab 1. Januar 2035.","optionen":["15. Mai 2034","1. Januar 2035","1. Januar 2037","15. Mai 2036"]}},{"id":"bf-12","typ":"offen","frage":"Name the requirements for proper cash management in a taxi business.","muster":"<ul><li>Record every cash receipt individually (taximeter with TSE)</li><li>Cash book daily and promptly, chronological, with vouchers</li><li>No negative balance, ready for a cash count</li><li>No invisible changes (GoBD), unalterable software</li><li>Record private withdrawals/deposits and bank deposits</li><li>Keep shift sheets or taximeter data; retention periods (10/8 years)</li><li>Offer a receipt to the passenger</li></ul><p lang=\"de\"><i>Key German terms: Kassenbuch, Einzelaufzeichnungspflicht, Kassensturzfähigkeit, Schichtzettel, GoBD.</i></p>","punkte_liste":[{"t":"Individual records / taximeter with TSE","p":1},{"t":"Daily, prompt, chronological, with vouchers","p":1},{"t":"No negative balance / ready for cash count","p":1},{"t":"Unalterable (GoBD) or retention periods","p":1}],"quelle":"§§ 146, 146a, 147 AO, GoBD","lek":"buchfuehrung","sg":"2.5","de":{"frage":"Nennen Sie die Anforderungen an eine ordnungsgemäße Kassenführung im Taxibetrieb.","muster":"<ul><li>Jede Bareinnahme einzeln aufzeichnen (Einzelaufzeichnungspflicht, Taxameter mit TSE)</li><li>Kassenbuch täglich und zeitnah, chronologisch, mit Belegen</li><li>Kein negativer Kassenbestand, Kassensturzfähigkeit</li><li>Keine unerkennbaren Änderungen (GoBD), unveränderbare Software</li><li>Privatentnahmen/-einlagen und Bankeinzahlungen erfassen</li><li>Schichtzettel bzw. Taxameterdaten aufbewahren; Aufbewahrungsfristen (10/8 Jahre)</li><li>Belegausgabe an den Fahrgast</li></ul>","punkte_liste":["Einzelaufzeichnung / Taxameter mit TSE","täglich, zeitnah, chronologisch, mit Belegen","kein negativer Bestand / kassensturzfähig","Unveränderbarkeit (GoBD) oder Aufbewahrungsfristen"]}},{"id":"da-01","typ":"multi","frage":"Which documents should a taxi driver carry on a trip from Aachen to Liège? Select all correct answers.","optionen":["ID card or passport","Driving licence and P-Schein","Registration certificate part I","Licence or shortened official copy","Registration certificate part II"],"richtig":[0,1,2,3],"erklaerung":"Part II (vehicle title) never belongs in the vehicle.","quelle":"PBefG, FeV, FZV","lc":true,"lek":"dokumente-ausland","sg":"5.3","de":{"frage":"Welche Dokumente sollte ein Taxifahrer bei einer Fahrt von Aachen nach Lüttich dabeihaben? Wähle alle richtigen.","erklaerung":"Teil II (Fahrzeugbrief) gehört nie ins Fahrzeug.","optionen":["Personalausweis oder Reisepass","Führerschein und P-Schein","Zulassungsbescheinigung Teil I","Genehmigung oder gekürzte amtliche Ausfertigung","Zulassungsbescheinigung Teil II"]}},{"id":"da-02","typ":"single","frage":"What is the international motor insurance card (“Green Card”) good for?","optionen":["It replaces the driving licence abroad.","It proves motor liability insurance; not required in the EU but helpful, partly mandatory outside the EU.","It is the licence for trips abroad.","It allows cabotage."],"richtig":1,"erklaerung":"Within the EU the number plate counts as proof of insurance.","quelle":"Versicherungsrecht","lc":true,"lek":"dokumente-ausland","sg":"5.3","de":{"frage":"Wofür ist die Internationale Versicherungskarte („Grüne Karte“) gut?","erklaerung":"Innerhalb der EU gilt das Kennzeichen als Versicherungsnachweis.","optionen":["Sie ersetzt den Führerschein im Ausland.","Sie weist die Kfz-Haftpflichtversicherung nach; in der EU nicht zwingend, aber hilfreich, außerhalb der EU teils Pflicht.","Sie ist die Genehmigung für Auslandsfahrten.","Sie berechtigt zur Kabotage."]}},{"id":"da-03","typ":"tf","frage":"The European accident report is a standard form that makes reporting damage after an accident abroad easier.","richtig":true,"erklaerung":"It has the same layout in all EU languages.","quelle":"Versicherungswesen","lek":"dokumente-ausland","sg":"5.3","de":{"frage":"Der Europäische Unfallbericht ist ein einheitliches Formular, das die Schadenmeldung nach einem Unfall im Ausland erleichtert.","erklaerung":"Er ist in allen EU-Sprachen gleich aufgebaut."}},{"id":"da-04","typ":"single","frage":"Why is a proof of booking useful for a Mietwagen abroad?","optionen":["For calculating tolls","To show that the booking came via the registered office and that there is no forbidden cabotage","It replaces the registration certificate","For vehicle tax"],"richtig":1,"erklaerung":"This way you can prove at checks that the trip is legal.","quelle":"§ 49 Abs. 4 PBefG","lek":"dokumente-ausland","sg":"5.3","de":{"frage":"Warum ist bei einem Mietwagen im Ausland ein Auftragsnachweis sinnvoll?","erklaerung":"So lässt sich bei Kontrollen belegen, dass die Fahrt legal ist.","optionen":["Für die Mautberechnung","Um zu zeigen, dass der Auftrag über den Betriebssitz kam und keine verbotene Kabotage vorliegt","Er ist ein Ersatz für den Fahrzeugschein","Für die Kfz-Steuer"]}},{"id":"dk-01","typ":"zuordnung","frage":"Who does the document belong to?","kategorien":["driver","vehicle","company"],"paare":[{"t":"Passenger transport driving permit (P-Schein)","k":0,"w":"§ 48 (3) FeV."},{"t":"Registration certificate part I","k":1,"w":"Vehicle registration, also digital in the i-Kfz app."},{"t":"Shortened official copy of the licence","k":2,"w":"§ 17 (4) PBefG."},{"t":"ID card","k":0,"w":"§ 2a SchwarzArbG, show to customs."},{"t":"Valid taxi tariff","k":2,"w":"§ 10 BOKraft: rules on fares and conditions of carriage."}],"erklaerung":"Driver-related, vehicle-related and company-related documents.","quelle":"PBefG, FeV, SchwarzArbG, BOKraft","lc":true,"lek":"dokumente","sg":"2.9","de":{"frage":"Zu wem gehört das Dokument?","erklaerung":"Fahrer-, fahrzeug- und unternehmensbezogene Dokumente.","kategorien":["Fahrer","Fahrzeug","Unternehmen"],"paare":["Fahrerlaubnis zur Fahrgastbeförderung","Zulassungsbescheinigung Teil I","Gekürzte amtliche Ausfertigung der Genehmigung","Personalausweis","Gültiger Taxitarif"]}},{"id":"dk-02","typ":"single","frage":"Where must the licence number (Ordnungsnummer) be displayed in a taxi?","optionen":["On the roof next to the taxi sign","At the bottom right of the rear window, readable from inside and outside","On the dashboard","On the driver's door"],"richtig":1,"erklaerung":"§ 27 BOKraft. In taxis also inside: name and registered office of the operator.","quelle":"§ 27 BOKraft","lc":true,"lek":"dokumente","sg":"2.9","de":{"frage":"Wo muss im Taxi die Ordnungsnummer angebracht sein?","erklaerung":"§ 27 BOKraft. Zusätzlich im Taxi innen: Name und Betriebssitz des Unternehmers.","optionen":["Auf dem Dach neben dem Taxischild","Unten rechts an der Heckscheibe, von innen und außen lesbar","Am Armaturenbrett","Auf der Fahrertür"]}},{"id":"dk-03","typ":"single","frage":"How long must booking records in Mietwagen transport be kept?","optionen":["1 year","2 years","6 years","10 years"],"fest":true,"richtig":0,"erklaerung":"Under § 49 (4) PBefG one year. Tax periods can be longer for the same data if they are also accounting vouchers.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"dokumente","sg":"2.9","de":{"frage":"Wie lange müssen Auftragsaufzeichnungen im Mietwagenverkehr aufbewahrt werden?","erklaerung":"Nach § 49 Abs. 4 PBefG ein Jahr. Steuerliche Fristen können für dieselben Daten länger sein, wenn sie zugleich Buchungsbelege sind.","optionen":["1 Jahr","2 Jahre","6 Jahre","10 Jahre"]}},{"id":"dk-04","typ":"multi","frage":"Which documents must an employed taxi driver carry on every trip? Select all correct answers.","optionen":["Driving licence","P-Schein","ID card or passport","Registration certificate part II (vehicle title)","His employment contract"],"richtig":[0,1,2],"erklaerung":"The vehicle title (part II) does not belong in the vehicle. The vehicle must also carry part I, the licence copy and the tariff.","quelle":"§ 48 FeV, § 2a SchwarzArbG","lek":"dokumente","sg":"2.9","de":{"frage":"Welche Dokumente muss ein angestellter Taxifahrer bei jeder Fahrt dabeihaben? Wähle alle richtigen.","erklaerung":"Der Fahrzeugbrief (Teil II) gehört nicht ins Auto. Ins Fahrzeug gehören außerdem Teil I, Genehmigungsausfertigung und Tarif.","optionen":["Führerschein","P-Schein","Personalausweis oder Pass","Zulassungsbescheinigung Teil II (Fahrzeugbrief)","Seinen Arbeitsvertrag"]}},{"id":"dk-05","typ":"tf","frage":"The licence under § 17 PBefG may also be carried electronically in the vehicle.","richtig":true,"erklaerung":"§ 17 (4) PBefG allows written or electronic form.","quelle":"§ 17 Abs. 4 PBefG","lek":"dokumente","sg":"2.9","de":{"frage":"Die Genehmigung nach § 17 PBefG darf im Fahrzeug auch elektronisch mitgeführt werden.","erklaerung":"§ 17 Abs. 4 PBefG erlaubt schriftliche oder elektronische Form."}},{"id":"dk-06","typ":"tf","frage":"In a Mietwagen there must be a sign inside with the operator's name and registered office.","richtig":false,"erklaerung":"§ 27 BOKraft requires the sign with the operator's address for taxis. Mietwagen need the sign with the licence number on the rear window.","quelle":"§ 27 BOKraft","lek":"dokumente","sg":"2.9","de":{"frage":"Im Mietwagen muss innen ein Schild mit Name und Betriebssitz des Unternehmers angebracht sein.","erklaerung":"Das Schild mit der Unternehmeranschrift schreibt § 27 BOKraft für Taxen vor. Mietwagen brauchen das Schild mit der Ordnungsnummer an der Heckscheibe."}},{"id":"dk-07","typ":"offen","frage":"At a traffic check the police ask for the papers. Which documents must a taxi carry on every trip? Assign them to driver, vehicle and company.","muster":"<p>Driver: driving licence, passenger transport permit, ID card/passport. Vehicle: registration certificate part I (paper or i-Kfz app). Company: licence document or shortened official copy, valid taxi tariff/conditions of carriage. Also: licence number on the rear window and operator's address inside.</p><p lang=\"de\"><i>Key German terms: Führerschein, Fahrerlaubnis zur Fahrgastbeförderung, Zulassungsbescheinigung Teil I, Genehmigungsurkunde, Ordnungsnummer.</i></p>","punkte_liste":[{"t":"Driving licence and P-Schein","p":1},{"t":"ID (SchwarzArbG)","p":1},{"t":"Registration certificate part I","p":1},{"t":"Licence/copy and tariff","p":1}],"quelle":"PBefG, FeV, BOKraft, SchwarzArbG","lek":"dokumente","sg":"2.9","de":{"frage":"Bei einer Verkehrskontrolle fragt die Polizei nach den Papieren. Welche Dokumente muss ein Taxi bei jeder Fahrt mitführen? Ordnen Sie sie Fahrer, Fahrzeug und Unternehmen zu.","muster":"<p>Fahrer: Führerschein, Fahrerlaubnis zur Fahrgastbeförderung, Personalausweis/Pass. Fahrzeug: Zulassungsbescheinigung Teil I (Papier oder i-Kfz-App). Unternehmen: Genehmigungsurkunde oder gekürzte amtliche Ausfertigung, geltender Taxitarif/Beförderungsbedingungen. Außerdem: Ordnungsnummer an der Heckscheibe und Unternehmeranschrift innen.</p>","punkte_liste":["Führerschein und P-Schein","Ausweis (SchwarzArbG)","Zulassungsbescheinigung Teil I","Genehmigung/Ausfertigung und Tarif"]}},{"id":"fp-01","typ":"multi","frage":"Which requirements apply to the passenger transport driving permit (taxi/Mietwagen)? Select all correct answers.","optionen":["Minimum age 21","Class B licence for at least 2 years","Certificate of good conduct and extract from the driver fitness register","Medical certificate and proof of eyesight","Passing the operator's exam (Fachkundeprüfung) at the IHK","German citizenship"],"richtig":[0,1,2,3],"erklaerung":"The operator's exam is not a requirement for the P-Schein. Citizenship does not matter.","quelle":"§ 48 Abs. 4 FeV","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Welche Voraussetzungen gelten für die Fahrerlaubnis zur Fahrgastbeförderung (Taxi/Mietwagen)? Wähle alle richtigen.","erklaerung":"Die Unternehmer-Fachkundeprüfung ist keine Voraussetzung für den P-Schein. Die Staatsangehörigkeit spielt keine Rolle.","optionen":["Mindestalter 21 Jahre","Fahrerlaubnis Klasse B seit mindestens 2 Jahren","Führungszeugnis und Auszug aus dem Fahreignungsregister","Ärztliches Zeugnis und Nachweis des Sehvermögens","Bestandene Fachkundeprüfung für Unternehmer bei der IHK","Deutsche Staatsangehörigkeit"]}},{"id":"fp-02","typ":"single","frage":"How long is a passenger transport driving permit valid at most?","optionen":["1 year","2 years","5 years","unlimited"],"fest":true,"richtig":2,"erklaerung":"It is issued for at most 5 years and can be extended by up to 5 years each time.","quelle":"§ 48 Abs. 5 FeV","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Wie lange gilt eine Fahrerlaubnis zur Fahrgastbeförderung höchstens?","erklaerung":"Sie wird für höchstens 5 Jahre erteilt und kann jeweils um bis zu 5 Jahre verlängert werden.","optionen":["1 Jahr","2 Jahre","5 Jahre","unbefristet"]}},{"id":"fp-03","typ":"tf","frage":"As vehicle keeper, the operator may let a driver without a valid P-Schein carry passengers if the driver has a normal licence and has applied for renewal.","richtig":false,"erklaerung":"The keeper may not order or allow passenger transport if the driver lacks the required permit.","quelle":"§ 48 Abs. 7 FeV","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Als Halter darf der Unternehmer einen Fahrer ohne gültigen P-Schein Fahrgäste befördern lassen, wenn der Fahrer einen normalen Führerschein hat und die Verlängerung beantragt ist.","erklaerung":"Der Halter darf die Fahrgastbeförderung nicht anordnen oder zulassen, wenn der Fahrer die erforderliche Erlaubnis nicht hat."}},{"id":"fp-04","typ":"single","frage":"How many children must a taxi at least be able to secure with child seats on the rear seats (if children are not carried regularly)?","optionen":["None, taxis are exempt","1 child of any weight","2 children from 9 kg, at least 1 of them 9 to 18 kg","As many children as there are seats"],"richtig":2,"erklaerung":"Taxis have a relief: the duty is limited to 2 children from 9 kg on the rear seats, at least one of 9 to 18 kg must be securable.","quelle":"§ 21 Abs. 1a StVO","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Wie viele Kinder muss ein Taxi auf den Rücksitzen mindestens mit Kindersitz sichern können (wenn nicht regelmäßig Kinder befördert werden)?","erklaerung":"Für Taxis gilt eine Erleichterung: Die Pflicht ist auf 2 Kinder ab 9 kg auf den Rücksitzen beschränkt, mindestens eines mit 9 bis 18 kg muss gesichert werden können.","optionen":["Kein Kind, Taxis sind ausgenommen","1 Kind beliebigen Gewichts","2 Kinder ab 9 kg, davon mindestens 1 mit 9 bis 18 kg","So viele Kinder, wie Sitze vorhanden sind"]}},{"id":"fp-05","typ":"tf","frage":"A taxi operator takes 3 children to school every day. The taxi relief for child restraints does not apply to these trips.","richtig":true,"erklaerung":"The relief does not apply if children are carried regularly. Then every child needs a suitable restraint.","quelle":"§ 21 Abs. 1a StVO","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Ein Taxiunternehmer fährt jeden Tag 3 Kinder zur Schule. Für diese Fahrten gilt die Erleichterung für Taxis bei der Kindersicherung nicht.","erklaerung":"Die Erleichterung gilt nicht, wenn eine regelmäßige Beförderung von Kindern stattfindet. Dann braucht jedes Kind eine passende Rückhalteeinrichtung."}},{"id":"fp-06","typ":"single","frage":"May a taxi use a bus lane (sign 245)?","optionen":["Yes, always","Only if an additional sign allows it, e.g. “Taxi frei”","Only with a passenger","Only at night"],"richtig":1,"erklaerung":"Bus lanes are reserved for scheduled buses. Taxis may only use them if an additional sign allows it.","quelle":"§ 41 StVO, Anlage 2 Zeichen 245","lc":true,"lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Darf ein Taxi eine Busspur (Zeichen 245) benutzen?","erklaerung":"Bussonderfahrstreifen sind grundsätzlich Linienbussen vorbehalten. Taxis dürfen sie nur nutzen, wenn ein Zusatzzeichen das erlaubt.","optionen":["Ja, immer","Nur wenn ein Zusatzzeichen das erlaubt, z. B. „Taxi frei“","Nur mit Fahrgast","Nur nachts"]}},{"id":"fp-07","typ":"tf","frage":"Taxi drivers are exempt from wearing a seat belt while carrying passengers.","richtig":false,"erklaerung":"The former exemption for taxi drivers was removed (§ 21a (1) No. 1 StVO was deleted). Seat belts are mandatory today.","quelle":"§ 21a StVO","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Taxifahrer sind bei der Fahrgastbeförderung von der Gurtpflicht befreit.","erklaerung":"Die frühere Ausnahme für Taxifahrer wurde gestrichen (§ 21a Abs. 1 Nr. 1 StVO ist weggefallen). Heute gilt die Gurtpflicht."}},{"id":"fp-08","typ":"single","frage":"What applies to alcohol for taxi and Mietwagen drivers on duty?","optionen":["Up to 0.5 per mille is allowed.","Up to 0.3 per mille is allowed.","Alcohol and other intoxicating substances are forbidden on duty and on standby.","Only beer is allowed."],"richtig":2,"erklaerung":"The BOKraft forbids drivers to consume alcohol and other intoxicating substances on duty and on standby.","quelle":"§ 8 Abs. 3 Nr. 1 und Abs. 5 BOKraft","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Was gilt für Alkohol bei Taxi- und Mietwagenfahrern im Dienst?","erklaerung":"Die BOKraft verbietet dem Fahrpersonal den Genuss alkoholischer Getränke und anderer berauschender Mittel während des Dienstes und der Dienstbereitschaft.","optionen":["Bis 0,5 Promille ist erlaubt.","Bis 0,3 Promille ist erlaubt.","Alkohol und andere berauschende Mittel sind im Dienst und in der Dienstbereitschaft verboten.","Nur Bier ist erlaubt."]}},{"id":"fp-09","typ":"single","frage":"From which age do you need extra proof of performance to renew the P-Schein?","optionen":["50 years","60 years","65 years","70 years"],"fest":true,"richtig":1,"erklaerung":"Renewal beyond the age of 60 requires additional proof under Annex 5 No. 2 and 3 FeV.","quelle":"§ 48 Abs. 6 FeV","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Ab welchem Alter braucht man für die Verlängerung des P-Scheins zusätzlich einen Nachweis der Leistungsfähigkeit?","erklaerung":"Für eine Verlängerung über das 60. Lebensjahr hinaus sind zusätzliche Nachweise nach Anlage 5 Nr. 2 und 3 FeV nötig.","optionen":["50 Jahre","60 Jahre","65 Jahre","70 Jahre"]}},{"id":"fp-10","typ":"tf","frage":"A driver with a class D bus licence does not need an extra P-Schein to drive a taxi.","richtig":true,"erklaerung":"§ 48 (2) No. 4 FeV: no passenger transport permit is needed for drivers with class D or D1.","quelle":"§ 48 Abs. 2 FeV","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Ein Fahrer mit Busführerschein Klasse D braucht für das Taxifahren keinen zusätzlichen P-Schein.","erklaerung":"§ 48 Abs. 2 Nr. 4 FeV: Keine Fahrerlaubnis zur Fahrgastbeförderung nötig für Fahrer mit Klasse D oder D1."}},{"id":"fp-11","typ":"tf","frage":"Passengers may smoke in the taxi if the driver agrees.","richtig":false,"erklaerung":"Public passenger transport, which includes vehicles under the PBefG, has a legal smoking ban.","quelle":"§§ 1, 2 BNichtrSchG","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Fahrgäste dürfen im Taxi rauchen, wenn der Fahrer zustimmt.","erklaerung":"In Verkehrsmitteln des öffentlichen Personenverkehrs, zu denen Fahrzeuge nach dem PBefG gehören, gilt ein gesetzliches Rauchverbot."}},{"id":"fp-12","typ":"single","frage":"A child is 10 years old and 152 cm tall. Does it need a child seat in a taxi?","optionen":["Yes, all children under 12 need a child seat.","No, the rule only applies to children under 12 who are smaller than 150 cm.","Yes, up to 14 years","Only on the front passenger seat"],"richtig":1,"erklaerung":"Both conditions must apply: under 12 years and smaller than 150 cm.","quelle":"§ 21 Abs. 1a StVO","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Ein Kind ist 10 Jahre alt und 152 cm groß. Braucht es im Taxi einen Kindersitz?","erklaerung":"Beide Merkmale müssen zusammenkommen: unter 12 Jahre und kleiner als 150 cm.","optionen":["Ja, alle Kinder unter 12 brauchen einen Kindersitz.","Nein, die Pflicht gilt nur für Kinder unter 12 Jahren, die kleiner als 150 cm sind.","Ja, bis 14 Jahre","Nur auf dem Beifahrersitz"]}},{"id":"fp-13","typ":"offen","frage":"A new driver wants to start working for you as a taxi driver. What must you check as the operator before he may carry passengers?","muster":"<p>Valid class B driving licence (held for at least 2 years) and valid passenger transport driving permit (P-Schein, check the expiry date). The keeper may not allow transport without a P-Schein (§ 48 (7) FeV). Also: social insurance registration before starting work (immediate notification), employment contract / written terms, briefing on the vehicle, taximeter, child seats and conduct rules (no alcohol, smoking ban).</p>","punkte_liste":[{"t":"Valid class B licence (for at least 2 years)","p":1},{"t":"Valid P-Schein, check expiry date","p":1},{"t":"Note: keeper may not allow transport without P-Schein","p":1},{"t":"Other sensible points (immediate SV notification, contract, briefing)","p":1}],"quelle":"§ 48 FeV","lek":"fahrpersonal-strassenverkehrsrecht","sg":"1.3","de":{"frage":"Ein neuer Fahrer möchte bei Ihnen als Taxifahrer anfangen. Was müssen Sie als Unternehmer prüfen, bevor er Fahrgäste befördern darf?","muster":"<p>Gültige Fahrerlaubnis Klasse B (seit mindestens 2 Jahren) und gültige Fahrerlaubnis zur Fahrgastbeförderung (P-Schein, Ablaufdatum prüfen). Der Halter darf die Beförderung ohne P-Schein nicht zulassen (§ 48 Abs. 7 FeV). Außerdem: Anmeldung zur Sozialversicherung vor Arbeitsbeginn (Sofortmeldung), Arbeitsvertrag/Nachweis der Arbeitsbedingungen, Einweisung in Fahrzeug, Taxameter, Kindersitze und Verhaltensregeln (kein Alkohol, Rauchverbot).</p>","punkte_liste":["Gültiger Führerschein Klasse B (seit mind. 2 Jahren)","Gültiger P-Schein, Ablaufdatum kontrollieren","Hinweis: Halter darf Beförderung ohne P-Schein nicht zulassen","Weitere sinnvolle Punkte (Sofortmeldung SV, Arbeitsvertrag, Einweisung)"]}},{"id":"aus-01","typ":"single","frage":"What does cabotage (Kabotage) mean in taxi transport?","optionen":["A trip of more than 50 km","Carrying passengers within another country with a foreign vehicle","An empty trip back to the registered office","A trip with more than 4 passengers"],"richtig":1,"erklaerung":"Example: an Aachen taxi carries passengers from Vaals to Maastricht. That is forbidden.","quelle":"Grenzüberschreitender Verkehr","lc":true,"lek":"fahrten-ins-ausland","sg":"5.1","de":{"frage":"Was versteht man im Taxiverkehr unter Kabotage?","erklaerung":"Beispiel: Ein Aachener Taxi fährt Fahrgäste von Vaals nach Maastricht. Das ist verboten.","optionen":["Eine Fahrt über mehr als 50 km","Die Beförderung von Fahrgästen innerhalb eines anderen Staates durch ein ausländisches Fahrzeug","Eine Leerfahrt zurück zum Betriebssitz","Eine Fahrt mit mehr als 4 Fahrgästen"]}},{"id":"aus-02","typ":"zuordnung","frage":"May an Aachen taxi make this trip?","kategorien":["allowed","forbidden"],"paare":[{"t":"Aachen → Heerlen, passenger gets in in Aachen","k":0,"w":"Taking passengers abroad is allowed."},{"t":"Heerlen → Kerkrade (both NL)","k":1,"w":"Cabotage."},{"t":"Maastricht → Aachen, booked by phone in advance","k":0,"w":"Allowed under Dutch law with a prior booking."},{"t":"Wait for passengers at Maastricht station","k":1,"w":"Waiting for customers abroad is not allowed."},{"t":"Eupen → Liège (both BE)","k":1,"w":"Cabotage."}],"erklaerung":"Basic rule: bringing passengers there yes, trips within the other country no.","quelle":"§ 52 PBefG, Recht NL/BE","lc":true,"lek":"fahrten-ins-ausland","sg":"5.1","de":{"frage":"Darf ein Aachener Taxi diese Fahrt machen?","erklaerung":"Grundregel: hinbringen ja, innerhalb des anderen Landes nein.","kategorien":["erlaubt","verboten"],"paare":["Aachen → Heerlen, Fahrgast steigt in Aachen ein","Heerlen → Kerkrade (beide NL)","Maastricht → Aachen, vorher telefonisch bestellt","Am Bahnhof Maastricht auf Fahrgäste warten","Eupen → Lüttich (beide BE)"]}},{"id":"aus-03","typ":"tf","frage":"For a taxi trip from Aachen to Maastricht the Aachen taxi tariff automatically applies to the whole route.","richtig":false,"erklaerung":"The tariff applies within the mandatory service area. For trips beyond it the price is agreed under the local rule, best before the trip starts.","quelle":"§§ 47, 51 PBefG","lc":true,"lek":"fahrten-ins-ausland","sg":"5.1","de":{"frage":"Für eine Taxifahrt von Aachen nach Maastricht gilt automatisch der Aachener Taxitarif für die ganze Strecke.","erklaerung":"Der Tarif gilt im Pflichtfahrbereich. Für Fahrten darüber hinaus wird der Preis nach der örtlichen Regel vereinbart, am besten vor Fahrtantritt."}},{"id":"aus-04","typ":"single","frage":"Which law applies to a Dutch taxi on the German part of a trip to Aachen?","optionen":["Only Dutch law","The German PBefG and its regulations","The EU bus regulation","No law"],"richtig":1,"erklaerung":"§ 52 (1) PBefG: for cross-border transport the PBefG also applies to operators based abroad.","quelle":"§ 52 PBefG","lek":"fahrten-ins-ausland","sg":"5.1","de":{"frage":"Welches Recht gilt für ein niederländisches Taxi auf der deutschen Strecke einer Fahrt nach Aachen?","erklaerung":"§ 52 Abs. 1 PBefG: Für grenzüberschreitenden Verkehr gilt das PBefG auch für Unternehmer mit Sitz im Ausland.","optionen":["Nur niederländisches Recht","Das deutsche PBefG und seine Verordnungen","EU-Busverordnung","Kein Recht"]}},{"id":"aus-05","typ":"tf","frage":"A Mietwagen from Aachen takes a passenger to Liège. Without a new booking via the registered office it must return to Aachen.","richtig":true,"erklaerung":"The duty to return also applies after trips abroad. Cabotage in Belgium would also be forbidden.","quelle":"§ 49 Abs. 4 PBefG","lek":"fahrten-ins-ausland","sg":"5.1","de":{"frage":"Ein Mietwagen aus Aachen bringt einen Fahrgast nach Lüttich. Ohne neuen Auftrag über den Betriebssitz muss er zurück nach Aachen.","erklaerung":"Die Rückkehrpflicht gilt auch nach Auslandsfahrten. Kabotage in Belgien wäre zudem verboten."}},{"id":"aus-06","typ":"offen","frage":"A passenger gets in in Aachen and wants to go to Maastricht. There he wants the taxi to wait and then take him to a hotel in Valkenburg (NL). How do you assess this?","muster":"<p>Aachen → Maastricht: allowed (transport abroad); agree the price beforehand because it is outside the mandatory service area. Maastricht → Valkenburg: both places are in the Netherlands, so it is cabotage – forbidden for a German taxi (fine in NL about 2.000 €). Solution: take the passenger directly from Aachen to Valkenburg (one continuous trip out of Germany) or use a Dutch taxi for the part within the Netherlands.</p><p lang=\"de\"><i>Key German terms: Kabotage, Pflichtfahrbereich, Preis vor Fahrtantritt vereinbaren.</i></p>","punkte_liste":[{"t":"Aachen → Maastricht allowed","p":1},{"t":"Maastricht → Valkenburg is cabotage, forbidden","p":1},{"t":"Agree price beforehand / tariff doesn't apply abroad","p":1},{"t":"Sensible alternative named","p":1}],"quelle":"§ 52 PBefG, Recht NL","lek":"fahrten-ins-ausland","sg":"5.1","de":{"frage":"Ein Fahrgast steigt in Aachen ein und will nach Maastricht. Dort möchte er, dass das Taxi wartet und ihn danach zu einem Hotel in Valkenburg (NL) bringt. Wie beurteilen Sie das?","muster":"<p>Aachen → Maastricht: erlaubt (Beförderung ins Ausland), Preis vorher vereinbaren, da außerhalb des Pflichtfahrbereichs. Maastricht → Valkenburg: beide Orte in den Niederlanden, also Kabotage – für ein deutsches Taxi verboten (Bußgeld in NL, ca. 2.000 €). Lösung: Fahrgast direkt von Aachen nach Valkenburg bringen (eine durchgehende Fahrt aus Deutschland heraus) oder für die Strecke in den Niederlanden ein niederländisches Taxi nehmen.</p>","punkte_liste":["Aachen → Maastricht erlaubt","Maastricht → Valkenburg ist Kabotage, verboten","Preis vorher vereinbaren / Tarif gilt nicht im Ausland","Sinnvolle Alternative genannt"]}},{"id":"fb-01","typ":"single","frage":"What does traffic sign 229 “Taxenstand” (taxi rank) mean?","optionen":["Parking for all vehicles up to 30 minutes","Drivers must not stop there, except taxis kept ready for passenger transport.","Only Mietwagen may wait there.","Stopping allowed for everyone to get in and out"],"richtig":1,"erklaerung":"Private cars may not stop at a taxi rank either.","quelle":"StVO Anlage 2, Zeichen 229","lc":true,"lek":"funk-bereitstellung","sg":"3.7","de":{"frage":"Was bedeutet das Verkehrszeichen 229 „Taxenstand“?","erklaerung":"Auch Privatwagen dürfen am Taxenstand nicht halten.","optionen":["Parkplatz für alle Fahrzeuge bis 30 Minuten","Wer ein Fahrzeug führt, darf dort nicht halten, ausgenommen für die Fahrgastbeförderung bereitgehaltene Taxen.","Nur Mietwagen dürfen dort warten.","Halten erlaubt zum Ein- und Aussteigen für alle"]}},{"id":"fb-02","typ":"tf","frage":"A passenger at the taxi rank must take the first taxi in the line.","richtig":false,"erklaerung":"Under the local taxi regulations the passenger has free choice among the taxis on standby.","quelle":"Taxenordnung","lc":true,"lek":"funk-bereitstellung","sg":"3.7","de":{"frage":"Ein Fahrgast am Taxenstand muss das erste Taxi in der Reihe nehmen.","erklaerung":"Der Fahrgast hat nach den Taxenordnungen freie Wahl unter den bereitgehaltenen Taxis."}},{"id":"fb-03","typ":"single","frage":"Who assigns frequencies for your own taxi radio network?","optionen":["The IHK","The licensing authority","The Federal Network Agency (Bundesnetzagentur)","The Federal Motor Transport Authority"],"richtig":2,"erklaerung":"Frequency assignments are issued by the Bundesnetzagentur under the Telecommunications Act.","quelle":"TKG","lc":true,"lek":"funk-bereitstellung","sg":"3.7","de":{"frage":"Wer teilt Frequenzen für ein eigenes Taxifunknetz zu?","erklaerung":"Frequenzzuteilungen erteilt die Bundesnetzagentur nach dem Telekommunikationsgesetz.","optionen":["Die IHK","Die Genehmigungsbehörde","Die Bundesnetzagentur","Das Kraftfahrt-Bundesamt"]}},{"id":"fb-04","typ":"single","frage":"Where may taxis be kept on standby?","optionen":["Anywhere parking is allowed","At places approved by the authority, in principle in the municipality of the registered office","Only at the registered office","Only at railway stations"],"richtig":1,"erklaerung":"§ 47 (1) and (2) PBefG.","quelle":"§ 47 PBefG","lek":"funk-bereitstellung","sg":"3.7","de":{"frage":"Wo dürfen Taxen bereitgehalten werden?","erklaerung":"§ 47 Abs. 1 und 2 PBefG.","optionen":["Überall, wo Parken erlaubt ist","An behördlich zugelassenen Stellen, grundsätzlich in der Gemeinde des Betriebssitzes","Nur am Betriebssitz","Nur an Bahnhöfen"]}},{"id":"fb-05","typ":"tf","frage":"Where exactly taxis line up at the rank and how they move up is usually set by the local taxi regulations.","richtig":true,"erklaerung":"The authorisation for this is in § 47 (3) PBefG.","quelle":"§ 47 Abs. 3 PBefG","lek":"funk-bereitstellung","sg":"3.7","de":{"frage":"Wo genau sich Taxis am Stand aufstellen und wie sie nachrücken, regelt meist die örtliche Taxenordnung.","erklaerung":"Die Ermächtigung dafür steht in § 47 Abs. 3 PBefG."}},{"id":"fb-06","typ":"single","frage":"During his lunch break a taxi driver leaves his taxi at the taxi rank for an hour and goes to eat. Is that allowed?","optionen":["Yes, taxis may always stand there.","No, only taxis kept ready for passenger transport may stop at the rank.","Yes, if the taxi sign is off.","Only at night"],"richtig":1,"erklaerung":"A taxi on a break is not on standby. It blocks the rank for others.","quelle":"Zeichen 229 StVO, Taxenordnung","lek":"funk-bereitstellung","sg":"3.7","de":{"frage":"Ein Taxifahrer stellt sein Taxi während seiner Mittagspause für eine Stunde am Taxenstand ab und geht essen. Ist das erlaubt?","erklaerung":"Ein Taxi in der Pause wird nicht bereitgehalten. Es blockiert den Stand für andere.","optionen":["Ja, Taxis dürfen dort immer stehen.","Nein, am Taxenstand dürfen nur Taxen halten, die für die Fahrgastbeförderung bereitgehalten werden.","Ja, wenn das Taxischild aus ist.","Nur nachts"]}},{"id":"gb-01","typ":"zahl","frage":"An operator wants to start with 4 taxis. How much equity and reserves must he prove at least?","richtig":6000,"einheit":"€","tol":1,"loesung":"1st vehicle: 2.250 €\n3 further vehicles: 3 × 1.250 € = 3.750 €\nTotal: 6.000 €","erklaerung":"For taxi and Mietwagen, one quarter of the EU amounts for buses applies: 2.250 € for the first and 1.250 € for each further vehicle.","quelle":"§ 2 Abs. 1 Nr. 2 PBZugV, Art. 7 VO (EG) 1071/2009","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Ein Unternehmer will mit 4 Taxen beginnen. Wie viel Eigenkapital und Reserven muss er mindestens nachweisen?","erklaerung":"Für Taxi und Mietwagen gilt ein Viertel der EU-Beträge für Busse: 2.250 € für das erste und 1.250 € für jedes weitere Fahrzeug.","loesung":"1. Fahrzeug: 2.250 €\n3 weitere Fahrzeuge: 3 × 1.250 € = 3.750 €\nSumme: 6.000 €","einheit":"€"}},{"id":"gb-02","typ":"single","frage":"How old may the tax office's certificate of good standing (Unbedenklichkeitsbescheinigung) be at most when you apply?","optionen":["1 month","3 months","6 months","1 year"],"fest":true,"richtig":1,"erklaerung":"Certificates from the tax office, municipality, social insurance and Berufsgenossenschaft: at most 3 months. The equity certificate may be up to 1 year old.","quelle":"§ 2 Abs. 2 PBZugV","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Wie alt darf die Unbedenklichkeitsbescheinigung des Finanzamts bei Antragstellung höchstens sein?","erklaerung":"Bescheinigungen von Finanzamt, Gemeinde, Sozialversicherung und Berufsgenossenschaft: höchstens 3 Monate. Die Eigenkapitalbescheinigung darf bis zu 1 Jahr alt sein.","optionen":["1 Monat","3 Monate","6 Monate","1 Jahr"]}},{"id":"gb-03","typ":"multi","frage":"How can professional competence for taxi and Mietwagen be proven? Select all correct answers.","optionen":["Passing the exam (Fachkundeprüfung) at the IHK","An equivalent final examination recognised by the state authority","At least 3 years in a management position at a German taxi or Mietwagen company","At least 5 years as an employed taxi driver","Holding a class B driving licence for at least 10 years"],"richtig":[0,1,2],"erklaerung":"Exam (§ 4), equivalent qualification (§ 6) or 3 years in management (§ 7 PBZugV). Driving experience alone is not enough.","quelle":"§§ 4, 6, 7 PBZugV","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Wie kann die fachliche Eignung für den Taxi- und Mietwagenverkehr nachgewiesen werden? Wähle alle richtigen.","erklaerung":"Prüfung (§ 4), gleichwertiger Abschluss (§ 6) oder 3 Jahre leitende Tätigkeit (§ 7 PBZugV). Reine Fahrerfahrung reicht nicht.","optionen":["Bestandene Fachkundeprüfung bei der IHK","Eine von der Landesbehörde anerkannte gleichwertige Abschlussprüfung","Mindestens 3 Jahre leitende Tätigkeit in einem deutschen Taxi- oder Mietwagenunternehmen","Mindestens 5 Jahre Erfahrung als angestellter Taxifahrer","Ein Führerschein der Klasse B seit mindestens 10 Jahren"]}},{"id":"gb-04","typ":"single","frage":"Within which period must the authority decide on a licence application?","optionen":["4 weeks","3 months, extendable once by up to 3 months","6 months, extendable as often as needed","There is no deadline."],"richtig":1,"erklaerung":"The period is 3 months and can be extended by up to 3 months. If the authority does not decide in time, the licence is deemed granted.","quelle":"§ 15 Abs. 1 PBefG","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Innerhalb welcher Frist muss die Behörde über einen Antrag auf Genehmigung entscheiden?","erklaerung":"Die Frist beträgt 3 Monate und kann um höchstens 3 Monate verlängert werden. Entscheidet die Behörde nicht rechtzeitig, gilt die Genehmigung als erteilt.","optionen":["4 Wochen","3 Monate, einmal verlängerbar um höchstens 3 Monate","6 Monate, beliebig verlängerbar","Es gibt keine Frist."]}},{"id":"gb-05","typ":"single","frage":"What is the maximum fine for carrying passengers without a licence?","optionen":["1.000 €","5.000 €","10.000 €","20.000 €"],"fest":true,"richtig":3,"erklaerung":"Carrying passengers without a licence: up to 20.000 €. Most other breaches of the PBefG: up to 10.000 €.","quelle":"§ 61 Abs. 2 PBefG","lc":true,"lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Wie hoch kann das Bußgeld für eine Personenbeförderung ohne Genehmigung höchstens sein?","erklaerung":"Beförderung ohne Genehmigung: bis 20.000 €. Die meisten anderen Verstöße gegen das PBefG: bis 10.000 €.","optionen":["1.000 €","5.000 €","10.000 €","20.000 €"]}},{"id":"gb-06","typ":"multi","frage":"Which requirements for the licence does § 13 (1) PBefG name? Select all correct answers.","optionen":["Safety and financial capacity of the business","Reliability","Professional competence","Registered office or branch in Germany","German citizenship","At least one year of experience as a taxi driver"],"richtig":[0,1,2,3],"erklaerung":"These are the four requirements. Citizenship and driving experience are not requirements.","quelle":"§ 13 Abs. 1 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Welche Voraussetzungen nennt § 13 Abs. 1 PBefG für die Genehmigung? Wähle alle richtigen.","erklaerung":"Das sind die vier Voraussetzungen. Staatsangehörigkeit und Fahrpraxis sind keine Voraussetzungen.","optionen":["Sicherheit und Leistungsfähigkeit des Betriebs","Zuverlässigkeit","Fachliche Eignung","Betriebssitz oder Niederlassung im Inland","Deutsche Staatsangehörigkeit","Mindestens ein Jahr Fahrpraxis als Taxifahrer"]}},{"id":"gb-07","typ":"single","frage":"At which IHK do you take the exam?","optionen":["At any IHK in Germany","At the IHK where you live","At the IHK where your business will be","Only at the IHK Berlin"],"richtig":1,"erklaerung":"For taxi and Mietwagen, the IHK of the candidate's place of residence is responsible. (For buses: place of work.)","quelle":"§ 5 Abs. 4 PBZugV","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Bei welcher IHK legst du die Fachkundeprüfung ab?","erklaerung":"Für Taxi und Mietwagen ist die IHK am Wohnsitz des Bewerbers zuständig. (Bei Bussen: Arbeitsort.)","optionen":["Bei jeder IHK in Deutschland","Bei der IHK an deinem Wohnsitz","Bei der IHK am geplanten Betriebssitz","Nur bei der IHK Berlin"]}},{"id":"gb-08","typ":"tf","frage":"A taxi operator who has run taxis for 3 years may sell his licence on its own to a colleague without giving up the business.","richtig":false,"erklaerung":"Taxi licences may only be transferred together with the whole business or an independent part. Every transfer also needs approval.","quelle":"§ 2 Abs. 2 und 3 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Ein Taxiunternehmer, der seit 3 Jahren selbst Taxis betreibt, darf seine Genehmigung einzeln an einen Kollegen verkaufen, ohne den Betrieb abzugeben.","erklaerung":"Taxi-Genehmigungen dürfen nur zusammen mit dem ganzen Betrieb oder einem selbständigen Teil übertragen werden. Jede Übertragung braucht außerdem eine Genehmigung."}},{"id":"gb-09","typ":"single","frage":"What must be carried in every taxi or Mietwagen during the trip?","optionen":["Only the driver's licence","The licence or a shortened official copy of it, on paper or electronically","The original equity certificate","The trade registration"],"richtig":1,"erklaerung":"In occasional transport by motor vehicle, the licence or a shortened official copy must be carried and shown on request. Lesson 2.6 covers all other documents.","quelle":"§ 17 Abs. 4 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Was muss in jedem Taxi oder Mietwagen während der Fahrt mitgeführt werden?","erklaerung":"Bei Gelegenheitsverkehr mit Kraftfahrzeugen muss die Genehmigung oder eine gekürzte amtliche Ausfertigung mitgeführt und auf Verlangen gezeigt werden. Welche Dokumente noch dazu gehören, lernst du in Lektion 2.6.","optionen":["Nur der Führerschein des Fahrers","Die Genehmigung oder eine gekürzte amtliche Ausfertigung davon, auf Papier oder elektronisch","Das Original der Eigenkapitalbescheinigung","Der Gewerbeschein"]}},{"id":"gb-10","typ":"tf","frage":"If the authority does not decide on the application within the deadline, the licence is deemed granted.","richtig":true,"erklaerung":"This is called deemed approval (Genehmigungsfiktion).","quelle":"§ 15 Abs. 1 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Wenn die Behörde nicht innerhalb der Frist über den Antrag entscheidet, gilt die Genehmigung als erteilt.","erklaerung":"Das nennt man Genehmigungsfiktion."}},{"id":"gb-11","typ":"single","frage":"A taxi operator dies. What applies to his heirs?","optionen":["The business must stop immediately.","The heirs may continue provisionally and must apply for a licence within 3 months after the period for disclaiming the inheritance ends.","The licence passes to the heirs automatically and without time limit.","The IHK runs the business."],"richtig":1,"erklaerung":"The heirs may continue the business provisionally. The deadline for the application is 3 months after the period for disclaiming the inheritance has ended.","quelle":"§ 19 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Ein Taxiunternehmer stirbt. Was gilt für seine Erben?","erklaerung":"Die Erben dürfen den Betrieb vorläufig weiterführen. Die Frist für den Antrag beträgt 3 Monate nach Ablauf der Frist für die Ausschlagung der Erbschaft.","optionen":["Der Betrieb muss sofort eingestellt werden.","Die Erben dürfen vorläufig weitermachen und müssen innerhalb von 3 Monaten nach Ablauf der Ausschlagungsfrist eine Genehmigung beantragen.","Die Genehmigung geht automatisch und unbefristet auf die Erben über.","Die IHK führt den Betrieb weiter."]}},{"id":"gb-12","typ":"single","frage":"What is a typical reason for the authority to consider a taxi operator unreliable?","optionen":["He has only one vehicle.","He has repeatedly and seriously broken working time rules.","He lives in a different town from his registered office.","He has no commercial training."],"richtig":1,"erklaerung":"Serious breaches of employment and social law duties, especially working and rest times, indicate unreliability.","quelle":"§ 1 Abs. 1 PBZugV","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Was ist ein typischer Grund, warum die Behörde einen Taxiunternehmer als unzuverlässig einstuft?","erklaerung":"Schwere Verstöße gegen arbeits- und sozialrechtliche Pflichten, vor allem Arbeits- und Ruhezeiten, sind Anhaltspunkte für Unzuverlässigkeit.","optionen":["Er hat nur ein Fahrzeug.","Er hat wiederholt schwer gegen Arbeitszeitvorschriften verstoßen.","Er wohnt in einer anderen Stadt als dem Betriebssitz.","Er hat keine kaufmännische Ausbildung."]}},{"id":"gb-13","typ":"single","frage":"How long is the first taxi licence of a new applicant valid?","optionen":["6 months","1 year","2 years","5 years"],"fest":true,"richtig":2,"erklaerung":"New applicants first get the licence for 2 years. During this time the rights and duties may not be transferred.","quelle":"§ 13 Abs. 5 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Wie lange gilt die erste Taxi-Genehmigung für einen Neubewerber?","erklaerung":"Neubewerber bekommen die Genehmigung zunächst für 2 Jahre. In dieser Zeit dürfen Rechte und Pflichten nicht übertragen werden.","optionen":["6 Monate","1 Jahr","2 Jahre","5 Jahre"]}},{"id":"gb-14","typ":"tf","frage":"The owner of the business must always be professionally competent personally.","richtig":false,"erklaerung":"It is enough if the person appointed to manage the business is professionally competent, for example an employed operations manager.","quelle":"§ 13 Abs. 1 Nr. 3 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Die fachliche Eignung muss immer der Inhaber des Unternehmens selbst haben.","erklaerung":"Es reicht, wenn die zur Führung der Geschäfte bestellte Person fachlich geeignet ist, zum Beispiel ein angestellter Betriebsleiter."}},{"id":"gb-15","typ":"single","frage":"Whom does the licensing authority consult, among others, on a taxi or Mietwagen application?","optionen":["The police and the fire brigade","The IHK, the municipality of the office, trade unions and transport associations","Only the tax office","The applicant's health insurer"],"richtig":1,"erklaerung":"§ 14 (2) PBefG names the municipality, trade supervision, IHK, trade unions and transport associations. They have 2 weeks to comment.","quelle":"§ 14 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Wen hört die Genehmigungsbehörde bei einem Antrag für Taxi oder Mietwagen unter anderem an?","erklaerung":"§ 14 Abs. 2 PBefG nennt Gemeinde, Gewerbeaufsicht, IHK, Fachgewerkschaften und Verkehrsverbände. Sie haben 2 Wochen Zeit für eine Stellungnahme.","optionen":["Die Polizei und die Feuerwehr","Die IHK, die Gemeinde des Betriebssitzes, Fachgewerkschaften und Verkehrsverbände","Nur das Finanzamt","Die Krankenkasse des Antragstellers"]}},{"id":"gb-16","typ":"tf","frage":"Anyone who wants to add another Mietwagen to the business does not need a new licence, only a registration at the vehicle registration office.","richtig":false,"erklaerung":"Expanding the business needs approval. The vehicles are listed with their registration numbers in the licence document.","quelle":"§ 2 Abs. 2 Nr. 1, § 17 PBefG","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Wer einen weiteren Mietwagen in seinen Betrieb aufnehmen will, braucht dafür keine neue Genehmigung, sondern meldet ihn nur der Zulassungsstelle.","erklaerung":"Eine Erweiterung des Betriebs braucht eine Genehmigung. Die Fahrzeuge stehen mit Kennzeichen in der Genehmigungsurkunde."}},{"id":"gb-17","typ":"offen","frage":"Name the requirements for a taxi licence and briefly explain how financial standing is proven.","muster":"<p>Requirements under § 13 (1) PBefG: safety and financial capacity of the business, reliability, professional competence, office in Germany. For taxis also: no danger to the functioning of the local taxi trade (§ 13 (4)).</p><p>Financial standing: equity and reserves of at least 2.250 € for the first and 1.250 € for each further vehicle, proven by an equity certificate (max. 1 year old) from a tax adviser, auditor or bank, plus certificates of good standing from the tax office, municipality, health insurers and Berufsgenossenschaft (max. 3 months old).</p><p lang=\"de\"><i>Key German terms: Zuverlässigkeit, fachliche Eignung, finanzielle Leistungsfähigkeit, Eigenkapitalbescheinigung, Unbedenklichkeitsbescheinigung.</i></p>","punkte_liste":[{"t":"Safety and capacity, reliability, competence, office in Germany","p":2},{"t":"Taxi: functioning of the local taxi trade","p":1},{"t":"Amounts 2.250 € / 1.250 €","p":1},{"t":"Equity certificate (tax adviser, auditor or bank)","p":1},{"t":"Certificates of good standing (tax office, municipality, social insurance, BG)","p":1}],"quelle":"§ 13 PBefG, § 2 PBZugV","lek":"genehmigung-berufszugang","sg":"1.1","de":{"frage":"Nennen Sie die Voraussetzungen für die Erteilung einer Genehmigung im Taxenverkehr und erläutern Sie kurz, wie die finanzielle Leistungsfähigkeit nachgewiesen wird.","muster":"<p>Voraussetzungen nach § 13 Abs. 1 PBefG: Sicherheit und Leistungsfähigkeit des Betriebs, Zuverlässigkeit, fachliche Eignung, Betriebssitz im Inland. Beim Taxi außerdem: keine Gefährdung der Funktionsfähigkeit des örtlichen Taxengewerbes (§ 13 Abs. 4).</p><p>Finanzielle Leistungsfähigkeit: Eigenkapital und Reserven mindestens 2.250 € für das erste und 1.250 € für jedes weitere Fahrzeug, nachgewiesen durch Eigenkapitalbescheinigung (max. 1 Jahr alt) eines Steuerberaters, Wirtschaftsprüfers oder einer Bank, dazu Unbedenklichkeitsbescheinigungen von Finanzamt, Gemeinde, Krankenkassen und Berufsgenossenschaft (max. 3 Monate alt).</p>","punkte_liste":["Sicherheit und Leistungsfähigkeit, Zuverlässigkeit, fachliche Eignung, Betriebssitz im Inland","Taxi: Funktionsfähigkeit des örtlichen Taxengewerbes","Beträge 2.250 € / 1.250 €","Eigenkapitalbescheinigung (Steuerberater, WP oder Bank)","Unbedenklichkeitsbescheinigungen (Finanzamt, Gemeinde, SV, BG)"]}},{"id":"ka-01","typ":"single","frage":"Where is the short-term price floor for a trip?","optionen":["At the cost price","At the variable costs of the trip","At 0 €","At the taxi tariff"],"richtig":1,"erklaerung":"Short term the price must cover at least the variable costs. Long term all costs (cost price) must be covered.","quelle":"Kalkulation","lc":true,"lek":"kalkulation","sg":"2.3","de":{"frage":"Wo liegt die kurzfristige Preisuntergrenze für eine Fahrt?","erklaerung":"Kurzfristig muss der Preis mindestens die variablen Kosten decken. Langfristig müssen alle Kosten (Selbstkosten) gedeckt sein.","optionen":["Bei den Selbstkosten","Bei den variablen Kosten der Fahrt","Bei 0 €","Beim Taxitarif"]}},{"id":"ka-02","typ":"zahl","frage":"Cost price of a Mietwagen trip: 180 €. Profit mark-up: 10 %. What is the gross price for a private customer?","richtig":235.62,"einheit":"€","loesung":"180,00 € × 1,10 = 198,00 € net\n198,00 € × 1,19 = 235,62 € gross","erklaerung":"First the mark-up, then 19 % VAT (Mietwagen).","quelle":"Kalkulationsschema","lc":true,"lek":"kalkulation","sg":"2.3","de":{"frage":"Selbstkosten einer Mietwagenfahrt: 180 €. Gewinnzuschlag: 10 %. Wie hoch ist der Bruttopreis für einen Privatkunden?","erklaerung":"Erst Gewinnzuschlag, dann 19 % USt (Mietwagen).","loesung":"180,00 € × 1,10 = 198,00 € netto\n198,00 € × 1,19 = 235,62 € brutto","einheit":"€"}},{"id":"ka-03","typ":"zahl","frage":"A passenger pays 35,70 € gross in the app. The platform keeps 20 % of the net price. How much does the Mietwagen operator receive (net)?","richtig":24,"einheit":"€","loesung":"35,70 € ÷ 1,19 = 30,00 € net\n30,00 € − 20 % (6,00 €) = 24,00 €","erklaerung":"Reverse calculation: first extract VAT, then deduct commission.","quelle":"Rückwärtskalkulation","lc":true,"lek":"kalkulation","sg":"2.3","de":{"frage":"Ein Fahrgast zahlt in der App 35,70 € brutto. Die Plattform behält 20 % vom Nettopreis. Wie viel erhält der Mietwagenunternehmer (netto)?","erklaerung":"Rückwärtskalkulation: erst USt herausrechnen, dann Provision abziehen.","loesung":"35,70 € ÷ 1,19 = 30,00 € netto\n30,00 € − 20 % (6,00 €) = 24,00 €","einheit":"€"}},{"id":"ka-04","typ":"single","frage":"After VAT and commission, a Mietwagen operator keeps 14,00 € from an app trip. The trip is 8 km, the approach 4 km, and without a new booking he must drive 6 km back to the office. Costs: 0,85 € per km. What is the result?","optionen":["Profit 7,20 €","Profit 3,80 €","Loss 1,30 €","Profit 1,30 €"],"fest":true,"richtig":2,"erklaerung":"All km count: 8 + 4 + 6 = 18 km × 0,85 € = 15,30 €. Result: 14,00 € − 15,30 € = −1,30 €. Anyone who only counts the 8 km with a passenger (7,20 €) or forgets the return (3,80 €) gets it wrong.","quelle":"Rückwärtskalkulation, § 49 Abs. 4 PBefG","lc":true,"lek":"kalkulation","sg":"2.3","de":{"frage":"Für eine App-Fahrt bleiben einem Mietwagenunternehmer nach USt und Provision 14,00 €. Die Fahrt ist 8 km lang, die Anfahrt 4 km, danach muss er ohne neuen Auftrag 6 km zum Betriebssitz zurück. Kosten: 0,85 € je km. Wie ist das Ergebnis?","erklaerung":"Alle km zählen: 8 + 4 + 6 = 18 km × 0,85 € = 15,30 €. Ergebnis: 14,00 € − 15,30 € = −1,30 €. Wer nur die 8 km mit Fahrgast rechnet (7,20 €) oder die Rückfahrt vergisst (3,80 €), täuscht sich.","optionen":["Gewinn 7,20 €","Gewinn 3,80 €","Verlust 1,30 €","Gewinn 1,30 €"]}},{"id":"ka-05","typ":"single","frage":"Which costs is the time price (waiting time) in the taxi tariff mainly meant to cover?","optionen":["Fuel and tyres","Driver's wage and owner's salary while the taxi stands or drives slowly","Vehicle tax","VAT"],"richtig":1,"erklaerung":"When the taxi stands still, there are hardly any km costs, but the working time must be paid.","quelle":"Tarifkalkulation","lek":"kalkulation","sg":"2.3","de":{"frage":"Welche Kosten soll vor allem der Zeitpreis (Wartezeit) im Taxitarif decken?","erklaerung":"Wenn das Taxi steht, fallen kaum km-Kosten an, aber die Arbeitszeit muss bezahlt werden.","optionen":["Kraftstoff und Reifen","Fahrer- und Unternehmerlohn während das Taxi steht oder langsam fährt","Die Kfz-Steuer","Die Umsatzsteuer"]}},{"id":"ka-06","typ":"zahl","frage":"Price a quote: 140 km (incl. empty trip) × 1,05 € per km, plus 2 hours waiting × 30 € per hour, plus 12 % profit mark-up. What is the net price?","richtig":231.84,"einheit":"€","loesung":"140 × 1,05 € = 147,00 €\n2 × 30,00 € = 60,00 €\nCost price = 207,00 €\n× 1,12 = 231,84 € net","erklaerung":"Cost price from distance and time, then the mark-up.","quelle":"Angebotskalkulation","lek":"kalkulation","sg":"2.3","de":{"frage":"Kalkuliere ein Angebot: 140 km (inkl. Leerfahrt) × 1,05 € je km, plus 2 Stunden Wartezeit × 30 € je Stunde, plus 12 % Gewinnzuschlag. Wie hoch ist der Nettopreis?","erklaerung":"Selbstkosten aus Strecke und Zeit, dann Gewinnzuschlag.","loesung":"140 × 1,05 € = 147,00 €\n2 × 30,00 € = 60,00 €\nSelbstkosten = 207,00 €\n× 1,12 = 231,84 € netto","einheit":"€"}},{"id":"ka-07","typ":"tf","frage":"A taxi operator may simply agree verbally with a hotel a cheaper fixed price than the tariff for trips within the mandatory service area.","richtig":false,"erklaerung":"Deviations from the tariff within the mandatory service area are only allowed as special agreements under § 51 (2) PBefG, among other things in writing and with approval or notification.","quelle":"§ 51 Abs. 2 PBefG","lek":"kalkulation","sg":"2.3","de":{"frage":"Ein Taxiunternehmer darf mit einem Hotel für Fahrten im Pflichtfahrbereich einfach mündlich einen günstigeren Festpreis als den Tarif vereinbaren.","erklaerung":"Abweichungen vom Tarif im Pflichtfahrbereich sind nur als Sondervereinbarung nach § 51 Abs. 2 PBefG erlaubt, unter anderem schriftlich und mit Genehmigung oder Anzeige."}},{"id":"ka-08","typ":"zahl","frage":"A gross quote for a Mietwagen trip is 297,50 €. What is the net price?","richtig":250,"einheit":"€","loesung":"297,50 € ÷ 1,19 = 250,00 €","erklaerung":"Mietwagen: 19 % VAT.","quelle":"Kalkulation","lek":"kalkulation","sg":"2.3","de":{"frage":"Ein Bruttoangebotspreis für eine Mietwagenfahrt beträgt 297,50 €. Wie hoch ist der Nettopreis?","erklaerung":"Mietwagen: 19 % USt.","loesung":"297,50 € ÷ 1,19 = 250,00 €","einheit":"€"}},{"id":"ka-09","typ":"offen","frage":"A company asks you for a quote for a regular Mietwagen trip. Describe how you calculate the quote price and name two typical mistakes.","muster":"<p>Determine the cost price: all km driven (incl. approach and empty trip) × cost per km, plus waiting time × hourly rate. Add a profit mark-up (profit, risk). Result = net price. Add 19 % VAT (Mietwagen) = gross price. For business customers show net plus VAT. Typical mistakes: forgetting the empty trip, 7 % instead of 19 %, mark-up on gross, forgetting waiting time, confusing cost per occupied km and per km driven.</p>","punkte_liste":[{"t":"Cost price from km (incl. empty trip) and time","p":1},{"t":"Profit mark-up → net price","p":1},{"t":"+ 19 % VAT → gross price","p":1},{"t":"Two typical mistakes named","p":1}],"quelle":"Kalkulation","lek":"kalkulation","sg":"2.3","de":{"frage":"Ein Unternehmen bittet Sie um ein Angebot für eine regelmäßige Mietwagenfahrt. Beschreiben Sie, wie Sie den Angebotspreis kalkulieren, und nennen Sie zwei typische Fehler.","muster":"<p>Selbstkosten ermitteln: alle gefahrenen km (inkl. Anfahrt und Leerfahrt) × Kosten je km, dazu Wartezeit × Stundensatz. Darauf einen Gewinnzuschlag (Gewinn, Risiko). Ergebnis = Nettopreis. Dazu 19 % Umsatzsteuer (Mietwagen) = Bruttopreis. Bei Firmenkunden Netto zzgl. USt ausweisen. Typische Fehler: Leerfahrt vergessen, 7 % statt 19 %, Gewinnzuschlag auf Brutto, Wartezeit vergessen, Kosten je Besetzt-km und je gefahrenem km verwechselt.</p>","punkte_liste":["Selbstkosten aus km (inkl. Leerfahrt) und Zeit","Gewinnzuschlag → Nettopreis","+ 19 % USt → Bruttopreis","Zwei typische Fehler genannt"]}},{"id":"kr-01","typ":"zuordnung","frage":"Fixed or variable? Match each type of cost.","kategorien":["fixed","variable"],"paare":[{"t":"Fuel","k":1,"w":"The more km, the more fuel. A common exam mistake."},{"t":"Motor liability insurance","k":0,"w":"Annual premium, however much you drive."},{"t":"Vehicle tax","k":0,"w":"Fixed annual amount."},{"t":"Tyre wear","k":1,"w":"Tyres wear per km: price ÷ mileage."},{"t":"Time-based depreciation","k":0,"w":"The car loses value every year, even when parked."},{"t":"Radio dispatch fee, flat monthly rate","k":0,"w":"Flat rate per month. A fee per trip would be variable."},{"t":"Platform commission (% of revenue)","k":1,"w":"Rises with every euro of revenue."},{"t":"Imputed owner's salary","k":0,"w":"Your salary as the boss, independent of km."},{"t":"Maintenance at km intervals","k":1,"w":"Service every X km, so it depends on mileage."}],"erklaerung":"Rule of thumb: do I pay this even if I don't drive for a month? Yes = fixed, no = variable.","quelle":"DIHK-Orientierungsrahmen 2.2","lc":true,"lek":"kostenrechnung","sg":"2.2","de":{"frage":"Fix oder variabel? Ordne jede Kostenart zu.","erklaerung":"Faustregel: Zahle ich das auch, wenn ich einen Monat gar nicht fahre? Ja = fix, Nein = variabel.","kategorien":["fix","variabel"],"paare":["Kraftstoff","Kfz-Haftpflichtversicherung","Kfz-Steuer","Reifenverschleiß","Zeitabhängige Abschreibung","Funkgebühr der Taxizentrale, monatlich pauschal","Plattform-Provision (% vom Umsatz)","Kalkulatorischer Unternehmerlohn","Wartung nach km-Intervall"]}},{"id":"kr-02","typ":"zahl","frage":"A taxi costs 38.000 €. After 5 years you want to sell it for 8.000 €. What is the annual depreciation?","richtig":6000,"einheit":"€","loesung":"(38.000 € − 8.000 €) ÷ 5 years = 6.000 € per year","erklaerung":"Formula: (purchase price − residual value) ÷ useful life.","quelle":"Kostenrechnung, Abschreibung","lc":true,"lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Taxi kostet 38.000 €. Nach 5 Jahren willst du es für 8.000 € verkaufen. Wie hoch ist die jährliche Abschreibung?","erklaerung":"Formel: (Anschaffungspreis − Restwert) ÷ Nutzungsdauer.","loesung":"(38.000 € − 8.000 €) ÷ 5 Jahre = 6.000 € pro Jahr","einheit":"€"}},{"id":"kr-03","typ":"zahl","frage":"Same taxi: purchase price 38.000 €, residual value 8.000 €. The imputed interest rate is 6 %. How much is the imputed interest per year?","richtig":1380,"einheit":"€","loesung":"(38.000 € + 8.000 €) ÷ 2 = 23.000 €\n23.000 € × 6 % = 1.380 €","erklaerung":"Interest is calculated on the average capital tied up: (purchase price + residual value) ÷ 2.","quelle":"Kostenrechnung, kalkulatorische Zinsen","lc":true,"lek":"kostenrechnung","sg":"2.2","de":{"frage":"Gleiches Taxi: Anschaffungspreis 38.000 €, Restwert 8.000 €. Der kalkulatorische Zinssatz beträgt 6 %. Wie hoch sind die kalkulatorischen Zinsen pro Jahr?","erklaerung":"Zinsen werden auf das durchschnittlich gebundene Kapital gerechnet: (Anschaffungspreis + Restwert) ÷ 2.","loesung":"(38.000 € + 8.000 €) ÷ 2 = 23.000 €\n23.000 € × 6 % = 1.380 €","einheit":"€"}},{"id":"kr-04","typ":"zahl","frage":"A taxi operator drives 60.000 km per year. His total costs are 49.000 €. What is the cost per km driven? (rounded to 2 decimals)","richtig":0.82,"einheit":"€/km","loesung":"49.000 € ÷ 60.000 km = 0,8167 € ≈ 0,82 €/km","erklaerung":"Cost per km = total costs ÷ km driven.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Taxiunternehmer fährt 60.000 km im Jahr. Seine Gesamtkosten betragen 49.000 €. Wie hoch sind die Kosten je gefahrenem km? (auf 2 Stellen gerundet)","erklaerung":"Kosten je km = Gesamtkosten ÷ gefahrene km.","loesung":"49.000 € ÷ 60.000 km = 0,8167 € ≈ 0,82 €/km","einheit":"€/km"}},{"id":"kr-05","typ":"zahl","frage":"Same business: 60.000 km, total costs 49.000 €. He drives half of all km with a passenger. What is the cost per occupied km?","richtig":1.63,"einheit":"€/km","loesung":"Occupied km = 60.000 km × 50 % = 30.000 km\n49.000 € ÷ 30.000 km = 1,6333 € ≈ 1,63 €/km","erklaerung":"Only the occupied km bring in money. So they must carry all costs.","quelle":"Kostenrechnung","lc":true,"lek":"kostenrechnung","sg":"2.2","de":{"frage":"Gleicher Betrieb: 60.000 km, Gesamtkosten 49.000 €. Die Hälfte aller km fährt er mit Fahrgast. Wie hoch sind die Kosten je Besetzt-km?","erklaerung":"Nur die Besetzt-km bringen Geld. Deshalb müssen sie alle Kosten tragen.","loesung":"Besetzt-km = 60.000 km × 50 % = 30.000 km\n49.000 € ÷ 30.000 km = 1,6333 € ≈ 1,63 €/km","einheit":"€/km"}},{"id":"kr-06","typ":"zahl","frage":"A taxi earns on average 1,10 € per km driven. Variable costs are 0,18 € per km. What is the contribution margin per km?","richtig":0.92,"einheit":"€/km","loesung":"1,10 € − 0,18 € = 0,92 € je km","erklaerung":"Contribution margin = revenue − variable costs.","quelle":"Deckungsbeitragsrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Taxi erlöst im Durchschnitt 1,10 € je gefahrenem km. Die variablen Kosten betragen 0,18 € je km. Wie hoch ist der Deckungsbeitrag je km?","erklaerung":"Deckungsbeitrag = Erlös − variable Kosten.","loesung":"1,10 € − 0,18 € = 0,92 € je km","einheit":"€/km"}},{"id":"kr-07","typ":"zahl","frage":"Fixed costs are 46.000 € per year. The contribution margin is 0,92 € per km. From how many km per year does the business make a profit?","richtig":50000,"einheit":"km","tol":1,"loesung":"46.000 € ÷ 0,92 €/km = 50.000 km","erklaerung":"Break-even point = fixed costs ÷ contribution margin per km.","quelle":"Deckungsbeitragsrechnung","lc":true,"lek":"kostenrechnung","sg":"2.2","de":{"frage":"Die Fixkosten betragen 46.000 € im Jahr. Der Deckungsbeitrag ist 0,92 € je km. Ab wie vielen km pro Jahr macht der Betrieb Gewinn?","erklaerung":"Gewinnschwelle = Fixkosten ÷ Deckungsbeitrag je km.","loesung":"46.000 € ÷ 0,92 €/km = 50.000 km","einheit":"km"}},{"id":"kr-08","typ":"zahl","frage":"A Mietwagen operator has costs of 54.000 € per year. The app keeps 20 % commission of revenue. How much revenue does he need to cover his costs?","richtig":67500,"einheit":"€","loesung":"54.000 € ÷ (1 − 0,20) = 54.000 € ÷ 0,80 = 67.500 €\nCheck: 67.500 € − 20 % (13.500 €) = 54.000 € ✓","erklaerung":"The commission is deducted from revenue. So divide by (1 − rate), don't multiply by (1 + rate).","quelle":"Kostenrechnung, Provision","lc":true,"lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Mietwagenunternehmer hat Kosten von 54.000 € im Jahr. Die App behält 20 % Provision vom Umsatz. Wie viel Umsatz braucht er, um seine Kosten zu decken?","erklaerung":"Die Provision geht vom Umsatz ab. Deshalb durch (1 − Satz) teilen, nicht mit (1 + Satz) multiplizieren.","loesung":"54.000 € ÷ (1 − 0,20) = 54.000 € ÷ 0,80 = 67.500 €\nProbe: 67.500 € − 20 % (13.500 €) = 54.000 € ✓","einheit":"€"}},{"id":"kr-09","typ":"single","frage":"An operator has 5 taxis. The rent for his office applies to all vehicles. What are such costs called?","optionen":["Direct costs (Einzelkosten)","Overheads (Gemeinkosten)","Variable costs","Imputed costs"],"richtig":1,"erklaerung":"Overheads concern several cost centres and are distributed with a key, for example by number of vehicles.","quelle":"Kostenstellenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Unternehmer hat 5 Taxis. Die Miete für sein Büro gilt für alle Fahrzeuge. Wie nennt man solche Kosten?","erklaerung":"Gemeinkosten betreffen mehrere Kostenstellen und werden mit einem Schlüssel verteilt, zum Beispiel nach Anzahl der Fahrzeuge.","optionen":["Einzelkosten","Gemeinkosten","Variable Kosten","Kalkulatorische Kosten"]}},{"id":"kr-10","typ":"zahl","frage":"<p><b>Task (sample values):</b> A taxi costs 45.000 €, residual value after 4 years 15.000 €, imputed interest rate 6 %. Insurance 5.200 €, vehicle tax 220 €, radio 2.400 €, other 980 €, imputed owner's salary 38.000 € per year. Consumption 7 l/100 km, fuel 1,60 €/l net, set of tyres 1.000 € for 50.000 km, maintenance 0,06 €/km. The taxi drives 80.000 km per year, 60 % of them with a passenger.</p><p>a) What are the <b>fixed costs</b> per year?</p>","richtig":56100,"einheit":"€","tol":1,"loesung":"Depreciation = (45.000 − 15.000) ÷ 4         =  7.500 €\nInterest     = (45.000 + 15.000) ÷ 2 × 6 %   =  1.800 €\nInsurance                                   =  5.200 €\nVehicle tax                                 =    220 €\nRadio                                       =  2.400 €\nOther                                       =    980 €\nOwner's salary                              = 38.000 €\nFixed costs                                 = 56.100 €","erklaerung":"All amounts that arise even without driving, plus depreciation, interest and owner's salary.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"<p><b>Aufgabe (Beispielwerte):</b> Ein Taxi kostet 45.000 €, Restwert nach 4 Jahren 15.000 €, kalk. Zinssatz 6 %. Versicherung 5.200 €, Kfz-Steuer 220 €, Funk 2.400 €, Sonstiges 980 €, kalkulatorischer Unternehmerlohn 38.000 € pro Jahr. Verbrauch 7 l/100 km, Kraftstoff 1,60 €/l netto, Reifensatz 1.000 € für 50.000 km, Wartung 0,06 €/km. Das Taxi fährt 80.000 km im Jahr, davon 60 % mit Fahrgast.</p><p>a) Wie hoch sind die <b>Fixkosten</b> pro Jahr?</p>","erklaerung":"Alle Beträge, die auch ohne Fahren anfallen, plus Abschreibung, Zinsen und Unternehmerlohn.","loesung":"Abschreibung = (45.000 − 15.000) ÷ 4         =  7.500 €\nZinsen      = (45.000 + 15.000) ÷ 2 × 6 %   =  1.800 €\nVersicherung                                =  5.200 €\nKfz-Steuer                                  =    220 €\nFunk                                        =  2.400 €\nSonstiges                                   =    980 €\nUnternehmerlohn                             = 38.000 €\nFixkosten                                   = 56.100 €","einheit":"€"}},{"id":"kr-11","typ":"zahl","frage":"<p>Same task. b) What is the <b>cost per km driven</b>? (2 decimals)</p>","richtig":0.89,"einheit":"€/km","loesung":"Fuel       = 7 ÷ 100 × 1,60 €  = 0,112 €/km\nTyres      = 1.000 € ÷ 50.000  = 0,020 €/km\nMaintenance                   = 0,060 €/km\nVariable costs                = 0,192 €/km\n\nVariable costs/year = 0,192 × 80.000 km = 15.360 €\nTotal costs = 56.100 € + 15.360 €         = 71.460 €\nCost per km = 71.460 € ÷ 80.000 km        ≈ 0,89 €/km","erklaerung":"First the variable costs per km, then the total costs, then divide by all km.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"<p>Gleiche Aufgabe. b) Wie hoch sind die <b>Kosten je gefahrenem km</b>? (2 Stellen)</p>","erklaerung":"Erst die variablen Kosten je km, dann die Gesamtkosten, dann durch alle km teilen.","loesung":"Kraftstoff = 7 ÷ 100 × 1,60 €  = 0,112 €/km\nReifen     = 1.000 € ÷ 50.000  = 0,020 €/km\nWartung                       = 0,060 €/km\nVariable Kosten               = 0,192 €/km\n\nVariable Kosten/Jahr = 0,192 × 80.000 km = 15.360 €\nGesamtkosten = 56.100 € + 15.360 €        = 71.460 €\nKosten je km = 71.460 € ÷ 80.000 km       ≈ 0,89 €/km","einheit":"€/km"}},{"id":"kr-12","typ":"zahl","frage":"<p>Same task. c) What is the <b>cost per occupied km</b>? (2 decimals)</p>","richtig":1.49,"einheit":"€/km","loesung":"Occupied km = 80.000 km × 60 % = 48.000 km\n71.460 € ÷ 48.000 km ≈ 1,49 €/km","erklaerung":"Divide total costs only by the km with a passenger.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"<p>Gleiche Aufgabe. c) Wie hoch sind die <b>Kosten je Besetzt-km</b>? (2 Stellen)</p>","erklaerung":"Gesamtkosten nur durch die km mit Fahrgast teilen.","loesung":"Besetzt-km = 80.000 km × 60 % = 48.000 km\n71.460 € ÷ 48.000 km ≈ 1,49 €/km","einheit":"€/km"}},{"id":"kr-13","typ":"tf","frage":"Imputed interest is only included if the operator has taken out a loan.","richtig":false,"erklaerung":"Imputed interest stands for the money tied up in the business that could earn interest elsewhere. It is also included for equity.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Kalkulatorische Zinsen setzt man nur an, wenn der Unternehmer einen Kredit aufgenommen hat.","erklaerung":"Kalkulatorische Zinsen stehen für das Geld, das im Betrieb gebunden ist und anderswo Zinsen bringen könnte. Sie werden auch bei Eigenkapital angesetzt."}},{"id":"kr-14","typ":"single","frage":"Depreciation is calculated by km driven. How do you classify it?","optionen":["Fixed costs","Variable costs","Overheads","It doesn't belong in cost accounting."],"richtig":1,"erklaerung":"Usage-based depreciation rises with every km and is therefore variable. Time-based depreciation is fixed.","quelle":"Kostenrechnung, Abschreibung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Eine Abschreibung wird nach gefahrenen Kilometern berechnet. Wie ordnest du sie ein?","erklaerung":"Leistungsabhängige Abschreibung steigt mit jedem km und ist deshalb variabel. Die zeitabhängige Abschreibung ist fix.","optionen":["Fixkosten","Variable Kosten","Gemeinkosten","Sie gehört nicht in die Kostenrechnung."]}},{"id":"kr-15","typ":"zahl","frage":"A Mietwagen costs 40.000 € and should run 300.000 km during its life. The residual value is then 10.000 €. What is the usage-based depreciation per km?","richtig":0.1,"einheit":"€/km","tol":0.001,"dez":3,"loesung":"(40.000 € − 10.000 €) ÷ 300.000 km = 0,10 €/km","erklaerung":"Usage-based: (purchase price − residual value) ÷ total mileage.","quelle":"Kostenrechnung, Abschreibung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Mietwagen kostet 40.000 € und soll in seiner Nutzungszeit 300.000 km fahren. Der Restwert beträgt dann 10.000 €. Wie hoch ist die leistungsabhängige Abschreibung je km?","erklaerung":"Leistungsabhängig: (Anschaffungspreis − Restwert) ÷ Gesamtlaufleistung.","loesung":"(40.000 € − 10.000 €) ÷ 300.000 km = 0,10 €/km","einheit":"€/km"}},{"id":"kr-16","typ":"zahl","frage":"A taxi has total costs of 63.000 € per year and makes 4.200 trips. What is the cost per trip?","richtig":15,"einheit":"€","loesung":"63.000 € ÷ 4.200 trips = 15,00 € per trip","erklaerung":"Cost per trip = total costs ÷ number of trips.","quelle":"Kostenträgerrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Taxi hat Gesamtkosten von 63.000 € im Jahr und macht 4.200 Fahrten. Wie hoch sind die Kosten je Fahrt?","erklaerung":"Kosten je Fahrt = Gesamtkosten ÷ Anzahl der Fahrten.","loesung":"63.000 € ÷ 4.200 Fahrten = 15,00 € je Fahrt","einheit":"€"}},{"id":"kr-17","typ":"single","frage":"In the cost unit accounting of a taxi business, what is the cost unit (Kostenträger)?","optionen":["The motor insurance","The office","The single trip or the single kilometre","The bank that gives the loan"],"richtig":2,"erklaerung":"Cost unit accounting asks: what were the costs incurred for? That is the service, i.e. the trip or the km.","quelle":"Kostenträgerrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Was ist in der Kostenträgerrechnung eines Taxibetriebs der Kostenträger?","erklaerung":"Die Kostenträgerrechnung fragt: Wofür sind die Kosten entstanden? Das ist die Leistung, also die Fahrt oder der km.","optionen":["Die Kfz-Versicherung","Das Büro","Die einzelne Fahrt oder der einzelne Kilometer","Die Bank, die den Kredit gibt"]}},{"id":"kr-18","typ":"zahl","frage":"A vehicle uses 8 litres per 100 km. A litre costs 1,45 € net. What are the fuel costs per km? (3 decimals)","richtig":0.116,"einheit":"€/km","tol":0.0005,"dez":3,"loesung":"8 l ÷ 100 km × 1,45 €/l = 0,116 €/km","erklaerung":"First divide consumption per 100 km by 100, then multiply by the price per litre.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Ein Fahrzeug verbraucht 8 Liter auf 100 km. Der Liter kostet 1,45 € netto. Wie hoch sind die Kraftstoffkosten je km? (3 Stellen)","erklaerung":"Verbrauch je 100 km erst durch 100 teilen, dann mit dem Literpreis malnehmen.","loesung":"8 l ÷ 100 km × 1,45 €/l = 0,116 €/km","einheit":"€/km"}},{"id":"kr-19","typ":"single","frage":"A Mietwagen business has costs of 80.000 €. The platform keeps 25 % commission. Which calculation gives the revenue needed?","optionen":["80.000 € × 1,25","80.000 € ÷ 0,75","80.000 € + 25 €","80.000 € × 0,75"],"richtig":1,"erklaerung":"Revenue = costs ÷ (1 − 0,25) = 106.666,67 €. Check: 25 % commission = 26.666,67 €, rest 80.000 €.","quelle":"Kostenrechnung, Provision","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Die Kosten eines Mietwagenbetriebs betragen 80.000 €. Die Plattform behält 25 % Provision. Welche Rechnung ergibt den nötigen Umsatz?","erklaerung":"Umsatz = Kosten ÷ (1 − 0,25) = 106.666,67 €. Probe: davon 25 % Provision = 26.666,67 €, Rest 80.000 €.","optionen":["80.000 € × 1,25","80.000 € ÷ 0,75","80.000 € + 25 €","80.000 € × 0,75"]}},{"id":"kr-20","typ":"tf","frage":"In cost accounting you calculate with gross amounts, i.e. including VAT.","richtig":false,"erklaerung":"For businesses entitled to deduct input VAT, VAT is a pass-through item. Cost accounting is always net.","quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"In der Kostenrechnung rechnet man mit Bruttobeträgen, also inklusive Umsatzsteuer.","erklaerung":"Die Umsatzsteuer ist für vorsteuerabzugsberechtigte Unternehmer ein durchlaufender Posten. Kostenrechnung immer netto."}},{"id":"kr-21","typ":"offen","frage":"Explain what the imputed owner's salary is and why it belongs in cost accounting.","muster":"<p>The imputed owner's salary is a notional salary for the work of an owner who works in the business himself. It is not paid out and does not appear in bookkeeping. In cost accounting it is included as a fixed cost so that prices also pay for the owner's own work. Its amount equals the salary of a comparable employee.</p><p lang=\"de\"><i>Key German terms: kalkulatorischer Unternehmerlohn, Fixkosten, Kostenrechnung.</i></p>","punkte_liste":[{"t":"Notional salary for the owner's own work","p":1},{"t":"Not paid out / no expense in bookkeeping","p":1},{"t":"So that prices also cover the owner's work","p":1},{"t":"Amount: like a comparable employee's salary; part of fixed costs","p":1}],"quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Erklären Sie, was der kalkulatorische Unternehmerlohn ist und warum er in die Kostenrechnung gehört.","muster":"<p>Der kalkulatorische Unternehmerlohn ist ein gedachtes Gehalt für die Arbeit des Unternehmers, der selbst im Betrieb mitarbeitet. Er wird nicht ausgezahlt und taucht nicht in der Buchhaltung auf. In der Kostenrechnung wird er als Fixkosten angesetzt, damit die Preise auch die eigene Arbeit bezahlen. Seine Höhe entspricht dem Gehalt eines vergleichbaren Angestellten.</p>","punkte_liste":["Gedachtes Gehalt für die eigene Arbeit des Unternehmers","Wird nicht ausgezahlt / ist kein Aufwand in der Buchführung","Damit die Preise auch die eigene Arbeitsleistung decken","Höhe: wie Gehalt eines vergleichbaren Angestellten; gehört zu den Fixkosten"]}},{"id":"kr-22","typ":"offen","frage":"Explain the difference between fixed and variable costs. Give two examples each from a taxi business.","muster":"<p>Fixed costs arise regardless of mileage, e.g. vehicle tax, insurance, time-based depreciation, owner's salary. Variable costs depend on mileage or revenue, e.g. fuel, tyres, maintenance by km, commission.</p>","punkte_liste":[{"t":"Fixed costs: independent of mileage","p":1},{"t":"Two correct examples of fixed costs","p":1},{"t":"Variable costs: depend on km or revenue","p":1},{"t":"Two correct examples of variable costs","p":1}],"quelle":"Kostenrechnung","lek":"kostenrechnung","sg":"2.2","de":{"frage":"Erklären Sie den Unterschied zwischen fixen und variablen Kosten. Nennen Sie je zwei Beispiele aus dem Taxibetrieb.","muster":"<p>Fixe Kosten fallen unabhängig von der Fahrleistung an, z. B. Kfz-Steuer, Versicherung, zeitabhängige Abschreibung, Unternehmerlohn. Variable Kosten hängen von der Fahrleistung oder vom Umsatz ab, z. B. Kraftstoff, Reifen, Wartung nach km, Provision.</p>","punkte_liste":["Fixe Kosten: unabhängig von der Fahrleistung","Zwei richtige Beispiele für fixe Kosten","Variable Kosten: abhängig von km oder Umsatz","Zwei richtige Beispiele für variable Kosten"]}},{"id":"pz-01","typ":"single","frage":"A passenger living in Germany with Turkish citizenship takes a taxi to Maastricht. Which papers does he need?","optionen":["Only his driving licence","Passport and residence permit","None, there is no ID requirement in the Schengen area","Only a copy of his ID card"],"richtig":1,"erklaerung":"Non-EU citizens need their passport and a valid residence permit. A driving licence is not an ID document.","quelle":"Pass- und Aufenthaltsrecht","lc":true,"lek":"pass-zoll","sg":"5.2","de":{"frage":"Ein Fahrgast mit deutschem Wohnsitz und türkischer Staatsangehörigkeit fährt mit dem Taxi nach Maastricht. Welche Papiere braucht er?","erklaerung":"Drittstaatsangehörige brauchen ihren Pass und einen gültigen Aufenthaltstitel. Ein Führerschein ist kein Ausweis.","optionen":["Nur seinen Führerschein","Reisepass und Aufenthaltstitel","Keine, im Schengen-Raum gibt es keine Ausweispflicht","Nur eine Kopie des Personalausweises"]}},{"id":"pz-02","typ":"single","frage":"What is the guide quantity for cigarettes brought from another EU country for your own use?","optionen":["200 pieces","400 pieces","800 pieces","Unlimited"],"fest":true,"richtig":2,"erklaerung":"800 cigarettes within the EU. From non-EU countries: 200.","quelle":"Zollrecht","lc":true,"lek":"pass-zoll","sg":"5.2","de":{"frage":"Welche Richtmenge gilt für Zigaretten, die man für den eigenen Bedarf aus einem anderen EU-Staat mitbringt?","erklaerung":"800 Zigaretten innerhalb der EU. Aus Drittstaaten: 200 Stück.","optionen":["200 Stück","400 Stück","800 Stück","Unbegrenzt"]}},{"id":"pz-03","typ":"tf","frage":"Because cannabis has been partly legal in Germany since 2024, a passenger may bring small amounts from a Dutch coffee shop to Germany.","richtig":false,"erklaerung":"Adults may possess small amounts in Germany, but importing is not allowed.","quelle":"KCanG","lc":true,"lek":"pass-zoll","sg":"5.2","de":{"frage":"Weil Cannabis in Deutschland seit 2024 teilweise legal ist, darf ein Fahrgast kleine Mengen aus einem niederländischen Coffeeshop nach Deutschland mitbringen.","erklaerung":"Besitz kleiner Mengen ist in Deutschland für Erwachsene erlaubt, die Einfuhr aber nicht."}},{"id":"pz-04","typ":"tf","frage":"Since September 2024 the Federal Police can carry out checks again at the German-Dutch and German-Belgian borders.","richtig":true,"erklaerung":"Temporary internal border checks at all German land borders since 16.9.2024, extended several times.","quelle":"Schengener Grenzkodex","lek":"pass-zoll","sg":"5.2","de":{"frage":"Seit September 2024 kann die Bundespolizei an der deutsch-niederländischen und deutsch-belgischen Grenze wieder Kontrollen durchführen.","erklaerung":"Vorübergehende Binnengrenzkontrollen an allen deutschen Landgrenzen seit 16.9.2024, mehrfach verlängert."}},{"id":"pz-05","typ":"single","frage":"Is a driving licence a valid ID document for crossing the border?","optionen":["Yes, always within the EU","No, you need an ID card or passport","Only the passenger transport permit","Only in Belgium"],"richtig":1,"erklaerung":"The driving licence only proves the right to drive, not identity for border purposes.","quelle":"Passrecht","lek":"pass-zoll","sg":"5.2","de":{"frage":"Ist ein Führerschein ein gültiges Ausweisdokument für den Grenzübertritt?","erklaerung":"Der Führerschein weist nur die Fahrerlaubnis nach, nicht die Identität für Grenzzwecke.","optionen":["Ja, innerhalb der EU immer","Nein, man braucht Personalausweis oder Reisepass","Nur der Führerschein zur Fahrgastbeförderung","Nur in Belgien"]}},{"id":"pz-06","typ":"multi","frage":"Which goods may not be taken across the border, or only with a permit? Select all correct answers.","optionen":["Narcotics","Weapons and ammunition","Unapproved fireworks","A crate of beer for your own use","Coffee for your own use"],"richtig":[0,1,2],"erklaerung":"Goods for your own use within the EU are in principle free.","quelle":"Zollrecht, BtMG, WaffG, SprengG","lek":"pass-zoll","sg":"5.2","de":{"frage":"Welche Waren dürfen nicht bzw. nur mit Erlaubnis über die Grenze mitgenommen werden? Wähle alle richtigen.","erklaerung":"Waren für den eigenen Bedarf innerhalb der EU sind grundsätzlich frei.","optionen":["Betäubungsmittel","Waffen und Munition","Nicht zugelassenes Feuerwerk","Ein Kasten Bier für den eigenen Bedarf","Kaffee für den eigenen Bedarf"]}},{"id":"pa-01","typ":"single","frage":"A candidate has 27 of 60 points in part 1 and 45 of 52,5 points in part 2. What applies?","optionen":["Passed, because 72 points together","Oral exam, because below 90 points","Failed, because part 1 is below 50 %","Passed, because part 2 is very good"],"richtig":2,"erklaerung":"Each written part needs at least 50 %. Part 1 has 27 of 60 = 45 %. There is then no oral exam.","quelle":"§ 4 Abs. 4 und 5 PBZugV","lc":true,"lek":"pruefung-ablauf","sg":"–","de":{"frage":"Ein Prüfling hat in Teil 1 27 von 60 Punkten und in Teil 2 45 von 52,5 Punkten. Was gilt?","erklaerung":"Jeder schriftliche Teil braucht mindestens 50 %. Teil 1 hat 27 von 60 = 45 %. Die mündliche Prüfung entfällt dann.","optionen":["Bestanden, weil zusammen 72 Punkte","Mündliche Prüfung, weil unter 90 Punkte","Nicht bestanden, weil Teil 1 unter 50 % liegt","Bestanden, weil Teil 2 sehr gut ist"]}},{"id":"pa-02","typ":"multi","frage":"Which tips help with calculations in the exam? Select all correct answers.","optionen":["Write down every step with formula and unit","Round only at the end","Check the result for plausibility","Only write the final result, it saves time","Calculate with gross amounts if nothing is stated"],"richtig":[0,1,2],"erklaerung":"You get partial points for the method. Cost accounting without a statement: net.","quelle":"Prüfungstaktik","lc":true,"lek":"pruefung-ablauf","sg":"–","de":{"frage":"Welche Tipps helfen bei Rechenaufgaben in der Prüfung? Wähle alle richtigen.","erklaerung":"Für den Rechenweg gibt es Teilpunkte. Kostenrechnung ohne Angabe: netto.","optionen":["Jeden Schritt mit Formel und Einheit aufschreiben","Erst am Ende runden","Ergebnis auf Plausibilität prüfen","Nur das Endergebnis hinschreiben, das spart Zeit","Mit Bruttobeträgen rechnen, wenn nichts angegeben ist"]}},{"id":"pa-03","typ":"zahl","frage":"A candidate has 38 points in written part 1 and 32 points in part 2. How many points does he need at least in the oral exam to pass?","richtig":20,"einheit":"points","tol":0.01,"dez":0,"loesung":"Written: 38 + 32 = 70\nNeeded: 90 − 70 = 20 points (of 37,5)","erklaerung":"Both parts above 50 % (30 and 26,25), together below 90 → oral exam. Total at least 90.","quelle":"§ 4 PBZugV","lek":"pruefung-ablauf","sg":"–","de":{"frage":"Ein Prüfling hat schriftlich 38 Punkte in Teil 1 und 32 Punkte in Teil 2. Wie viele Punkte braucht er in der mündlichen Prüfung mindestens, um zu bestehen?","erklaerung":"Beide Teile über 50 % (30 bzw. 26,25), zusammen unter 90 → mündlich. Gesamt mindestens 90.","loesung":"Schriftlich: 38 + 32 = 70\nNötig: 90 − 70 = 20 Punkte (von 37,5)","einheit":"Punkte"}},{"id":"pa-04","typ":"single","frage":"At which IHK does a candidate take the professional competence exam for taxi and Mietwagen?","optionen":["At the IHK of the registered office","At the IHK where he lives","At any IHK of his choice","Only at the DIHK in Berlin"],"richtig":1,"erklaerung":"§ 5 (4) PBZugV: place of residence (for buses: place of work).","quelle":"§ 5 Abs. 4 PBZugV","lek":"pruefung-ablauf","sg":"–","de":{"frage":"Bei welcher IHK legt ein Bewerber die Fachkundeprüfung für Taxi und Mietwagen ab?","erklaerung":"§ 5 Abs. 4 PBZugV: Wohnsitz (bei Bussen: Arbeitsort).","optionen":["Bei der IHK am Betriebssitz","Bei der IHK am Wohnsitz","Bei jeder IHK nach Wahl","Nur beim DIHK in Berlin"]}},{"id":"pa-05","typ":"tf","frage":"Anyone who scores at least 90 points in writing and is above 50 % in both parts does not have to take the oral exam.","richtig":true,"erklaerung":"The oral exam is dropped if 60 % of the total points have already been reached.","quelle":"§ 4 Abs. 5 PBZugV","lek":"pruefung-ablauf","sg":"–","de":{"frage":"Wer schriftlich mindestens 90 Punkte erreicht und in beiden Teilen über 50 % liegt, muss nicht mehr in die mündliche Prüfung.","erklaerung":"Die mündliche Prüfung entfällt, wenn schon 60 % der Gesamtpunkte erreicht sind."}},{"id":"sv-01","typ":"zuordnung","frage":"Who pays the contributions? Match them.","kategorien":["employer and employee","employer only"],"paare":[{"t":"Pension insurance","k":0,"w":"18,6 %, half each."},{"t":"Unemployment insurance","k":0,"w":"2,6 %, half each."},{"t":"Health insurance","k":0,"w":"14,6 % + additional rate, half each."},{"t":"Accident insurance (Berufsgenossenschaft)","k":1,"w":"Paid by the employer alone."},{"t":"U1 levy (refund for sickness)","k":1,"w":"Levies are paid by the employer alone."},{"t":"Long-term care insurance (basic rate)","k":0,"w":"3,6 %, half each; the childless surcharge is paid by the employee only."}],"erklaerung":"Remember: accident insurance and levies are borne by the employer only.","quelle":"SGB IV, VII","lc":true,"lek":"sozialversicherung","sg":"1.5","de":{"frage":"Wer zahlt die Beiträge? Ordne zu.","erklaerung":"Merke: Unfallversicherung und Umlagen trägt nur der Arbeitgeber.","kategorien":["Arbeitgeber und Arbeitnehmer","nur Arbeitgeber"],"paare":["Rentenversicherung","Arbeitslosenversicherung","Krankenversicherung","Unfallversicherung (Berufsgenossenschaft)","Umlage U1 (Erstattung bei Krankheit)","Pflegeversicherung (Grundbeitrag)"]}},{"id":"sv-02","typ":"single","frage":"By when must a taxi operator report a new driver by immediate notification (Sofortmeldung)?","optionen":["At the latest when employment starts","Within 2 weeks","With the first payroll","Within 6 weeks"],"richtig":0,"erklaerung":"In the passenger transport trade the immediate notification applies: at the latest when employment starts, to the pension insurance data office.","quelle":"§ 28a Abs. 4 SGB IV","lc":true,"lek":"sozialversicherung","sg":"1.5","de":{"frage":"Bis wann muss ein Taxiunternehmer einen neuen Fahrer per Sofortmeldung melden?","erklaerung":"Im Personenbeförderungsgewerbe gilt die Sofortmeldepflicht: spätestens bei Aufnahme der Beschäftigung an die Datenstelle der Rentenversicherung.","optionen":["Spätestens bei Beginn der Beschäftigung","Innerhalb von 2 Wochen","Mit der ersten Lohnabrechnung","Innerhalb von 6 Wochen"]}},{"id":"sv-03","typ":"single","frage":"To whom does the employer pay the total social insurance contribution for a driver subject to insurance?","optionen":["To the tax office","To the employee's health insurer as collecting agency","Directly to the pension insurance","To the Berufsgenossenschaft"],"richtig":1,"erklaerung":"The health insurer is the collecting agency and passes contributions on to pension, unemployment and care insurance. Accident insurance goes to the BG.","quelle":"§ 28h SGB IV","lc":true,"lek":"sozialversicherung","sg":"1.5","de":{"frage":"An wen zahlt der Arbeitgeber den Gesamtsozialversicherungsbeitrag für einen sozialversicherungspflichtigen Fahrer?","erklaerung":"Die Krankenkasse ist Einzugsstelle und verteilt die Beiträge an Renten-, Arbeitslosen- und Pflegeversicherung. Die Unfallversicherung geht an die BG.","optionen":["An das Finanzamt","An die Krankenkasse des Arbeitnehmers als Einzugsstelle","Direkt an die Rentenversicherung","An die Berufsgenossenschaft"]}},{"id":"sv-04","typ":"single","frage":"An operator has drivers working in his taxis as “subcontractors”. He sets the shifts; the drivers have no vehicle and no customers of their own. What happens at an audit?","optionen":["Nothing, because there are subcontractor agreements","Classification as employees; back payment of contributions including the employee's share, late surcharges, possibly criminal proceedings","Only a notice from the IHK","The drivers must pay the contributions alone."],"richtig":1,"erklaerung":"This is typical bogus self-employment. Back claims up to 4 years, with intent up to 30 years. Withholding contributions is a crime under § 266a StGB.","quelle":"§§ 7, 25 SGB IV, § 266a StGB","lc":true,"lek":"sozialversicherung","sg":"1.5","de":{"frage":"Ein Unternehmer lässt Fahrer als „Subunternehmer“ in seinen Taxis fahren. Er bestimmt die Schichten, die Fahrer haben kein eigenes Fahrzeug und keine eigenen Kunden. Was droht bei einer Prüfung?","erklaerung":"Das ist typische Scheinselbständigkeit. Nachforderung bis 4 Jahre, bei Vorsatz bis 30 Jahre. Vorenthalten von Beiträgen ist nach § 266a StGB strafbar.","optionen":["Nichts, weil Verträge mit Subunternehmern bestehen","Einstufung als Arbeitnehmer; Nachzahlung der Beiträge inklusive Arbeitnehmeranteil, Säumniszuschläge, eventuell Strafverfahren","Nur ein Hinweis der IHK","Die Fahrer müssen die Beiträge allein nachzahlen."]}},{"id":"sv-05","typ":"single","frage":"What is the pension insurance contribution rate in 2026?","optionen":["9,3 %","14,6 %","18,6 %","20,0 %"],"fest":true,"richtig":2,"erklaerung":"18,6 %, half each paid by employer and employee (9,3 % each).","quelle":"Rechengrößen 2026","lek":"sozialversicherung","sg":"1.5","de":{"frage":"Wie hoch ist der Beitragssatz zur Rentenversicherung 2026?","erklaerung":"18,6 %, je zur Hälfte von Arbeitgeber und Arbeitnehmer (je 9,3 %).","optionen":["9,3 %","14,6 %","18,6 %","20,0 %"]}},{"id":"sv-06","typ":"tf","frage":"A taxi operator without employees does not need to be insured with the Berufsgenossenschaft.","richtig":false,"erklaerung":"Taxi and Mietwagen operators are insured themselves under the statutes of BG Verkehr. The Federal Constitutional Court has confirmed this for taxi operators.","quelle":"Satzung BG Verkehr, § 3 SGB VII","lek":"sozialversicherung","sg":"1.5","de":{"frage":"Ein Taxiunternehmer ohne Angestellte muss nicht bei der Berufsgenossenschaft versichert sein.","erklaerung":"Taxi- und Mietwagenunternehmer sind kraft Satzung der BG Verkehr selbst pflichtversichert. Das Bundesverfassungsgericht hat das für Taxiunternehmer bestätigt."}},{"id":"sv-07","typ":"single","frage":"When is the total social insurance contribution due?","optionen":["On the 15th of the following month","On the third-to-last bank working day of the month in which the work was done","Once a year on 31 December","On the 10th of the following month, like VAT"],"richtig":1,"erklaerung":"§ 23 (1) SGB IV: third-to-last bank working day of the current month.","quelle":"§ 23 SGB IV","lek":"sozialversicherung","sg":"1.5","de":{"frage":"Wann ist der Gesamtsozialversicherungsbeitrag fällig?","erklaerung":"§ 23 Abs. 1 SGB IV: drittletzter Bankarbeitstag des laufenden Monats.","optionen":["Am 15. des Folgemonats","Am drittletzten Bankarbeitstag des Monats, in dem gearbeitet wurde","Einmal im Jahr am 31. Dezember","Am 10. des Folgemonats, wie die Umsatzsteuer"]}},{"id":"sv-08","typ":"single","frage":"A self-employed Mietwagen operator has no employees and almost only takes bookings from one platform. What should he have checked?","optionen":["Whether he gets child benefit","Whether he is subject to pension insurance as an employee-like self-employed person","Whether he can save VAT","Whether he needs a tachograph"],"richtig":1,"erklaerung":"Self-employed people without employees subject to insurance who work essentially for one client are subject to pension insurance.","quelle":"§ 2 Satz 1 Nr. 9 SGB VI","lek":"sozialversicherung","sg":"1.5","de":{"frage":"Ein selbständiger Mietwagenunternehmer hat keine Angestellten und fährt fast ausschließlich Aufträge einer einzigen Plattform. Was sollte er prüfen lassen?","erklaerung":"Selbständige ohne versicherungspflichtige Arbeitnehmer, die im Wesentlichen nur für einen Auftraggeber tätig sind, sind rentenversicherungspflichtig.","optionen":["Ob er Kindergeld bekommt","Ob er als arbeitnehmerähnlicher Selbständiger rentenversicherungspflichtig ist","Ob er Mehrwertsteuer sparen kann","Ob er einen Fahrtenschreiber braucht"]}},{"id":"sv-09","typ":"tf","frage":"In the taxi trade, no immediate notification is needed for mini-jobbers.","richtig":false,"erklaerung":"The immediate notification applies to all employees in the passenger transport trade, including mini-jobbers.","quelle":"§ 28a Abs. 4 SGB IV","lek":"sozialversicherung","sg":"1.5","de":{"frage":"Für Minijobber muss im Taxigewerbe keine Sofortmeldung abgegeben werden.","erklaerung":"Die Sofortmeldung gilt für alle Beschäftigten im Personenbeförderungsgewerbe, auch für Minijobber."}},{"id":"sv-10","typ":"zahl","frage":"A driver earns 2.500 € gross per month. How much is the employer's share of pension insurance in 2026?","richtig":232.5,"einheit":"€","loesung":"18,6 % ÷ 2 = 9,3 %\n2.500 € × 9,3 % = 232,50 €","erklaerung":"Employer and employee each pay half.","quelle":"SGB VI, Beitragssatz 2026","lek":"sozialversicherung","sg":"1.5","de":{"frage":"Ein Fahrer verdient 2.500 € brutto im Monat. Wie hoch ist der Arbeitgeberanteil zur Rentenversicherung 2026?","erklaerung":"Arbeitgeber und Arbeitnehmer zahlen je die Hälfte.","loesung":"18,6 % ÷ 2 = 9,3 %\n2.500 € × 9,3 % = 232,50 €","einheit":"€"}},{"id":"sv-11","typ":"offen","frage":"Which notification duties does a taxi operator have when hiring a new driver subject to social insurance?","muster":"<p>Employer number from the Federal Employment Agency (if not yet available). Immediate notification at the latest when employment starts, to the pension insurance data office (§ 28a (4) SGB IV, passenger transport trade). Registration with the health insurer (collecting agency) with the first payroll, at the latest within 6 weeks (DEÜV). Contribution statement and payment by the third-to-last bank working day. Payroll report to the Berufsgenossenschaft. At the end: deregistration.</p><p lang=\"de\"><i>Key German terms: Sofortmeldung, Anmeldung, Einzugsstelle, Betriebsnummer, Beitragsnachweis.</i></p>","punkte_liste":[{"t":"Immediate notification at the latest when employment starts","p":2},{"t":"Registration with the health insurer (within 6 weeks / first payroll)","p":1},{"t":"Employer number, contribution statement or report to the BG","p":1}],"quelle":"§ 28a SGB IV, DEÜV","lek":"sozialversicherung","sg":"1.5","de":{"frage":"Welche Meldepflichten hat ein Taxiunternehmer, wenn er einen neuen sozialversicherungspflichtigen Fahrer einstellt?","muster":"<p>Betriebsnummer bei der Bundesagentur für Arbeit (falls noch nicht vorhanden). Sofortmeldung spätestens bei Beschäftigungsbeginn an die Datenstelle der Rentenversicherung (§ 28a Abs. 4 SGB IV, Personenbeförderungsgewerbe). Anmeldung bei der Krankenkasse (Einzugsstelle) mit der ersten Lohnabrechnung, spätestens innerhalb von 6 Wochen (DEÜV). Beitragsnachweis und Zahlung zum drittletzten Bankarbeitstag. Lohnnachweis an die Berufsgenossenschaft. Bei Ende: Abmeldung.</p>","punkte_liste":["Sofortmeldung spätestens bei Beschäftigungsbeginn","Anmeldung bei der Krankenkasse (spätestens 6 Wochen / erste Abrechnung)","Betriebsnummer, Beitragsnachweis oder Meldung an die BG"]}},{"id":"st-01","typ":"zuordnung","frage":"Which VAT rate applies?","kategorien":["7 %","19 %"],"paare":[{"t":"Taxi within the city of Aachen, 15 km","k":0,"w":"Taxi within one municipality."},{"t":"Taxi from Aachen to Eschweiler, 18 km","k":0,"w":"Different municipality, but not more than 50 km."},{"t":"Taxi from Aachen to Cologne, 72 km","k":1,"w":"Over 50 km and not within one municipality."},{"t":"Mietwagen within Aachen, 6 km","k":1,"w":"Mietwagen are not covered by § 12 (2) No. 10 UStG."},{"t":"Taxi within Berlin, 55 km","k":0,"w":"Within one municipality 7 % applies, even over 50 km."}],"erklaerung":"7 % only for taxis: within one municipality OR distance at most 50 km.","quelle":"§ 12 Abs. 2 Nr. 10 UStG","lc":true,"lek":"steuern","sg":"1.8","de":{"frage":"Welcher Umsatzsteuersatz gilt?","erklaerung":"7 % nur für Taxen: innerhalb einer Gemeinde ODER Strecke höchstens 50 km.","kategorien":["7 %","19 %"],"paare":["Taxi innerhalb der Stadt Aachen, 15 km","Taxi von Aachen nach Eschweiler, 18 km","Taxi von Aachen nach Köln, 72 km","Mietwagen innerhalb von Aachen, 6 km","Taxi innerhalb von Berlin, 55 km"]}},{"id":"st-02","typ":"zahl","frage":"A passenger pays 32,10 € for a taxi trip in town. How much VAT is included?","richtig":2.1,"einheit":"€","loesung":"32,10 € × 7 ÷ 107 = 2,10 €","erklaerung":"From the gross amount: × rate ÷ (100 + rate).","quelle":"§ 12 UStG","lc":true,"lek":"steuern","sg":"1.8","de":{"frage":"Ein Fahrgast zahlt für eine Taxifahrt in der Stadt 32,10 €. Wie viel Umsatzsteuer ist darin enthalten?","erklaerung":"Aus dem Bruttobetrag: × Steuersatz ÷ (100 + Steuersatz).","loesung":"32,10 € × 7 ÷ 107 = 2,10 €","einheit":"€"}},{"id":"st-03","typ":"zahl","frage":"A taxi operator collected 3.120 € VAT in the quarter. He paid 980 € input VAT. How much VAT is payable?","richtig":2140,"einheit":"€","tol":0.5,"loesung":"3.120 € − 980 € = 2.140 €","erklaerung":"VAT payable = VAT − input VAT.","quelle":"§§ 15, 18 UStG","lc":true,"lek":"steuern","sg":"1.8","de":{"frage":"Ein Taxiunternehmer hat im Quartal 3.120 € Umsatzsteuer eingenommen. Er hat 980 € Vorsteuer bezahlt. Wie hoch ist die Zahllast?","erklaerung":"Zahllast = Umsatzsteuer − Vorsteuer.","loesung":"3.120 € − 980 € = 2.140 €","einheit":"€"}},{"id":"st-04","typ":"multi","frage":"What applies to small businesses under § 19 UStG? Select all correct answers.","optionen":["Turnover in the previous year at most 25.000 €","Turnover in the current year at most 100.000 €","No VAT shown on invoices","No input VAT deduction","Duty to file monthly advance returns"],"richtig":[0,1,2,3],"erklaerung":"Small businesses are exempt from VAT but may not deduct input VAT either. Advance returns are not required.","quelle":"§ 19 UStG","lc":true,"lek":"steuern","sg":"1.8","de":{"frage":"Was gilt für Kleinunternehmer nach § 19 UStG? Wähle alle richtigen.","erklaerung":"Kleinunternehmer sind von der Umsatzsteuer befreit, dürfen aber auch keine Vorsteuer abziehen. Voranmeldungen entfallen.","optionen":["Umsatz im Vorjahr höchstens 25.000 €","Umsatz im laufenden Jahr höchstens 100.000 €","Kein Ausweis von Umsatzsteuer","Kein Vorsteuerabzug","Pflicht zu monatlicher Voranmeldung"]}},{"id":"st-05","typ":"multi","frage":"What must at least be on a taxi receipt for 38,50 €? Select all correct answers.","optionen":["Full name and address of the operator","Date of issue","Type and scope of the service","Fare and tax in one sum","Tax rate","Name and address of the passenger","Sequential invoice number"],"richtig":[0,1,2,3,4],"erklaerung":"Up to 250 € gross a small-amount invoice under § 33 UStDV is enough. The customer's name and an invoice number are not needed there.","quelle":"§ 33 UStDV","lc":true,"lek":"steuern","sg":"1.8","de":{"frage":"Was muss auf einer Taxiquittung über 38,50 € mindestens stehen? Wähle alle richtigen.","erklaerung":"Bis 250 € brutto reicht eine Kleinbetragsrechnung nach § 33 UStDV. Name des Kunden und Rechnungsnummer sind dort nicht nötig.","optionen":["Vollständiger Name und Anschrift des Unternehmers","Ausstellungsdatum","Art und Umfang der Leistung","Entgelt und Steuerbetrag in einer Summe","Steuersatz","Name und Anschrift des Fahrgasts","Fortlaufende Rechnungsnummer"]}},{"id":"st-06","typ":"tf","frage":"Since 1 January 2026 every taximeter must have a certified technical security device (TSE).","richtig":true,"erklaerung":"The transition rule for EU taximeters ended on 31.12.2025. Taximeters and odometers are electronic recording systems under § 146a AO.","quelle":"§ 146a AO, KassenSichV","lc":true,"lek":"steuern","sg":"1.8","de":{"frage":"Seit dem 1. Januar 2026 muss jeder Taxameter mit einer zertifizierten technischen Sicherheitseinrichtung (TSE) ausgestattet sein.","erklaerung":"Die Übergangsregel für EU-Taxameter endete am 31.12.2025. Taxameter und Wegstreckenzähler sind elektronische Aufzeichnungssysteme nach § 146a AO."}},{"id":"st-07","typ":"zahl","frage":"A sole proprietor has trade income of 60.000 €. The municipal multiplier is 400 %. How much is the trade tax?","richtig":4970,"einheit":"€","tol":0.5,"loesung":"60.000 € − 24.500 € = 35.500 €\n35.500 € × 3,5 % = 1.242,50 € base amount\n1.242,50 € × 400 % = 4.970,00 €","erklaerung":"(Trade income − allowance) × base rate × multiplier.","quelle":"§§ 11, 16 GewStG","lc":true,"lek":"steuern","sg":"1.8","de":{"frage":"Ein Einzelunternehmer hat einen Gewerbeertrag von 60.000 €. Der Hebesatz beträgt 400 %. Wie hoch ist die Gewerbesteuer?","erklaerung":"(Gewerbeertrag − Freibetrag) × Messzahl × Hebesatz.","loesung":"60.000 € − 24.500 € = 35.500 €\n35.500 € × 3,5 % = 1.242,50 € Messbetrag\n1.242,50 € × 400 % = 4.970,00 €","einheit":"€"}},{"id":"st-08","typ":"zahl","frage":"A customer pays 142,80 € gross for a Mietwagen trip. What is the net amount?","richtig":120,"einheit":"€","loesung":"142,80 € ÷ 1,19 = 120,00 €","erklaerung":"Mietwagen: 19 %. Net = gross ÷ 1,19.","quelle":"§ 12 Abs. 1 UStG","lek":"steuern","sg":"1.8","de":{"frage":"Ein Kunde zahlt für eine Mietwagenfahrt 142,80 € brutto. Wie hoch ist der Nettobetrag?","erklaerung":"Mietwagen: 19 %. Netto = Brutto ÷ 1,19.","loesung":"142,80 € ÷ 1,19 = 120,00 €","einheit":"€"}},{"id":"st-09","typ":"tf","frage":"For VAT purposes a taxi receipt counts as a ticket (Fahrausweis) under § 34 UStDV.","richtig":false,"erklaerung":"Invoices for using a taxi or Mietwagen are not tickets (UStAE 14.7). Up to 250 € they are small-amount invoices.","quelle":"UStAE 14.7, § 33 UStDV","lek":"steuern","sg":"1.8","de":{"frage":"Eine Taxiquittung gilt umsatzsteuerlich als Fahrausweis nach § 34 UStDV.","erklaerung":"Rechnungen über die Benutzung eines Taxis oder Mietwagens sind keine Fahrausweise (UStAE 14.7). Bis 250 € sind sie Kleinbetragsrechnungen."}},{"id":"st-10","typ":"single","frage":"By when must the advance VAT return for the 2nd quarter (without permanent extension) reach the tax office?","optionen":["30 June","10 July","31 July","10 August"],"richtig":1,"erklaerung":"By the 10th day after the end of the return period.","quelle":"§ 18 Abs. 1 UStG","lek":"steuern","sg":"1.8","de":{"frage":"Bis wann muss die Umsatzsteuer-Voranmeldung für das 2. Quartal (ohne Dauerfristverlängerung) beim Finanzamt sein?","erklaerung":"Bis zum 10. Tag nach Ablauf des Voranmeldungszeitraums.","optionen":["30. Juni","10. Juli","31. Juli","10. August"]}},{"id":"st-11","typ":"single","frage":"When must an operator file advance VAT returns monthly?","optionen":["Always","If the tax in the previous year was more than 9.000 €","If he has more than 2 vehicles","Only in the first year"],"richtig":1,"erklaerung":"The standard period is the calendar quarter; monthly if the previous year's tax was over 9.000 €.","quelle":"§ 18 Abs. 2 UStG","lek":"steuern","sg":"1.8","de":{"frage":"Wann muss ein Unternehmer die Umsatzsteuer-Voranmeldung monatlich abgeben?","erklaerung":"Regelzeitraum ist das Kalendervierteljahr; monatlich bei Vorjahressteuer über 9.000 €.","optionen":["Immer","Wenn die Steuer im Vorjahr mehr als 9.000 € betrug","Wenn er mehr als 2 Fahrzeuge hat","Nur im ersten Jahr"]}},{"id":"st-12","typ":"single","frage":"Which businesses get the 24.500 € trade tax allowance?","optionen":["All businesses","Sole proprietorships and partnerships","Only GmbHs","Only small businesses under § 19 UStG"],"richtig":1,"erklaerung":"Natural persons and partnerships. Capital companies get no allowance.","quelle":"§ 11 Abs. 1 GewStG","lek":"steuern","sg":"1.8","de":{"frage":"Für welche Unternehmen gilt der Freibetrag von 24.500 € bei der Gewerbesteuer?","erklaerung":"Natürliche Personen und Personengesellschaften. Kapitalgesellschaften erhalten keinen Freibetrag.","optionen":["Für alle Unternehmen","Für Einzelunternehmen und Personengesellschaften","Nur für GmbH","Nur für Kleinunternehmer nach § 19 UStG"]}},{"id":"st-13","typ":"single","frage":"A taxi operator buys a new electric taxi, first registered in 2026. What applies to vehicle tax?","optionen":["Full vehicle tax by weight","Exempt for 10 years from first registration, at most until 31.12.2035","Exempt forever","Only half vehicle tax"],"richtig":1,"erklaerung":"§ 3d KraftStG: first registration by 31.12.2030, exemption 10 years, at most until 31.12.2035.","quelle":"§ 3d KraftStG","lek":"steuern","sg":"1.8","de":{"frage":"Ein Taxiunternehmer kauft ein neues Elektro-Taxi mit Erstzulassung im Jahr 2026. Was gilt für die Kfz-Steuer?","erklaerung":"§ 3d KraftStG: Erstzulassung bis 31.12.2030, Befreiung 10 Jahre, längstens bis 31.12.2035.","optionen":["Volle Kfz-Steuer nach Gewicht","Befreit für 10 Jahre ab Erstzulassung, längstens bis 31.12.2035","Befreit für immer","Nur halbe Kfz-Steuer"]}},{"id":"st-14","typ":"single","frage":"Who is responsible for vehicle tax?","optionen":["The tax office","The municipality","Customs (main customs office)","The vehicle registration office"],"richtig":2,"erklaerung":"Vehicle tax is administered by customs.","quelle":"KraftStG","lek":"steuern","sg":"1.8","de":{"frage":"Wer ist für die Kfz-Steuer zuständig?","erklaerung":"Die Kfz-Steuer verwaltet die Zollverwaltung.","optionen":["Das Finanzamt","Die Gemeinde","Der Zoll (Hauptzollamt)","Die Zulassungsstelle"]}},{"id":"st-15","typ":"single","frage":"When are income tax advance payments due?","optionen":["Monthly on the 10th","10 March, 10 June, 10 September, 10 December","Once a year on 31 May","15 February, 15 May, 15 August, 15 November"],"richtig":1,"erklaerung":"§ 37 (1) EStG.","quelle":"§ 37 EStG","lek":"steuern","sg":"1.8","de":{"frage":"Wann sind die Einkommensteuer-Vorauszahlungen fällig?","erklaerung":"§ 37 Abs. 1 EStG.","optionen":["Monatlich am 10.","10. März, 10. Juni, 10. September, 10. Dezember","Einmal jährlich am 31. Mai","15. Februar, 15. Mai, 15. August, 15. November"]}},{"id":"st-16","typ":"tf","frage":"A taxi operator may only deduct the input VAT from a garage invoice if he has a proper invoice.","richtig":true,"erklaerung":"A proper invoice under §§ 14, 14a UStG is a condition for input VAT deduction.","quelle":"§ 15 Abs. 1 UStG","lek":"steuern","sg":"1.8","de":{"frage":"Ein Taxiunternehmer darf die Vorsteuer aus einer Werkstattrechnung nur abziehen, wenn er eine ordnungsgemäße Rechnung hat.","erklaerung":"Voraussetzung für den Vorsteuerabzug ist eine Rechnung nach §§ 14, 14a UStG."}},{"id":"st-17","typ":"offen","frage":"Explain when a taxi trip is subject to the reduced VAT rate and what applies to Mietwagen trips. Extract the VAT from a fare of 53,50 € (taxi, in town).","muster":"<p>Taxi trips are subject to 7 % if they take place within one municipality or the distance is not more than 50 km (§ 12 (2) No. 10 UStG). Otherwise 19 %. Mietwagen trips are generally subject to 19 % (exception: patient transport on taxi terms). Calculation: 53,50 € × 7 ÷ 107 = 3,50 € VAT; net 50,00 €.</p><p lang=\"de\"><i>Key German terms: ermäßigter Steuersatz, Regelsteuersatz, Gemeinde, Beförderungsstrecke.</i></p>","punkte_liste":[{"t":"7 % within one municipality","p":1},{"t":"7 % for distances up to 50 km, otherwise 19 %","p":1},{"t":"Mietwagen generally 19 %","p":1},{"t":"Calculation correct: 3,50 € VAT / 50,00 € net","p":2}],"quelle":"§ 12 UStG","lek":"steuern","sg":"1.8","de":{"frage":"Erklären Sie, wann eine Taxifahrt dem ermäßigten Umsatzsteuersatz unterliegt, und was für Mietwagenfahrten gilt. Rechnen Sie die Umsatzsteuer aus einem Fahrpreis von 53,50 € (Taxi, innerorts) heraus.","muster":"<p>Taxifahrten unterliegen 7 %, wenn sie innerhalb einer Gemeinde stattfinden oder die Beförderungsstrecke nicht mehr als 50 km beträgt (§ 12 Abs. 2 Nr. 10 UStG). Sonst 19 %. Mietwagenfahrten unterliegen grundsätzlich 19 % (Ausnahme: Krankenfahrten zu Taxi-Bedingungen). Rechnung: 53,50 € × 7 ÷ 107 = 3,50 € USt; netto 50,00 €.</p>","punkte_liste":["7 % innerhalb einer Gemeinde","7 % bei Strecke bis 50 km, sonst 19 %","Mietwagen grundsätzlich 19 %","Rechnung richtig: 3,50 € USt / 50,00 € netto"]}},{"id":"tb-01","typ":"single","frage":"Who is authorised by the PBefG to set taxi fares?","optionen":["The IHK","The state government by regulation; it may delegate this power","Each taxi operator for himself","The local taxi dispatch centre"],"richtig":1,"erklaerung":"§ 51 (1) PBefG authorises the state government. The task is usually delegated to districts and independent cities. The IHK is consulted.","quelle":"§ 51 Abs. 1 und 3 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Wer ist nach dem PBefG ermächtigt, die Beförderungsentgelte für Taxen festzulegen?","erklaerung":"§ 51 Abs. 1 PBefG ermächtigt die Landesregierung. Meist ist die Aufgabe auf Kreise und kreisfreie Städte übertragen. Die IHK wird angehört.","optionen":["Die IHK","Die Landesregierung durch Rechtsverordnung; sie kann die Ermächtigung übertragen","Jeder Taxiunternehmer für sich","Die örtliche Taxizentrale"]}},{"id":"tb-02","typ":"tf","frage":"A taxi driver may give a regular customer 10 % off the taxi tariff if the customer travels often.","richtig":false,"erklaerung":"The tariff may be neither exceeded nor undercut. Discounts that are not available to everyone under the same conditions are forbidden. Only a special agreement under § 51 (2) would be possible.","quelle":"§ 51 Abs. 5, § 39 Abs. 3 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Ein Taxifahrer darf einem Stammkunden 10 % Rabatt auf den Taxitarif geben, wenn der Kunde regelmäßig fährt.","erklaerung":"Der Tarif darf weder über- noch unterschritten werden. Ermäßigungen, die nicht unter gleichen Bedingungen jedem zugutekommen, sind verboten. Möglich wäre nur eine Sondervereinbarung nach § 51 Abs. 2."}},{"id":"tb-03","typ":"multi","frage":"Under which conditions are special agreements for the mandatory service area allowed? Select all correct answers.","optionen":["There is a fixed period, a minimum number of trips or a minimum monthly turnover.","The order of the transport market is not disturbed.","Fares and conditions are agreed in writing.","The regulation provides for approval or notification.","The customer pays in cash.","The trip is longer than 50 km."],"richtig":[0,1,2,3],"erklaerung":"These are the four conditions of § 51 (2) PBefG.","quelle":"§ 51 Abs. 2 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Unter welchen Bedingungen sind Sondervereinbarungen für den Pflichtfahrbereich zulässig? Wähle alle richtigen.","erklaerung":"Das sind die vier Bedingungen aus § 51 Abs. 2 PBefG.","optionen":["Es gibt einen festen Zeitraum, eine Mindestzahl an Fahrten oder einen Mindestumsatz im Monat.","Die Ordnung des Verkehrsmarktes wird nicht gestört.","Entgelte und Bedingungen werden schriftlich vereinbart.","Die Rechtsverordnung sieht eine Genehmigung oder Anzeige vor.","Der Kunde zahlt bar.","Die Fahrt geht über mehr als 50 km."]}},{"id":"tb-04","typ":"multi","frage":"When does an obligation to carry exist under § 22 PBefG? Select all conditions.","optionen":["The conditions of carriage are complied with.","The trip is possible with the vehicles normally used.","The trip is not prevented by circumstances the operator cannot avoid or remedy.","The trip is longer than 5 km.","The passenger pays in advance."],"richtig":[0,1,2],"erklaerung":"§ 22 PBefG names these three conditions. The length of the trip does not matter.","quelle":"§ 22 PBefG","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Wann besteht nach § 22 PBefG eine Beförderungspflicht? Wähle alle Bedingungen.","erklaerung":"Diese drei Bedingungen nennt § 22 PBefG. Die Länge der Fahrt spielt keine Rolle.","optionen":["Die Beförderungsbedingungen werden eingehalten.","Die Beförderung ist mit den regelmäßig eingesetzten Fahrzeugen möglich.","Die Beförderung wird nicht durch Umstände verhindert, die der Unternehmer nicht abwenden und nicht beheben kann.","Die Fahrt ist länger als 5 km.","Der Fahrgast zahlt im Voraus."]}},{"id":"tb-05","typ":"single","frage":"A passenger is very drunk, insults the driver and hits the window. What applies?","optionen":["The driver must still take him because of the obligation to carry.","The driver may refuse because facts suggest the passenger is a danger to safety.","The driver may only refuse with police approval.","The driver may refuse but must still charge the base fare."],"richtig":1,"erklaerung":"Carriage may be refused if facts justify the assumption that the person is a danger to safety and order or to passengers.","quelle":"§ 13 BOKraft","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Ein Fahrgast ist stark betrunken, beleidigt den Fahrer und schlägt gegen die Scheibe. Was gilt?","erklaerung":"Die Beförderung darf abgelehnt werden, wenn Tatsachen die Annahme rechtfertigen, dass die Person eine Gefahr für Sicherheit und Ordnung oder für Fahrgäste ist.","optionen":["Der Fahrer muss ihn wegen der Beförderungspflicht trotzdem fahren.","Der Fahrer darf die Fahrt ablehnen, weil Tatsachen dafür sprechen, dass der Fahrgast eine Gefahr für die Sicherheit ist.","Der Fahrer darf nur ablehnen, wenn die Polizei zustimmt.","Der Fahrer darf ablehnen, muss aber trotzdem den Grundpreis kassieren."]}},{"id":"tb-06","typ":"single","frage":"What applies to prices for Mietwagen?","optionen":["The local taxi tariff applies.","The price is freely agreed; without agreement it is calculated by the odometer. The authority can set minimum fares.","The IHK sets the price.","Mietwagen may only charge fixed prices approved by the authority."],"richtig":1,"erklaerung":"Mietwagen have no tariff obligation. § 40 BOKraft: charging by odometer if nothing else is agreed. § 51a PBefG: the authority can set minimum fares.","quelle":"§ 51a PBefG, § 40 BOKraft","lc":true,"lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Was gilt für die Preise im Mietwagenverkehr?","erklaerung":"Mietwagen haben keine Tarifpflicht. § 40 BOKraft: Abrechnung nach Wegstreckenzähler, wenn nichts anderes vereinbart ist. § 51a PBefG: Die Behörde kann Mindestentgelte festlegen.","optionen":["Es gilt der örtliche Taxitarif.","Der Preis ist frei vereinbar; ohne Vereinbarung wird nach dem Wegstreckenzähler abgerechnet. Die Behörde kann Mindestentgelte festlegen.","Der Preis wird von der IHK festgelegt.","Mietwagen dürfen nur Festpreise nehmen, die die Behörde genehmigt hat."]}},{"id":"tb-07","typ":"single","frage":"When must the taxi roof sign be lit according to the BOKraft?","optionen":["Whenever the engine is running","When the taxi is free and in the tariff area; not needed at the rank; off during a booked trip","Only at night","Only while carrying a passenger"],"richtig":1,"erklaerung":"This way people on the street can see whether a taxi is free.","quelle":"§ 39 BOKraft","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Wann muss das Taxischild nach BOKraft leuchten?","erklaerung":"So erkennt man auf der Straße, ob ein Taxi frei ist.","optionen":["Immer, wenn der Motor läuft","Wenn das Taxi frei ist und im Tarifgebiet unterwegs ist; nicht nötig am Taxistand; aus bei einer Fahrt mit Auftrag","Nur nachts","Nur während der Fahrt mit Fahrgast"]}},{"id":"tb-08","typ":"tf","frage":"For a pre-booked taxi trip, the local tariff may provide a fixed price or a price range. Within the range the price is agreed before the trip starts.","richtig":true,"erklaerung":"§ 51 (1) sentence 4 PBefG allows this since the 2021 reform.","quelle":"§ 51 Abs. 1 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Für eine vorbestellte Taxifahrt kann der örtliche Tarif einen Festpreis oder einen Preisrahmen vorsehen. Innerhalb des Rahmens wird der Preis vor Fahrtantritt vereinbart.","erklaerung":"Das erlaubt § 51 Abs. 1 Satz 4 PBefG seit der Reform 2021."}},{"id":"tb-09","typ":"single","frage":"A passenger says nothing about the route. Which route must the driver take?","optionen":["The fastest route, however long","The shortest route; another only if it is better for traffic or cheaper and agreed with the passenger","Whatever the satnav suggests first","Any route, because the meter is running anyway"],"richtig":1,"erklaerung":"§ 38 BOKraft: the shortest route unless the passenger decides otherwise.","quelle":"§ 38 BOKraft","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Ein Fahrgast sagt nichts zur Strecke. Welchen Weg muss der Fahrer nehmen?","erklaerung":"§ 38 BOKraft: kürzester Weg, sofern der Fahrgast nichts anderes bestimmt.","optionen":["Den schnellsten Weg, egal wie lang","Den kürzesten Weg; einen anderen nur, wenn er verkehrs- oder preisgünstiger ist und mit dem Fahrgast vereinbart wird","Den Weg, den das Navi zuerst vorschlägt","Jeden Weg, weil der Taxameter sowieso läuft"]}},{"id":"tb-10","typ":"tf","frage":"A taxi driver may refuse a 1.5 km trip within the mandatory service area because it is not worth it.","richtig":false,"erklaerung":"The length of the trip is no reason. The obligation to carry applies in the mandatory service area.","quelle":"§§ 22, 47 Abs. 4 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Ein Taxifahrer darf eine Fahrt von 1,5 km im Pflichtfahrbereich ablehnen, weil sie sich nicht lohnt.","erklaerung":"Die Länge der Fahrt ist kein Grund. Im Pflichtfahrbereich gilt die Beförderungspflicht."}},{"id":"tb-11","typ":"single","frage":"A passenger wants to put a can of petrol in the boot. What applies?","optionen":["Allowed if he pays a surcharge","Highly flammable substances are excluded from carriage.","Allowed if the can is closed","Only with permission from the fire brigade"],"richtig":1,"erklaerung":"Explosive, highly flammable, radioactive, foul-smelling or corrosive substances are excluded from carriage.","quelle":"§ 15 BOKraft","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Ein Fahrgast will einen Kanister Benzin im Kofferraum mitnehmen. Was gilt?","erklaerung":"Explosive, leicht entzündliche, radioaktive, übel riechende oder ätzende Stoffe sind von der Beförderung ausgeschlossen.","optionen":["Erlaubt, wenn er dafür einen Zuschlag zahlt","Leicht entzündliche Stoffe sind von der Beförderung ausgeschlossen.","Erlaubt, wenn der Kanister geschlossen ist","Nur mit Genehmigung der Feuerwehr"]}},{"id":"tb-12","typ":"single","frage":"What is the mandatory service area (Pflichtfahrbereich)?","optionen":["The area where the taxi regulations set no-stopping zones","The area where the set taxi tariff applies; only there does the obligation to carry apply","The route from the taxi rank to the office","The area where Mietwagen may wait"],"richtig":1,"erklaerung":"The obligation to carry only exists for trips within the area of the fares set under § 51.","quelle":"§ 47 Abs. 4 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Was ist der Pflichtfahrbereich?","erklaerung":"Die Beförderungspflicht besteht nur für Fahrten innerhalb des Geltungsbereichs der Beförderungsentgelte nach § 51.","optionen":["Das Gebiet, in dem die Taxenordnung Halteverbote regelt","Der Geltungsbereich des festgesetzten Taxitarifs; nur dort gilt die Beförderungspflicht","Die Strecke vom Taxistand zum Betriebssitz","Das Gebiet, in dem Mietwagen warten dürfen"]}},{"id":"tb-13","typ":"zahl","frage":"Sample tariff: base fare 4,00 €, 1st to 5th km 2,40 €/km, from the 6th km 2,10 €/km. A passenger travels 9 km without waiting time. What is the fare?","richtig":24.4,"einheit":"€","loesung":"4,00 € + 5 × 2,40 € + 4 × 2,10 €\n= 4,00 € + 12,00 € + 8,40 € = 24,40 €","erklaerung":"Base fare plus the stepped km prices.","quelle":"Beispieltarif (Beispielwerte)","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Beispieltarif: Grundpreis 4,00 €, 1. bis 5. km 2,40 €/km, ab dem 6. km 2,10 €/km. Ein Fahrgast fährt 9 km ohne Wartezeit. Wie hoch ist der Fahrpreis?","erklaerung":"Grundpreis plus gestaffelte km-Preise.","loesung":"4,00 € + 5 × 2,40 € + 4 × 2,10 €\n= 4,00 € + 12,00 € + 8,40 € = 24,40 €","einheit":"€"}},{"id":"tb-14","typ":"tf","frage":"The obligation to carry also applies to Mietwagen if the booking comes in via the registered office.","richtig":false,"erklaerung":"§§ 21 and 22 PBefG do not apply to Mietwagen.","quelle":"§ 49 Abs. 4 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Die Beförderungspflicht gilt auch für Mietwagen, wenn der Auftrag am Betriebssitz eingeht.","erklaerung":"Für Mietwagen gelten §§ 21 und 22 PBefG nicht."}},{"id":"tb-15","typ":"single","frage":"What does the obligation to operate (Betriebspflicht) mean for a taxi operator?","optionen":["He must drive 24 hours every day.","He must start the licensed business and run it properly during the period of validity. Release only on application.","He must set up a works council.","He must request a tax audit every year."],"richtig":1,"erklaerung":"§ 21 PBefG. The authority can release him on application if operating is impossible or unreasonable.","quelle":"§ 21 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Was bedeutet die Betriebspflicht für einen Taxiunternehmer?","erklaerung":"§ 21 PBefG. Die Behörde kann auf Antrag befreien, wenn der Betrieb unmöglich oder unzumutbar ist.","optionen":["Er muss jeden Tag 24 Stunden fahren.","Er muss den genehmigten Betrieb aufnehmen und während der Geltungsdauer ordnungsgemäß führen. Befreiung nur auf Antrag.","Er muss einen Betriebsrat gründen.","Er muss jedes Jahr eine Betriebsprüfung beim Finanzamt beantragen."]}},{"id":"tb-16","typ":"offen","frage":"Explain the tariff obligation in taxi transport and name two exceptions.","muster":"<p>The fares set under § 51 PBefG are binding. They may be neither exceeded nor undercut; discounts are only allowed if available to everyone on the same terms (§ 51 (5) with § 39 (3)). Exceptions: special agreements under § 51 (2) (period/minimum volume, market not disturbed, in writing, approval/notification); fixed prices or price ranges for pre-booked trips (§ 51 (1) s. 4); trips outside the mandatory service area.</p><p lang=\"de\"><i>Key German terms: Tarifpflicht, Sondervereinbarung, Festpreis, Tarifkorridor, Pflichtfahrbereich.</i></p>","punkte_liste":[{"t":"Tariff is binding: no more and no less","p":1},{"t":"Discounts only for everyone on equal terms","p":1},{"t":"Exception 1 correct (e.g. special agreement)","p":1},{"t":"Exception 2 correct (e.g. fixed price/range for pre-booking or outside the mandatory area)","p":1}],"quelle":"§§ 39, 51 PBefG","lek":"tarife-befoerderungspflicht","sg":"1.1","de":{"frage":"Erläutern Sie die Tarifpflicht im Taxenverkehr und nennen Sie zwei Ausnahmen.","muster":"<p>Die nach § 51 PBefG festgesetzten Beförderungsentgelte sind verbindlich. Sie dürfen weder über- noch unterschritten werden; Ermäßigungen sind nur zulässig, wenn sie unter gleichen Bedingungen jedermann zugutekommen (§ 51 Abs. 5 i. V. m. § 39 Abs. 3). Ausnahmen: Sondervereinbarungen nach § 51 Abs. 2 (Zeitraum/Mindestmenge, Markt nicht gestört, schriftlich, Genehmigung/Anzeige); Festpreise oder Preisrahmen für vorbestellte Fahrten (§ 51 Abs. 1 S. 4); Fahrten außerhalb des Pflichtfahrbereichs.</p>","punkte_liste":["Tarif ist verbindlich: nicht über- und nicht unterschreiten","Ermäßigungen nur für jedermann zu gleichen Bedingungen","Ausnahme 1 richtig (z. B. Sondervereinbarung)","Ausnahme 2 richtig (z. B. Festpreis/Preisrahmen bei Vorbestellung oder außerhalb Pflichtfahrbereich)"]}},{"id":"tm-01","typ":"single","frage":"Which trip does <b>not</b> fall under the Passenger Transport Act (PBefG)?","optionen":["A Mietwagen takes a passenger to the airport for 40 €.","Four colleagues drive to work together and only share the fuel costs, less than 30 cents per km.","A taxi carries a passenger at the taxi tariff.","A driver offers paid rides via an app."],"richtig":1,"erklaerung":"Car trips are exempt if they are free of charge or the total payment does not exceed the amount under § 5 (2) BRKG (currently 30 cents per km).","quelle":"§ 1 Abs. 2 Nr. 1 PBefG, § 5 Abs. 2 BRKG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Welche Fahrt fällt <b>nicht</b> unter das Personenbeförderungsgesetz?","erklaerung":"Fahrten mit dem Pkw sind ausgenommen, wenn sie kostenlos sind oder das Gesamtentgelt nicht über dem Betrag nach § 5 Abs. 2 BRKG liegt (zurzeit 30 Cent pro km).","optionen":["Ein Mietwagen bringt einen Fahrgast gegen 40 € zum Flughafen.","Vier Kollegen fahren zusammen zur Arbeit und teilen nur die Spritkosten, weniger als 30 Cent pro km.","Ein Taxi fährt einen Fahrgast nach Taxitarif.","Ein Fahrer bietet über eine App Fahrten gegen Bezahlung an."]}},{"id":"tm-02","typ":"multi","frage":"Which forms of occasional transport (Gelegenheitsverkehr) does the PBefG allow? Select all correct answers.","optionen":["Taxis (Verkehr mit Taxen)","Private hire cars (Verkehr mit Mietwagen)","Pooled on-demand transport (gebündelter Bedarfsverkehr)","Scheduled city buses","Picking up hitchhikers privately for money"],"richtig":[0,1,2],"erklaerung":"§ 46 (2) PBefG only allows four forms: taxis, excursions and holiday trips, hired coaches and Mietwagen, and pooled on-demand transport. Scheduled transport is not occasional transport.","quelle":"§ 46 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Welche Formen des Gelegenheitsverkehrs erlaubt das PBefG? Wähle alle richtigen.","erklaerung":"§ 46 Abs. 2 PBefG erlaubt nur vier Formen: Taxen, Ausflugsfahrten und Ferienziel-Reisen, Mietomnibusse und Mietwagen sowie den gebündelten Bedarfsverkehr. Linienverkehr ist kein Gelegenheitsverkehr.","optionen":["Verkehr mit Taxen","Verkehr mit Mietwagen","Gebündelter Bedarfsverkehr","Linienverkehr mit Stadtbussen","Privates Mitnehmen von Anhaltern gegen Bezahlung"]}},{"id":"tm-03","typ":"zuordnung","frage":"Who does the rule apply to?","kategorien":["Taxi","Mietwagen","both"],"paare":[{"t":"Must return to the registered office after every trip without a new booking.","k":1,"w":"This is the duty to return under § 49 (4) PBefG."},{"t":"Must take every passenger within the mandatory service area.","k":0,"w":"Only taxis have an obligation to carry (§§ 22, 47 (4) PBefG)."},{"t":"Needs a licence under the PBefG.","k":2,"w":"§ 2 PBefG applies to both."},{"t":"Must record incoming bookings and keep them for 1 year.","k":1,"w":"§ 49 (4) PBefG."},{"t":"Has a taximeter (Fahrpreisanzeiger).","k":0,"w":"The Mietwagen has an odometer (§§ 28, 30 BOKraft)."},{"t":"May not be rented out to self-drivers.","k":0,"w":"§ 47 (5) PBefG expressly forbids this for taxis."},{"t":"Outside advertising only on the side doors.","k":2,"w":"§ 26 (2) BOKraft applies to taxis and Mietwagen."},{"t":"The price is in principle freely agreed.","k":1,"w":"But the authority can set minimum fares (§ 51a PBefG)."}],"erklaerung":"The table in this lesson sums up all the differences.","quelle":"PBefG, BOKraft","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Für wen gilt die Regel?","erklaerung":"Die Tabelle in dieser Lektion fasst alle Unterschiede zusammen.","kategorien":["Taxi","Mietwagen","beide"],"paare":["Muss nach jeder Fahrt ohne neuen Auftrag zum Betriebssitz zurück.","Muss jeden Fahrgast im Pflichtfahrbereich mitnehmen.","Braucht eine Genehmigung nach dem PBefG.","Muss eingehende Aufträge aufzeichnen und 1 Jahr aufbewahren.","Hat einen Fahrpreisanzeiger (Taxameter).","Darf nicht an Selbstfahrer vermietet werden.","Außenwerbung nur an den seitlichen Türen.","Der Preis ist grundsätzlich frei vereinbar."]}},{"id":"tm-04","typ":"single","frage":"A Mietwagen from Aachen takes a passenger to Düsseldorf airport. The driver has no new booking. What must he do?","optionen":["He may wait at the terminal for new passengers.","He must return to the registered office in Aachen without delay.","He may join the taxi rank if there is space.","He may wait for one hour and then drive back."],"richtig":1,"erklaerung":"Without a new booking the duty to return applies. Mietwagen may not wait for customers.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Ein Mietwagen aus Aachen bringt einen Fahrgast zum Flughafen Düsseldorf. Einen neuen Auftrag hat der Fahrer nicht. Was muss er tun?","erklaerung":"Ohne neuen Auftrag gilt die Rückkehrpflicht. Warten auf Kunden ist für Mietwagen nicht erlaubt.","optionen":["Er darf am Terminal auf neue Fahrgäste warten.","Er muss unverzüglich zum Betriebssitz in Aachen zurückfahren.","Er darf sich an den Taxistand stellen, wenn dort Platz ist.","Er darf eine Stunde warten und dann zurückfahren."]}},{"id":"tm-05","typ":"tf","frage":"During the trip a new app booking arrives at the registered office. After dropping off, the Mietwagen may drive straight to the new passenger.","richtig":true,"erklaerung":"The duty to return does not apply if a new booking came in via the registered office before or during the trip.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Während der Fahrt geht über die App ein neuer Auftrag am Betriebssitz ein. Der Mietwagen darf nach dem Absetzen direkt zum neuen Fahrgast fahren.","erklaerung":"Die Rückkehrpflicht entfällt, wenn vor oder während der Fahrt ein neuer Auftrag über den Betriebssitz eingegangen ist."}},{"id":"tm-06","typ":"tf","frage":"A pedestrian waves at a Mietwagen at a traffic light. The driver may pick him up if he is free.","richtig":false,"erklaerung":"The booking did not come in via the registered office. Only a taxi may pick up passengers on the street.","quelle":"§ 49 Abs. 4 PBefG","lc":true,"lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Ein Passant winkt einem Mietwagen an der Ampel zu. Der Fahrer darf ihn mitnehmen, wenn er gerade frei ist.","erklaerung":"Der Auftrag ist nicht über den Betriebssitz eingegangen. Fahrgäste auf der Straße aufnehmen darf nur ein Taxi."}},{"id":"tm-07","typ":"tf","frage":"A taxi from Aachen may join a taxi rank in Cologne and wait for passengers there.","richtig":false,"erklaerung":"Taxis may in principle only wait for customers in the municipality of the operator's registered office. The authority can allow exceptions.","quelle":"§ 47 Abs. 2 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Ein Aachener Taxi darf sich in Köln an einen Taxistand stellen und dort auf Fahrgäste warten.","erklaerung":"Taxen dürfen grundsätzlich nur in der Gemeinde bereitgehalten werden, in der der Unternehmer seinen Betriebssitz hat. Die Behörde kann Ausnahmen erlauben."}},{"id":"tm-08","typ":"tf","frage":"A taxi from Aachen may pick up a pre-booked passenger in Cologne and take him to Aachen.","richtig":true,"erklaerung":"Pre-booked trips may start in other municipalities.","quelle":"§ 47 Abs. 2 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Ein Aachener Taxi darf einen vorbestellten Fahrgast in Köln abholen und nach Aachen fahren.","erklaerung":"Vorbestellte Fahrten dürfen auch in anderen Gemeinden beginnen."}},{"id":"tm-09","typ":"single","frage":"A Mietwagen has a yellow roof sign saying “CAB”. Is this allowed?","optionen":["Yes, as long as it does not say “Taxi”.","No, because the Mietwagen could be confused with a taxi.","Yes, if the sign is not lit at night.","Only with permission from the IHK."],"richtig":1,"erklaerung":"Mietwagen must not appear in a way that can be confused with taxis. Signs reserved for taxis are forbidden.","quelle":"§ 49 Abs. 4 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Ein Mietwagen hat ein gelbes Dachschild mit der Aufschrift „CAB“. Ist das erlaubt?","erklaerung":"Mietwagen dürfen nicht so auftreten, dass man sie mit Taxis verwechseln kann. Zeichen, die Taxen vorbehalten sind, sind verboten.","optionen":["Ja, solange nicht „Taxi“ draufsteht.","Nein, weil man den Mietwagen damit mit einem Taxi verwechseln kann.","Ja, wenn das Schild nachts nicht leuchtet.","Nur mit Genehmigung der IHK."]}},{"id":"tm-10","typ":"single","frage":"How long must a Mietwagen operator keep the records of incoming bookings?","optionen":["3 months","6 months","1 year","10 years"],"fest":true,"richtig":2,"erklaerung":"Bookings are recorded on paper or electronically and kept for one year.","quelle":"§ 49 Abs. 4 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Wie lange muss ein Mietwagenunternehmer die Aufzeichnungen über eingegangene Aufträge aufbewahren?","erklaerung":"Die Aufträge werden buchmäßig oder elektronisch erfasst und ein Jahr aufbewahrt.","optionen":["3 Monate","6 Monate","1 Jahr","10 Jahre"]}},{"id":"tm-11","typ":"single","frage":"Which measuring device does a Mietwagen need?","optionen":["A taximeter (Fahrpreisanzeiger)","An odometer (Wegstreckenzähler) or an approved software system","A tachograph","No device"],"richtig":1,"erklaerung":"A Mietwagen must have an easy-to-read odometer, or alternatively a conformity-assessed software system. Calibration law applies.","quelle":"§ 30 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Welches Messgerät braucht ein Mietwagen?","erklaerung":"In Mietwagen ist ein leicht ablesbarer Wegstreckenzähler einzubauen, alternativ ein konformitätsbewertetes Software-System. Das Eichrecht gilt.","optionen":["Einen Fahrpreisanzeiger (Taxameter)","Einen Wegstreckenzähler oder ein zugelassenes Software-System","Einen Fahrtenschreiber","Kein Messgerät"]}},{"id":"tm-12","typ":"single","frage":"Which colour does the BOKraft require for taxis?","optionen":["Black","Light ivory RAL 1015","Traffic yellow RAL 1023","No specific colour"],"richtig":1,"erklaerung":"Taxis are light ivory RAL 1015. Exceptions are possible under state law.","quelle":"§ 26 Abs. 1 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Welche Farbe schreibt die BOKraft für Taxen vor?","erklaerung":"Taxen sind hell-elfenbein nach RAL 1015. Ausnahmen sind über Landesrecht möglich.","optionen":["Schwarz","Hell-elfenbein RAL 1015","Verkehrsgelb RAL 1023","Keine bestimmte Farbe"]}},{"id":"tm-13","typ":"single","frage":"A Mietwagen driver refuses a trip from Aachen to Maastricht. Is he allowed to?","optionen":["No, he has an obligation to carry.","Yes, Mietwagen have no obligation to carry.","Only if the trip is longer than 50 km.","Only after 10 pm."],"richtig":1,"erklaerung":"§§ 21 and 22 PBefG (obligations to operate and to carry) do not apply to Mietwagen.","quelle":"§ 49 Abs. 4 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Ein Mietwagenfahrer lehnt eine Fahrt von Aachen nach Maastricht ab. Darf er das?","erklaerung":"§§ 21 und 22 PBefG (Betriebs- und Beförderungspflicht) gelten für Mietwagen nicht.","optionen":["Nein, er hat Beförderungspflicht.","Ja, für Mietwagen gibt es keine Beförderungspflicht.","Nur wenn die Fahrt länger als 50 km ist.","Nur nach 22 Uhr."]}},{"id":"tm-14","typ":"single","frage":"In a large rural municipality the authority may allow parking locations for Mietwagen. Which minimum distance from the registered office is the basis?","optionen":["5 km","10 km","15 km","50 km"],"fest":true,"richtig":2,"erklaerung":"The basis is a minimum distance of 15 km between the main office and the parking location, or between several locations.","quelle":"§ 49 Abs. 5 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"In einer großen Flächengemeinde darf die Behörde Abstellorte für Mietwagen erlauben. Welcher Mindestabstand zum Betriebssitz ist dafür die Grundlage?","erklaerung":"Grundlage ist ein Mindestabstand von 15 km zwischen dem Hauptbetriebssitz und dem Abstellort oder zwischen mehreren Abstellorten.","optionen":["5 km","10 km","15 km","50 km"]}},{"id":"tm-15","typ":"tf","frage":"Uber and Bolt do not need a licence in Germany, so the Mietwagen operator who drives via these apps does not need one either.","richtig":false,"erklaerung":"The platform only arranges the trip. Whoever carries out the trips for payment is the operator and needs a licence under § 2 PBefG.","quelle":"§§ 2, 49 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Uber und Bolt brauchen in Deutschland selbst keine Genehmigung, deshalb braucht auch der Mietwagenunternehmer, der über diese Apps fährt, keine Genehmigung.","erklaerung":"Die Plattform vermittelt nur. Wer die Fahrten gegen Entgelt ausführt, ist Unternehmer und braucht eine Genehmigung nach § 2 PBefG."}},{"id":"tm-16","typ":"offen","frage":"Explain the duty to return (Rückkehrpflicht) for Mietwagen. Also say when it does not apply.","muster":"<p>Mietwagen may only carry out bookings received at the registered office or the operator's home. After the trip the Mietwagen must return to the registered office without delay. This does not apply if the driver received a new booking via the office before the trip or during the trip. In large rural municipalities the authority can also allow parking locations (basis: at least 15 km distance).</p><p lang=\"de\"><i>Key German terms: Rückkehrpflicht, Betriebssitz, unverzüglich, Beförderungsauftrag, Abstellort.</i></p>","punkte_liste":[{"t":"Bookings only via the registered office or the operator's home","p":1},{"t":"After the trip return to the registered office without delay","p":1},{"t":"Exception: new booking before or during the trip","p":1},{"t":"Special rule: parking locations in large municipalities (§ 49 (5))","p":1}],"quelle":"§ 49 Abs. 4 und 5 PBefG","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Erklären Sie die Rückkehrpflicht für Mietwagen. Nennen Sie auch, wann sie nicht gilt.","muster":"<p>Mietwagen dürfen nur Aufträge ausführen, die am Betriebssitz oder in der Wohnung des Unternehmers eingegangen sind. Nach Ende der Fahrt muss der Mietwagen unverzüglich zum Betriebssitz zurückkehren. Das gilt nicht, wenn der Fahrer vor der Fahrt über den Betriebssitz oder während der Fahrt einen neuen Auftrag bekommen hat. In großen Flächengemeinden kann die Behörde außerdem Abstellorte erlauben (Grundlage: mindestens 15 km Abstand).</p>","punkte_liste":["Aufträge nur über Betriebssitz oder Wohnung des Unternehmers","Nach der Fahrt unverzüglich zurück zum Betriebssitz","Ausnahme: neuer Auftrag vor oder während der Fahrt","Sonderregel: Abstellorte in Flächengemeinden (§ 49 Abs. 5)"]}},{"id":"tm-17","typ":"offen","frage":"Name four differences between taxi transport and Mietwagen transport.","muster":"<ul><li>Taxis may wait at ranks and take bookings on the street; Mietwagen only via the registered office.</li><li>Mietwagen have a duty to return.</li><li>Taxis have obligations to carry and to operate; Mietwagen do not.</li><li>Taxis have a fixed tariff; Mietwagen a free price (possibly a minimum fare).</li><li>Taxi: RAL 1015 and roof sign; Mietwagen must not look like a taxi.</li><li>Taxi: taximeter; Mietwagen: odometer.</li></ul>","punkte_liste":[{"t":"Bookings / waiting (taxi rank vs. registered office)","p":1},{"t":"Duty to return for Mietwagen","p":1},{"t":"Obligation to carry only for taxis","p":1},{"t":"Tariff obligation for taxis, free prices for Mietwagen","p":1},{"t":"Another correct difference (appearance, meter, licence check …)","p":1}],"quelle":"§§ 47, 49, 51, 51a PBefG; §§ 26, 28, 30 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Nennen Sie vier Unterschiede zwischen dem Verkehr mit Taxen und dem Verkehr mit Mietwagen.","muster":"<ul><li>Taxi darf an Taxiständen bereitstehen und auf der Straße Aufträge annehmen, Mietwagen nur über den Betriebssitz.</li><li>Mietwagen hat Rückkehrpflicht.</li><li>Taxi hat Beförderungs- und Betriebspflicht, Mietwagen nicht.</li><li>Taxi hat festen Tarif, Mietwagen freien Preis (evtl. Mindestentgelt).</li><li>Taxi: RAL 1015 und Taxischild; Mietwagen darf nicht wie ein Taxi aussehen.</li><li>Taxi: Fahrpreisanzeiger; Mietwagen: Wegstreckenzähler.</li></ul>","punkte_liste":["Auftragsannahme / Bereithalten (Taxistand vs. Betriebssitz)","Rückkehrpflicht beim Mietwagen","Beförderungspflicht nur beim Taxi","Tarifpflicht beim Taxi, freie Preise beim Mietwagen","Weiterer richtiger Unterschied (Aussehen, Messgerät, Genehmigungsprüfung …)"]}},{"id":"tm-18","typ":"single","frage":"What applies to outside advertising on taxis?","optionen":["Advertising is allowed anywhere on the vehicle.","Advertising only on the side doors, no political or religious advertising.","Advertising is completely forbidden on taxis.","Advertising only on the roof next to the taxi sign."],"richtig":1,"erklaerung":"Outside advertising is only allowed on the side doors. Political and religious advertising is forbidden on taxis.","quelle":"§ 26 Abs. 2 BOKraft","lek":"taxi-oder-mietwagen","sg":"1.1","de":{"frage":"Was gilt für Außenwerbung an Taxen?","erklaerung":"Werbung nach außen ist nur an den seitlichen Fahrzeugtüren erlaubt. Politische und religiöse Werbung ist an Taxen verboten.","optionen":["Werbung ist überall am Fahrzeug erlaubt.","Werbung nur an den seitlichen Türen, keine politische oder religiöse Werbung.","Werbung ist bei Taxen ganz verboten.","Werbung nur auf dem Dach neben dem Taxischild."]}},{"id":"um-01","typ":"tf","frage":"A taxi driver may leave the engine running at the taxi rank so that the car stays warm.","richtig":false,"erklaerung":"Letting engines run unnecessarily is forbidden.","quelle":"§ 30 Abs. 1 StVO","lc":true,"lek":"umweltschutz","sg":"4.3","de":{"frage":"Ein Taxifahrer darf am Taxenstand den Motor laufen lassen, damit das Auto warm bleibt.","erklaerung":"Unnötiges Laufenlassen von Motoren ist verboten."}},{"id":"um-02","typ":"single","frage":"Where should taxis be washed?","optionen":["On the street in front of the business","On a meadow","In a car wash or at a washing bay with an oil separator","At the taxi rank"],"richtig":2,"erklaerung":"Otherwise oil, fuel and cleaning agents get into the water. The basis is water protection law (WHG) and the local wastewater rules.","quelle":"WHG","lc":true,"lek":"umweltschutz","sg":"4.3","de":{"frage":"Wo sollen Taxis gewaschen werden?","erklaerung":"Sonst gelangen Öl, Kraftstoff und Reiniger ins Wasser. Grundlage ist der Gewässerschutz (WHG) und die örtliche Abwassersatzung.","optionen":["Auf der Straße vor dem Betrieb","Auf einer Wiese","In einer Waschanlage oder auf einem Waschplatz mit Ölabscheider","Am Taxenstand"]}},{"id":"um-03","typ":"zahl","frage":"A taxi drives 60.000 km a year. Thanks to economical driving, consumption falls from 7,5 to 6,5 l/100 km. A litre costs 1,50 € net. How much does the operator save per year?","richtig":900,"einheit":"€","tol":0.5,"loesung":"60.000 ÷ 100 × 1,0 l = 600 l\n600 l × 1,50 € = 900,00 €","erklaerung":"Saving = km ÷ 100 × difference in consumption × price.","quelle":"Kostenrechnung","lc":true,"lek":"umweltschutz","sg":"4.3","de":{"frage":"Ein Taxi fährt 60.000 km im Jahr. Durch sparsame Fahrweise sinkt der Verbrauch von 7,5 auf 6,5 l/100 km. Der Liter kostet 1,50 € netto. Wie viel spart der Unternehmer im Jahr?","erklaerung":"Ersparnis = km ÷ 100 × Verbrauchsdifferenz × Preis.","loesung":"60.000 ÷ 100 × 1,0 l = 600 l\n600 l × 1,50 € = 900,00 €","einheit":"€"}},{"id":"um-04","typ":"single","frage":"Which regulation governs the stickers for low-emission zones?","optionen":["35. BImSchV","BOKraft","FeV","39. BImSchV"],"richtig":0,"erklaerung":"35. BImSchV: marking of vehicles with a low contribution to pollution. The 39. BImSchV sets the air quality limits.","quelle":"35. BImSchV","lek":"umweltschutz","sg":"4.3","de":{"frage":"Welche Verordnung regelt die Plaketten für Umweltzonen?","erklaerung":"35. BImSchV: Kennzeichnung der Kraftfahrzeuge mit geringem Beitrag zur Schadstoffbelastung. Die 39. BImSchV regelt die Luftqualitätsgrenzwerte.","optionen":["35. BImSchV","BOKraft","FeV","39. BImSchV"]}},{"id":"um-05","typ":"single","frage":"What must a dealer who sells engine oil do?","optionen":["Nothing","Take back used oil in the amount of oil sold","Only sell oil to workshops","Put used oil in household waste"],"richtig":1,"erklaerung":"Take-back duty under the Used Oil Ordinance (Altölverordnung).","quelle":"Altölverordnung","lek":"umweltschutz","sg":"4.3","de":{"frage":"Was muss ein Händler tun, der Motoröl verkauft?","erklaerung":"Rücknahmepflicht nach der Altölverordnung.","optionen":["Nichts","Altöl in der Menge des verkauften Öls zurücknehmen","Nur Öl an Werkstätten verkaufen","Altöl in den Hausmüll geben"]}},{"id":"um-06","typ":"multi","frage":"Which way of driving saves fuel? Select all correct answers.","optionen":["Drive with foresight and let the car roll","Shift up early","Check tyre pressure regularly","Leave the engine running while waiting","Accelerate hard to reach top gear faster"],"richtig":[0,1,2],"erklaerung":"Idling is forbidden and costs fuel; hard acceleration increases consumption.","quelle":"Umweltschutz","lek":"umweltschutz","sg":"4.3","de":{"frage":"Welche Fahrweise spart Kraftstoff? Wähle alle richtigen.","erklaerung":"Laufenlassen ist verboten und kostet Kraftstoff; starkes Beschleunigen erhöht den Verbrauch.","optionen":["Vorausschauend fahren und rollen lassen","Früh hochschalten","Reifendruck regelmäßig prüfen","Motor beim Warten laufen lassen","Stark beschleunigen, um schneller im höchsten Gang zu sein"]}},{"id":"um-07","typ":"offen","frage":"Name four measures a taxi business can take to protect the environment when operating and maintaining its vehicles.","muster":"<ul><li>Train economical driving, engine off when waiting (§ 30 StVO)</li><li>Buy low-emission vehicles (hybrid, electric), observe low-emission zones</li><li>Regular maintenance, tyre pressure, emissions test at the HU</li><li>Wash only with an oil separator</li><li>Dispose of used oil, tyres and batteries properly</li><li>Avoid noise at the taxi rank</li></ul><p lang=\"de\"><i>Key German terms: Umweltzone, Plakette, Ölabscheider, Altöl, unnötiges Laufenlassen.</i></p>","punkte_liste":[{"t":"Measure 1","p":1},{"t":"Measure 2","p":1},{"t":"Measure 3","p":1},{"t":"Measure 4","p":1}],"quelle":"StVO, KrWG, WHG, BImSchG","lek":"umweltschutz","sg":"4.3","de":{"frage":"Nennen Sie vier Maßnahmen, mit denen ein Taxiunternehmen die Umwelt beim Betrieb und bei der Wartung seiner Fahrzeuge schützen kann.","muster":"<ul><li>Sparsame Fahrweise schulen, Motor beim Warten aus (§ 30 StVO)</li><li>Emissionsarme Fahrzeuge (Hybrid, E) anschaffen, Umweltzonen beachten</li><li>Regelmäßige Wartung, Reifendruck, AU bei der HU</li><li>Waschen nur mit Ölabscheider</li><li>Altöl, Reifen, Batterien fachgerecht entsorgen</li><li>Lärm vermeiden am Taxenstand</li></ul>","punkte_liste":["Maßnahme 1","Maßnahme 2","Maßnahme 3","Maßnahme 4"]}},{"id":"uf-01","typ":"single","frage":"What is the correct order after an accident with injured people?","optionen":["Take photos, call the insurer, then help","Stop and hazard lights, own safety and securing the scene, emergency call, first aid","Drive on and call the police later","First collect the fare from the passengers, then help"],"richtig":1,"erklaerung":"First secure and call for help, then first aid. Photos and reports come later.","quelle":"§ 34 StVO","lc":true,"lek":"unfaelle","sg":"4.2","de":{"frage":"Was ist nach einem Unfall mit Verletzten die richtige Reihenfolge?","erklaerung":"Erst sichern und Notruf, dann Erste Hilfe. Fotos und Meldung kommen später.","optionen":["Fotos machen, Versicherung anrufen, dann helfen","Anhalten und Warnblinker, eigene Sicherheit und Absichern, Notruf, Erste Hilfe","Weiterfahren und später die Polizei anrufen","Erst die Fahrgäste abrechnen, dann helfen"]}},{"id":"uf-02","typ":"tf","frage":"Anyone who only leaves a note with his phone number after a small parking bump and drives on immediately can be guilty of leaving the scene of an accident.","richtig":true,"erklaerung":"A note does not replace waiting a reasonable time or informing the police.","quelle":"§ 142 StGB","lc":true,"lek":"unfaelle","sg":"4.2","de":{"frage":"Wer nach einem kleinen Parkrempler nur einen Zettel mit seiner Telefonnummer hinterlässt und sofort weiterfährt, kann sich wegen Unfallflucht strafbar machen.","erklaerung":"Ein Zettel ersetzt nicht das Warten einer angemessenen Zeit bzw. die Benachrichtigung der Polizei."}},{"id":"uf-03","typ":"single","frage":"An employed driver is injured in an accident and is on sick leave for 2 weeks. What must the operator do?","optionen":["Nothing, the health insurer handles everything.","Report the work accident to the Berufsgenossenschaft within 3 days.","Report the accident to the IHK within a month.","Only inform the motor insurer."],"richtig":1,"erklaerung":"Duty to report in case of death or more than 3 days unable to work, deadline 3 days after learning of it.","quelle":"§ 193 SGB VII","lc":true,"lek":"unfaelle","sg":"4.2","de":{"frage":"Ein angestellter Fahrer verletzt sich bei einem Unfall und ist 2 Wochen krankgeschrieben. Was muss der Unternehmer tun?","erklaerung":"Anzeigepflicht bei Tod oder mehr als 3 Tagen Arbeitsunfähigkeit, Frist 3 Tage ab Kenntnis.","optionen":["Nichts, die Krankenkasse regelt alles.","Den Arbeitsunfall innerhalb von 3 Tagen der Berufsgenossenschaft anzeigen.","Den Unfall innerhalb eines Monats der IHK melden.","Nur die Kfz-Versicherung informieren."]}},{"id":"uf-04","typ":"multi","frage":"Which measures protect taxi drivers against robberies? Select all correct answers.","optionen":["Alarm system, triggered from the driver's seat","Little cash in the vehicle, encourage card payment","Emergency function with location via the dispatch centre","Drivers should fight back against offenders","Carry as much change as possible"],"richtig":[0,1,2],"erklaerung":"In a robbery: your own safety comes first, don't resist.","quelle":"§ 25 BOKraft, Unfallverhütung","lc":true,"lek":"unfaelle","sg":"4.2","de":{"frage":"Welche Maßnahmen schützen Taxifahrer vor Überfällen? Wähle alle richtigen.","erklaerung":"Bei einem Überfall gilt: Eigene Sicherheit geht vor, nicht wehren.","optionen":["Alarmanlage, vom Fahrersitz auslösbar","Wenig Bargeld im Fahrzeug, Kartenzahlung fördern","Notruf-Funktion mit Ortung über die Zentrale","Fahrer sollen sich gegen Täter wehren","Möglichst viel Wechselgeld mitnehmen"]}},{"id":"uf-05","typ":"single","frage":"Which regulation of the Berufsgenossenschaft contains the “principles of prevention”, e.g. risk assessment and instruction?","optionen":["DGUV Vorschrift 1","DGUV Vorschrift 70","BOKraft","StVZO"],"richtig":0,"erklaerung":"DGUV Vorschrift 1 = principles of prevention. DGUV Vorschrift 70 = vehicles.","quelle":"DGUV Vorschrift 1","lek":"unfaelle","sg":"4.2","de":{"frage":"Welche Vorschrift der Berufsgenossenschaft enthält die „Grundsätze der Prävention“, z. B. Gefährdungsbeurteilung und Unterweisung?","erklaerung":"DGUV Vorschrift 1 = Grundsätze der Prävention. DGUV Vorschrift 70 = Fahrzeuge.","optionen":["DGUV Vorschrift 1","DGUV Vorschrift 70","BOKraft","StVZO"]}},{"id":"uf-06","typ":"tf","frage":"Anyone who does not give first aid at an accident although it would be reasonable commits a criminal offence.","richtig":true,"erklaerung":"Failure to render assistance under § 323c StGB.","quelle":"§ 323c StGB","lek":"unfaelle","sg":"4.2","de":{"frage":"Wer bei einem Unfall keine Erste Hilfe leistet, obwohl es ihm zumutbar wäre, macht sich strafbar.","erklaerung":"Unterlassene Hilfeleistung nach § 323c StGB."}},{"id":"uf-07","typ":"offen","frage":"In your business there were two rear-end collisions on the night shift within three months. What measures do you take so that it doesn't happen again?","muster":"<p>Analysis: time, shift length, breaks, driver, weather, vehicle condition. Measures: technical (emergency brake assist, check tyres and brakes), organisational (limit shift lengths, ensure breaks under the ArbZG, keep rest periods, plan routes), personal (instruction on distance, tiredness, distraction; driver safety training). Document the instruction, check the effect, keep accident statistics. Report to the insurer and, if necessary, the BG.</p><p lang=\"de\"><i>Key German terms: Ursachenanalyse, Schichtplan, Ruhezeit, Unterweisung, Fahrsicherheitstraining.</i></p>","punkte_liste":[{"t":"Cause analysis","p":1},{"t":"Organisational measure (shift, breaks, rest period)","p":1},{"t":"Personal measure (instruction, training)","p":1},{"t":"Technical measure or checking effectiveness","p":1}],"quelle":"DGUV Vorschrift 1, ArbSchG","lek":"unfaelle","sg":"4.2","de":{"frage":"In Ihrem Betrieb gab es innerhalb von drei Monaten zwei Auffahrunfälle in der Nachtschicht. Welche Maßnahmen ergreifen Sie, damit sich das nicht wiederholt?","muster":"<p>Analyse: Uhrzeit, Schichtlänge, Pausen, Fahrer, Wetter, Fahrzeugzustand. Maßnahmen: technisch (Notbremsassistent, Reifen, Bremsen prüfen), organisatorisch (Schichtlängen begrenzen, Pausen nach ArbZG sicherstellen, Ruhezeiten einhalten, Touren planen), persönlich (Unterweisung zu Abstand, Müdigkeit, Ablenkung; Fahrsicherheitstraining). Unterweisung dokumentieren, Wirkung kontrollieren, Unfallstatistik führen. Meldungen an Versicherung und ggf. BG.</p>","punkte_liste":["Ursachenanalyse","Organisatorische Maßnahme (Schicht, Pausen, Ruhezeit)","Persönliche Maßnahme (Unterweisung, Training)","Technische Maßnahme oder Kontrolle der Wirksamkeit"]}},{"id":"ug-01","typ":"zuordnung","frage":"How are the people involved liable? Match them.","kategorien":["unlimited","limited"],"paare":[{"t":"Sole proprietor","k":0,"w":"He is liable with all his assets, including private ones."},{"t":"Partner in a GbR","k":0,"w":"Each is liable personally and without limit."},{"t":"Partner in an OHG","k":0,"w":"All are liable without limit."},{"t":"General partner (Komplementär) of a KG","k":0,"w":"The general partner is liable without limit."},{"t":"Limited partner (Kommanditist) of a KG","k":1,"w":"He is only liable up to his contribution."},{"t":"Shareholder of a GmbH","k":1,"w":"Only the company's assets are liable."}],"erklaerung":"Unlimited liability means: including private assets.","quelle":"§ 705 BGB, §§ 105, 161 HGB, GmbHG","lc":true,"lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Wie haften die Beteiligten? Ordne zu.","erklaerung":"Unbeschränkte Haftung bedeutet: auch mit dem Privatvermögen.","kategorien":["unbeschränkt","beschränkt"],"paare":["Einzelunternehmer","Gesellschafter einer GbR","Gesellschafter einer OHG","Komplementär einer KG","Kommanditist einer KG","Gesellschafter einer GmbH"]}},{"id":"ug-02","typ":"single","frage":"How much of a GmbH's share capital must at least be paid in before it is registered in the commercial register?","optionen":["1 €","6.250 €","12.500 €","25.000 €"],"fest":true,"richtig":2,"erklaerung":"At least a quarter on each share, in total at least half of the minimum capital of 25.000 €.","quelle":"§§ 5, 7 Abs. 2 GmbHG","lc":true,"lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Wie viel des Stammkapitals einer GmbH muss mindestens eingezahlt sein, bevor sie zum Handelsregister angemeldet wird?","erklaerung":"Auf jeden Anteil mindestens ein Viertel, insgesamt mindestens die Hälfte des Mindeststammkapitals von 25.000 €.","optionen":["1 €","6.250 €","12.500 €","25.000 €"]}},{"id":"ug-03","typ":"multi","frage":"What applies to the UG (haftungsbeschränkt)? Select all correct answers.","optionen":["The share capital may be below 25.000 €.","The capital must be paid in full before registration.","Contributions in kind are forbidden.","A quarter of the annual surplus must go into a reserve.","The shareholders are liable without limit."],"richtig":[0,1,2,3],"erklaerung":"The UG is a GmbH with less capital. The shareholders are not personally liable.","quelle":"§ 5a GmbHG","lc":true,"lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Was gilt für die UG (haftungsbeschränkt)? Wähle alle richtigen.","erklaerung":"Die UG ist eine GmbH mit weniger Kapital. Die Gesellschafter haften nicht persönlich.","optionen":["Das Stammkapital kann unter 25.000 € liegen.","Das Kapital muss vor der Anmeldung voll eingezahlt sein.","Sacheinlagen sind verboten.","Ein Viertel des Jahresüberschusses muss in eine Rücklage.","Die Gesellschafter haften unbeschränkt."]}},{"id":"ug-04","typ":"single","frage":"Where does a taxi operator register his trade?","optionen":["At the IHK","At the municipal trade office (Gewerbeamt)","At the local court","At the PBefG licensing authority, that's enough"],"richtig":1,"erklaerung":"The trade registration goes to the responsible municipal authority (trade office). It is needed in addition to the PBefG licence.","quelle":"§ 14 GewO","lc":true,"lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Wo meldet ein Taxiunternehmer sein Gewerbe an?","erklaerung":"Die Gewerbeanzeige geht an die zuständige Behörde der Gemeinde (Gewerbeamt). Sie ist zusätzlich zur PBefG-Genehmigung nötig.","optionen":["Bei der IHK","Beim Gewerbeamt der Gemeinde","Beim Amtsgericht","Bei der Genehmigungsbehörde nach PBefG, das reicht"]}},{"id":"ug-05","typ":"single","frage":"Within which period must a new business be reported to the Berufsgenossenschaft?","optionen":["1 week after starting","1 month after starting","3 months after starting","Only when the first accident happens"],"richtig":0,"erklaerung":"Within one week of the start of the business.","quelle":"§ 192 Abs. 1 SGB VII","lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Innerhalb welcher Frist muss ein neues Unternehmen der Berufsgenossenschaft angezeigt werden?","erklaerung":"Binnen einer Woche nach Beginn des Unternehmens.","optionen":["1 Woche nach Beginn","1 Monat nach Beginn","3 Monate nach Beginn","Erst, wenn der erste Unfall passiert"]}},{"id":"ug-06","typ":"tf","frage":"Every trader is a merchant under the HGB, even if the business does not need a commercially organised operation.","richtig":false,"erklaerung":"Small traders whose business does not need a commercial organisation by type or size are not merchants. They can register voluntarily (§ 2 HGB).","quelle":"§ 1 Abs. 2 HGB","lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Jeder Gewerbetreibende ist Kaufmann im Sinne des HGB, auch wenn sein Betrieb keinen kaufmännisch eingerichteten Geschäftsbetrieb braucht.","erklaerung":"Kleingewerbetreibende, deren Betrieb nach Art oder Umfang keinen kaufmännischen Geschäftsbetrieb erfordert, sind keine Kaufleute. Sie können sich freiwillig eintragen lassen (§ 2 HGB)."}},{"id":"ug-07","typ":"single","frage":"What does the suffix “e. K.” after a company name mean?","optionen":["Registered capital company","Registered merchant (sole trader in the commercial register)","European cooperation","Former licence holder"],"richtig":1,"erklaerung":"Sole merchants in the commercial register use the suffix “eingetragener Kaufmann” or “e. K.”.","quelle":"§ 19 HGB","lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Was bedeutet der Zusatz „e. K.“ hinter einem Firmennamen?","erklaerung":"Einzelkaufleute im Handelsregister führen den Zusatz „eingetragener Kaufmann“ bzw. „e. K.“.","optionen":["Eingetragene Kapitalgesellschaft","Eingetragener Kaufmann (Einzelunternehmer im Handelsregister)","Europäische Kooperation","Ehemaliger Konzessionär"]}},{"id":"ug-08","typ":"single","frage":"Who receives the PBefG licence in a taxi GmbH?","optionen":["Every driver","The GmbH as operator; professional competence must be held by a person who manages the business","Only the largest shareholder personally","The IHK"],"richtig":1,"erklaerung":"The company is the operator. The applicant or the person appointed to manage the business must be professionally competent.","quelle":"§ 13 Abs. 1 Nr. 3 PBefG","lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Wer bekommt bei einer Taxi-GmbH die Genehmigung nach dem PBefG?","erklaerung":"Unternehmer ist die Gesellschaft. Fachlich geeignet muss der Antragsteller oder die zur Führung der Geschäfte bestellte Person sein.","optionen":["Jeder Fahrer","Die GmbH als Unternehmer; die fachliche Eignung muss eine Person haben, die die Geschäfte führt","Nur der größte Gesellschafter persönlich","Die IHK"]}},{"id":"ug-09","typ":"tf","frage":"A GmbH is always a merchant, even if it runs only one taxi.","richtig":true,"erklaerung":"Capital companies are merchants by legal form (Formkaufleute).","quelle":"§ 6 HGB, § 13 Abs. 3 GmbHG","lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Eine GmbH ist immer Kaufmann, auch wenn sie nur ein einziges Taxi betreibt.","erklaerung":"Kapitalgesellschaften sind Formkaufleute."}},{"id":"ug-10","typ":"single","frage":"What can the authority do if a trader is unreliable?","optionen":["Nothing, as long as he pays taxes","Prohibit the trade fully or partly","Only issue a warning","Hand the business over to the IHK"],"richtig":1,"erklaerung":"Prohibition of trade due to unreliability.","quelle":"§ 35 GewO","lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Was kann die Behörde tun, wenn ein Gewerbetreibender unzuverlässig ist?","erklaerung":"Gewerbeuntersagung wegen Unzuverlässigkeit.","optionen":["Nichts, solange er Steuern zahlt","Das Gewerbe ganz oder teilweise untersagen","Nur eine Verwarnung aussprechen","Den Betrieb an die IHK übergeben"]}},{"id":"ug-11","typ":"offen","frage":"Two friends want to found a Mietwagen business with 6 vehicles together and do not want to be liable with their private assets. Which legal form do you recommend? Give reasons and state the capital requirements.","muster":"<p>Recommendation: GmbH (or UG if little capital is available). Reason: in a GmbH only the company's assets are liable, not the shareholders' private assets. GbR or OHG are not suitable because all partners are liable without limit. Capital: GmbH at least 25.000 € share capital, at least 12.500 € paid in at registration (a quarter of each share). UG: possible below 25.000 €, but paid in fully in cash, no contributions in kind, a quarter of the surplus into a reserve each year. Founding at a notary, entry in the commercial register. Note: for the licence they must also prove 2.250 € + 5 × 1.250 € = 8.500 € equity and reserves.</p><p lang=\"de\"><i>Key German terms: Haftung, Stammkapital, Gesellschaftsvermögen, Handelsregister, Sacheinlage.</i></p>","punkte_liste":[{"t":"GmbH or UG recommended","p":1},{"t":"Reason: liability only with company assets; GbR/OHG unlimited","p":1},{"t":"GmbH: 25.000 € share capital, at least 12.500 € paid in","p":1},{"t":"UG: pay in fully, no contributions in kind, reserve","p":1},{"t":"Notary and commercial register (or equity of 8.500 € under PBZugV)","p":1}],"quelle":"GmbHG, HGB, PBZugV","lek":"unternehmen-gruenden","sg":"1.2","de":{"frage":"Zwei Freunde wollen gemeinsam einen Mietwagenbetrieb mit 6 Fahrzeugen gründen und möchten nicht mit ihrem Privatvermögen haften. Welche Rechtsform empfehlen Sie? Begründen Sie und nennen Sie die Kapitalanforderungen.","muster":"<p>Empfehlung: GmbH (oder UG, wenn wenig Kapital vorhanden ist). Begründung: Bei der GmbH haftet nur das Gesellschaftsvermögen, nicht das Privatvermögen der Gesellschafter. GbR oder OHG kommen nicht in Frage, weil dort alle unbeschränkt haften. Kapital: GmbH mindestens 25.000 € Stammkapital, bei Anmeldung mindestens 12.500 € eingezahlt (ein Viertel je Anteil). UG: unter 25.000 € möglich, aber voll in Geld einzuzahlen, keine Sacheinlagen, jährlich ein Viertel des Überschusses in die Rücklage. Gründung beim Notar, Eintragung ins Handelsregister. Hinweis: Für die Genehmigung zusätzlich 2.250 € + 5 × 1.250 € = 8.500 € Eigenkapital und Reserven nachweisen.</p>","punkte_liste":["GmbH oder UG empfohlen","Begründung: Haftung nur mit Gesellschaftsvermögen; GbR/OHG haften unbeschränkt","GmbH: 25.000 € Stammkapital, mind. 12.500 € eingezahlt","UG: voll einzahlen, keine Sacheinlagen, Rücklage","Notar und Handelsregister (oder Eigenkapital 8.500 € nach PBZugV)"]}},{"id":"vk-01","typ":"single","frage":"Under DGUV Vorschrift 70, who must check the vehicle's safety equipment before every shift?","optionen":["The garage","The driver","The TÜV","The Berufsgenossenschaft"],"richtig":1,"erklaerung":"The driver checks before every shift and reports defects. In addition, a competent person checks at least once a year.","quelle":"§§ 36, 57 DGUV Vorschrift 70","lc":true,"lek":"verkehrssicherheit","sg":"4.1","de":{"frage":"Wer muss nach DGUV Vorschrift 70 vor Beginn jeder Schicht die Sicherheitseinrichtungen des Fahrzeugs prüfen?","erklaerung":"Der Fahrzeugführer prüft vor jeder Schicht und meldet Mängel. Mindestens einmal jährlich prüft zusätzlich ein Sachkundiger.","optionen":["Die Werkstatt","Der Fahrer","Der TÜV","Die Berufsgenossenschaft"]}},{"id":"vk-02","typ":"zahl","frage":"According to the rules of thumb, how long is the stopping distance at 60 km/h with normal braking?","richtig":54,"einheit":"m","tol":0.1,"dez":0,"loesung":"Reaction distance = 6 × 3 = 18 m\nBraking distance = 6 × 6 = 36 m\nStopping distance = 18 + 36 = 54 m","erklaerung":"Reaction distance (v/10)×3 plus braking distance (v/10)².","quelle":"Fahrschul-Faustformeln","lc":true,"lek":"verkehrssicherheit","sg":"4.1","de":{"frage":"Wie lang ist der Anhalteweg bei 60 km/h und normaler Bremsung nach den Faustformeln?","erklaerung":"Reaktionsweg (v/10)×3 plus Bremsweg (v/10)².","loesung":"Reaktionsweg = 6 × 3 = 18 m\nBremsweg = 6 × 6 = 36 m\nAnhalteweg = 18 + 36 = 54 m","einheit":"m"}},{"id":"vk-03","typ":"single","frage":"How often must an employer at least instruct his drivers on safety and health?","optionen":["Only when hiring","At least once a year","Every 5 years","Only after an accident"],"richtig":1,"erklaerung":"When hiring, when something changes and at least once a year; document it.","quelle":"§ 12 ArbSchG, § 4 DGUV Vorschrift 1","lc":true,"lek":"verkehrssicherheit","sg":"4.1","de":{"frage":"Wie oft muss ein Arbeitgeber seine Fahrer mindestens über Sicherheit und Gesundheitsschutz unterweisen?","erklaerung":"Bei Einstellung, bei Veränderungen und mindestens einmal jährlich; dokumentieren.","optionen":["Nur bei der Einstellung","Mindestens einmal jährlich","Alle 5 Jahre","Nur nach einem Unfall"]}},{"id":"vk-04","typ":"zahl","frage":"According to the rule of thumb, how long is the braking distance in an emergency stop from 80 km/h?","richtig":32,"einheit":"m","tol":0.1,"dez":0,"loesung":"(80 ÷ 10)² ÷ 2 = 64 ÷ 2 = 32 m","erklaerung":"Emergency stop: half the normal braking distance.","quelle":"Fahrschul-Faustformeln","lek":"verkehrssicherheit","sg":"4.1","de":{"frage":"Wie lang ist der Bremsweg bei einer Gefahrbremsung aus 80 km/h nach der Faustformel?","erklaerung":"Gefahrbremsung: halber normaler Bremsweg.","loesung":"(80 ÷ 10)² ÷ 2 = 64 ÷ 2 = 32 m","einheit":"m"}},{"id":"vk-05","typ":"tf","frage":"If the speed doubles, the braking distance doubles too.","richtig":false,"erklaerung":"The braking distance grows with the square of the speed: twice as fast = four times the braking distance.","quelle":"Fahrphysik","lek":"verkehrssicherheit","sg":"4.1","de":{"frage":"Verdoppelt sich die Geschwindigkeit, verdoppelt sich auch der Bremsweg.","erklaerung":"Der Bremsweg wächst mit dem Quadrat der Geschwindigkeit: doppelt so schnell = vierfacher Bremsweg."}},{"id":"vk-06","typ":"single","frage":"Under DGUV Vorschrift 70, how often must the operator at least have his vehicles checked by a competent person?","optionen":["Monthly","At least once a year","Every 3 years","Never, the HU is enough"],"richtig":1,"erklaerung":"As needed, at least once a year, with a written result.","quelle":"§ 57 DGUV Vorschrift 70","lek":"verkehrssicherheit","sg":"4.1","de":{"frage":"Wie oft muss der Unternehmer seine Fahrzeuge nach DGUV Vorschrift 70 mindestens durch einen Sachkundigen prüfen lassen?","erklaerung":"Bei Bedarf, mindestens einmal jährlich, mit schriftlichem Ergebnis.","optionen":["Monatlich","Mindestens einmal jährlich","Alle 3 Jahre","Nie, die HU reicht"]}},{"id":"vk-07","typ":"offen","frage":"Write an instruction for your drivers on the pre-departure check. Name at least six check points.","muster":"<ul><li>Tyres: pressure, tread, damage</li><li>Lights, indicators, brake lights</li><li>Brakes and parking brake</li><li>Steering, horn, wipers</li><li>Mirrors, windows</li><li>Warning lights on the display</li><li>Equipment: first-aid kit, warning triangle, high-visibility vest, child seats</li><li>Taximeter, taxi sign, alarm system, papers</li><li>Report defects immediately; do not drive off with safety defects</li></ul><p lang=\"de\"><i>Key German terms: Abfahrtkontrolle, Profiltiefe, Feststellbremse, Verbandkasten, Mängel melden.</i></p>","punkte_liste":[{"t":"Tyres and lights","p":1},{"t":"Brakes, steering, visibility (mirrors/windows/wipers)","p":1},{"t":"Equipment and papers","p":1},{"t":"Taxi-specific (taximeter, sign, alarm, child seats)","p":1},{"t":"Report defects / don't drive off","p":1}],"quelle":"DGUV Vorschrift 70, DGUV Grundsatz 314-002","lek":"verkehrssicherheit","sg":"4.1","de":{"frage":"Erstellen Sie eine Anweisung für Ihre Fahrer zur Abfahrtkontrolle. Nennen Sie mindestens sechs Prüfpunkte.","muster":"<ul><li>Reifen: Luftdruck, Profil, Schäden</li><li>Beleuchtung, Blinker, Bremslichter</li><li>Bremse und Feststellbremse</li><li>Lenkung, Hupe, Scheibenwischer</li><li>Spiegel, Scheiben</li><li>Warnleuchten im Display</li><li>Ausrüstung: Verbandkasten, Warndreieck, Warnweste, Kindersitze</li><li>Taxameter, Taxischild, Alarmanlage, Papiere</li><li>Mängel sofort melden; bei Sicherheitsmängeln nicht losfahren</li></ul>","punkte_liste":["Reifen und Beleuchtung","Bremse, Lenkung, Sicht (Spiegel/Scheiben/Wischer)","Ausrüstung und Papiere","Taxispezifisch (Taxameter, Schild, Alarmanlage, Kindersitze)","Mängel melden / nicht losfahren"]}},{"id":"vs-01","typ":"multi","frage":"Which insurance is mandatory for a taxi operator with one employed driver? Select all correct answers.","optionen":["Motor liability insurance","Statutory accident insurance with the Berufsgenossenschaft","Social insurance for the employed driver","Comprehensive insurance (Vollkasko)","Legal expenses insurance"],"richtig":[0,1,2],"erklaerung":"Comprehensive and legal expenses insurance are voluntary (although comprehensive cover may be required by the leasing company or bank).","quelle":"PflVG, SGB VII, SGB IV","lc":true,"lek":"versicherungen","sg":"2.6","de":{"frage":"Welche Versicherungen sind für einen Taxiunternehmer mit einem angestellten Fahrer Pflicht? Wähle alle richtigen.","erklaerung":"Kasko und Rechtsschutz sind freiwillig (Vollkasko kann aber vom Leasinggeber oder der Bank verlangt werden).","optionen":["Kfz-Haftpflichtversicherung","Gesetzliche Unfallversicherung bei der Berufsgenossenschaft","Sozialversicherung für den angestellten Fahrer","Vollkaskoversicherung","Rechtsschutzversicherung"]}},{"id":"vs-02","typ":"single","frage":"What is the statutory minimum sum insured in motor liability for personal injury per accident (car)?","optionen":["1,3 m €","5 m €","7,5 m €","100 m €"],"fest":true,"richtig":2,"erklaerung":"7,5 m € personal injury, 1,3 m € property damage, 50.000 € pure financial loss.","quelle":"Anlage zu § 4 Abs. 2 PflVG","lc":true,"lek":"versicherungen","sg":"2.6","de":{"frage":"Wie hoch ist die gesetzliche Mindestversicherungssumme der Kfz-Haftpflicht für Personenschäden je Unfall (Pkw)?","erklaerung":"7,5 Mio. € Personenschäden, 1,3 Mio. € Sachschäden, 50.000 € reine Vermögensschäden.","optionen":["1,3 Mio. €","5 Mio. €","7,5 Mio. €","100 Mio. €"]}},{"id":"vs-03","typ":"single","frage":"A taxi driver causes an accident himself. His own taxi is badly damaged. Which insurance pays for the damage to his own vehicle?","optionen":["His own motor liability insurance","Comprehensive insurance (Vollkasko)","The Berufsgenossenschaft","Partial cover (Teilkasko)"],"richtig":1,"erklaerung":"Own-fault accident damage to your own vehicle is only paid by comprehensive insurance. Liability insurance pays for damage to others.","quelle":"Versicherungswesen","lc":true,"lek":"versicherungen","sg":"2.6","de":{"frage":"Ein Taxifahrer verursacht selbst einen Unfall. Sein eigenes Taxi ist schwer beschädigt. Welche Versicherung zahlt den Schaden am eigenen Fahrzeug?","erklaerung":"Selbst verschuldete Unfallschäden am eigenen Fahrzeug zahlt nur die Vollkasko. Die Haftpflicht zahlt Schäden anderer.","optionen":["Die eigene Kfz-Haftpflicht","Die Vollkaskoversicherung","Die Berufsgenossenschaft","Die Teilkasko"]}},{"id":"vs-04","typ":"single","frage":"An operator lets a driver without a driving licence drive. An accident happens. What applies in motor liability insurance?","optionen":["The insurer pays the injured party nothing.","The insurer pays the injured party and can reclaim up to 5.000 € from the operator.","The insurer pays and can reclaim everything without limit.","The injured party must contact the BG."],"richtig":1,"erklaerung":"Breach of a duty before the insured event: release from liability towards the policyholder limited to 5.000 €. The injured party is protected.","quelle":"§ 5 KfzPflVV","lc":true,"lek":"versicherungen","sg":"2.6","de":{"frage":"Ein Unternehmer lässt einen Fahrer ohne Fahrerlaubnis fahren. Es kommt zum Unfall. Was gilt in der Kfz-Haftpflicht?","erklaerung":"Obliegenheitsverletzung vor dem Versicherungsfall: Leistungsfreiheit gegenüber dem Versicherungsnehmer begrenzt auf 5.000 €. Der Geschädigte ist geschützt.","optionen":["Die Versicherung zahlt dem Geschädigten nichts.","Die Versicherung zahlt dem Geschädigten und kann beim Unternehmer bis zu 5.000 € zurückfordern.","Die Versicherung zahlt und kann alles unbegrenzt zurückfordern.","Der Geschädigte muss sich an die BG wenden."]}},{"id":"vs-05","typ":"tf","frage":"A Mietwagen may be driven with a normal private car insurance if it only carries passengers occasionally.","richtig":false,"erklaerung":"Use as a Mietwagen must be agreed in the contract. Otherwise it is a breach of duty (use clause) with recourse.","quelle":"§ 5 Abs. 1 Nr. 1 KfzPflVV","lc":true,"lek":"versicherungen","sg":"2.6","de":{"frage":"Ein Mietwagen darf mit einer normalen Privat-Pkw-Versicherung gefahren werden, wenn er nur selten Fahrgäste befördert.","erklaerung":"Die Verwendung als Mietwagen muss im Vertrag vereinbart sein. Sonst ist das eine Obliegenheitsverletzung (Verwendungsklausel) mit Regress."}},{"id":"vs-06","typ":"single","frage":"Which insurance pays if a passenger trips over a cable in the taxi company's office and is injured?","optionen":["Motor liability","Business liability","Partial cover","Daily sickness benefit insurance"],"richtig":1,"erklaerung":"Damage outside driving operations is covered by business liability insurance.","quelle":"Versicherungswesen","lek":"versicherungen","sg":"2.6","de":{"frage":"Welche Versicherung zahlt, wenn ein Fahrgast im Büro des Taxiunternehmens über ein Kabel stolpert und sich verletzt?","erklaerung":"Schäden außerhalb des Fahrbetriebs deckt die Betriebshaftpflicht.","optionen":["Kfz-Haftpflicht","Betriebshaftpflicht","Teilkasko","Krankentagegeldversicherung"]}},{"id":"vs-07","typ":"single","frage":"What does partial cover (Teilkasko) typically pay for?","optionen":["Own-fault accidents","Theft, fire, glass breakage, storm, hail, collision with animals","Damage to other people's cars","Loss of income"],"richtig":1,"erklaerung":"Comprehensive cover also pays for own-fault accidents and vandalism.","quelle":"Versicherungswesen","lek":"versicherungen","sg":"2.6","de":{"frage":"Was deckt die Teilkasko typischerweise?","erklaerung":"Vollkasko deckt zusätzlich selbst verschuldete Unfälle und Vandalismus.","optionen":["Selbst verschuldete Unfälle","Diebstahl, Brand, Glasbruch, Sturm, Hagel, Wildunfall","Schäden an fremden Autos","Verdienstausfall"]}},{"id":"vs-08","typ":"tf","frage":"An injured party can claim directly against the motor liability insurer of the person who caused the accident.","richtig":true,"erklaerung":"Direct claim under § 115 VVG.","quelle":"§ 115 VVG","lek":"versicherungen","sg":"2.6","de":{"frage":"Ein Geschädigter kann seinen Anspruch direkt gegen die Kfz-Haftpflichtversicherung des Unfallverursachers geltend machen.","erklaerung":"Direktanspruch nach § 115 VVG."}},{"id":"vs-09","typ":"offen","frage":"Which insurance do you recommend to a start-up with one Mietwagen who drives himself? Distinguish between mandatory and voluntary insurance.","muster":"<p><b>Mandatory:</b> motor liability (use as Mietwagen), statutory accident insurance with BG Verkehr, health insurance (with long-term care). <b>Voluntary, recommended:</b> comprehensive or partial cover (often required with financing/leasing), driver protection, business liability, legal expenses, business interruption, daily sickness benefit, occupational disability, retirement provision.</p>","punkte_liste":[{"t":"Motor liability as mandatory (with the correct use)","p":1},{"t":"BG accident insurance and health insurance as mandatory","p":1},{"t":"At least two sensible voluntary business insurances","p":1},{"t":"At least one personal cover (daily sickness benefit, disability, pension)","p":1}],"quelle":"Versicherungswesen","lek":"versicherungen","sg":"2.6","de":{"frage":"Welche Versicherungen empfehlen Sie einem Existenzgründer mit einem Mietwagen, der selbst fährt? Unterscheiden Sie Pflicht- und freiwillige Versicherungen.","muster":"<p><b>Pflicht:</b> Kfz-Haftpflicht (Verwendung als Mietwagen), gesetzliche Unfallversicherung bei der BG Verkehr, Krankenversicherung (mit Pflegeversicherung). <b>Freiwillig, empfehlenswert:</b> Voll- oder Teilkasko (bei Finanzierung/Leasing oft Pflicht), Fahrerschutz, Betriebshaftpflicht, Rechtsschutz, Betriebsunterbrechung, Krankentagegeld, Berufsunfähigkeit, Altersvorsorge.</p>","punkte_liste":["Kfz-Haftpflicht als Pflicht (mit richtiger Verwendung)","BG-Unfallversicherung und Krankenversicherung als Pflicht","Mindestens zwei sinnvolle betriebliche freiwillige Versicherungen","Mindestens eine persönliche Absicherung (Krankentagegeld, BU, Rente)"]}},{"id":"vh-01","typ":"zuordnung","frage":"Which type of contract is it?","kategorien":["Purchase","Rental","Contract for work","Loan"],"paare":[{"t":"A passenger takes a ride to the station.","k":2,"w":"Contract of carriage = contract for work (result owed)."},{"t":"The operator buys a new taxi from a dealer.","k":0,"w":"Purchase contract under § 433 BGB."},{"t":"The operator rents a garage for 120 € a month.","k":1,"w":"Rental contract under § 535 BGB."},{"t":"The bank lends the operator 30.000 € for 4 years.","k":3,"w":"Loan contract under § 488 BGB."},{"t":"The garage repairs the gearbox.","k":2,"w":"Repair = contract for work."}],"erklaerung":"Contract for work: result owed. Service contract: only the activity.","quelle":"BGB","lc":true,"lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Welcher Vertragstyp liegt vor?","erklaerung":"Werkvertrag: Erfolg geschuldet. Dienstvertrag: nur die Tätigkeit.","kategorien":["Kauf","Miete","Werkvertrag","Darlehen"],"paare":["Ein Fahrgast lässt sich zum Bahnhof fahren.","Der Unternehmer kauft beim Händler ein neues Taxi.","Der Unternehmer mietet eine Garage für 120 € im Monat.","Die Bank leiht dem Unternehmer 30.000 € für 4 Jahre.","Die Werkstatt repariert das Getriebe."]}},{"id":"vh-02","typ":"single","frage":"A taxi operator puts up a sign in the taxi: “No liability for personal injury.” Is this effective?","optionen":["Yes, if the passenger has seen it","No, in paid commercial passenger transport liability for death and injury of passengers may neither be excluded nor limited.","Yes, up to 1.000 €","Only for trips over 50 km"],"richtig":1,"erklaerung":"§ 8a StVG prohibits excluding or limiting keeper's liability towards passengers.","quelle":"§ 8a StVG","lc":true,"lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Ein Taxiunternehmer hängt ein Schild ins Taxi: „Keine Haftung für Personenschäden.“ Ist das wirksam?","erklaerung":"§ 8a StVG verbietet den Ausschluss und die Beschränkung der Halterhaftung gegenüber beförderten Personen.","optionen":["Ja, wenn der Fahrgast es gesehen hat","Nein, bei entgeltlicher geschäftsmäßiger Personenbeförderung darf die Haftung für Tod und Verletzung von Fahrgästen weder ausgeschlossen noch beschränkt werden.","Ja, bis 1.000 €","Nur bei Fahrten über 50 km"]}},{"id":"vh-03","typ":"zahl","frage":"Through a slightly negligent driving error, a passenger's laptop (value 1.800 €) is destroyed. The operator has excluded liability for property damage as far as legally allowed. How much must he pay?","richtig":1000,"einheit":"€","tol":0,"loesung":"Exclusion only for the part above 1.000 € → compensation: 1.000 €","erklaerung":"Liability for property damage can only be excluded for the amount above 1.000 €, and not in case of intent or gross negligence.","quelle":"§ 23 PBefG","lc":true,"lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Durch einen leicht fahrlässigen Fahrfehler wird der Laptop eines Fahrgasts zerstört (Wert 1.800 €). Der Unternehmer hat die Haftung für Sachschäden so weit wie gesetzlich zulässig ausgeschlossen. Wie viel muss er ersetzen?","erklaerung":"Der Haftungsausschluss für Sachschäden ist nur für den Betrag über 1.000 € möglich, und nicht bei Vorsatz oder grober Fahrlässigkeit.","loesung":"Ausschluss nur für den Teil über 1.000 € → Ersatz: 1.000 €","einheit":"€"}},{"id":"vh-04","typ":"single","frage":"After a trip a taxi driver finds a phone worth 600 € on the back seat. What applies?","optionen":["He may keep it if nobody comes forward.","He must hand it in without delay to the operator or the designated place. As an employee he gets no finder's reward.","He gets 10 % finder's reward.","He must take it to the IHK."],"richtig":1,"erklaerung":"§ 11 BOKraft: duty to check and hand in. § 978 BGB: employees of the transport company have no claim to a finder's reward.","quelle":"§ 11 BOKraft, § 978 BGB","lc":true,"lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Ein Taxifahrer findet nach der Fahrt ein Handy im Wert von 600 € auf dem Rücksitz. Was gilt?","erklaerung":"§ 11 BOKraft: Pflicht zur Prüfung und Abgabe. § 978 BGB: Mitarbeiter des Verkehrsunternehmens haben keinen Anspruch auf Finderlohn.","optionen":["Er darf es behalten, wenn sich niemand meldet.","Er muss es unverzüglich beim Unternehmer oder der bestimmten Stelle abgeben. Finderlohn bekommt er als Mitarbeiter nicht.","Er bekommt 10 % Finderlohn.","Er muss es zur IHK bringen."]}},{"id":"vh-05","typ":"single","frage":"What type of contract is the contract of carriage?","optionen":["Purchase contract","Rental contract","Contract for work (Werkvertrag)","Service contract (Dienstvertrag)"],"richtig":2,"erklaerung":"The result is owed: carriage to the destination.","quelle":"§ 631 BGB","lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Welcher Vertragstyp ist der Beförderungsvertrag?","erklaerung":"Geschuldet wird der Erfolg: die Beförderung ans Ziel.","optionen":["Kaufvertrag","Mietvertrag","Werkvertrag","Dienstvertrag"]}},{"id":"vh-06","typ":"tf","frage":"The keeper of a taxi is liable for damage from operating the vehicle even if neither he nor the driver is at fault.","richtig":true,"erklaerung":"Keeper's liability is strict liability. It is only excluded in case of force majeure.","quelle":"§ 7 StVG","lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Der Halter eines Taxis haftet für Schäden aus dem Betrieb des Fahrzeugs auch dann, wenn weder er noch der Fahrer Schuld hat.","erklaerung":"Halterhaftung ist Gefährdungshaftung. Ausgeschlossen ist sie nur bei höherer Gewalt."}},{"id":"vh-07","typ":"single","frage":"What is the maximum amount of keeper's liability for personal injury in one accident (without special cases)?","optionen":["1 m €","2,5 m €","5 m €","unlimited"],"fest":true,"richtig":2,"erklaerung":"5 m € for personal injury, 1 m € for property damage per event. With fault under § 823 BGB there is no limit.","quelle":"§ 12 StVG","lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Wie hoch ist der Höchstbetrag der Halterhaftung für Personenschäden bei einem Unfall (ohne Sonderfälle)?","erklaerung":"5 Mio. € für Personenschäden, 1 Mio. € für Sachschäden je Ereignis. Bei Verschulden nach § 823 BGB gibt es keine Grenze.","optionen":["1 Mio. €","2,5 Mio. €","5 Mio. €","unbegrenzt"]}},{"id":"vh-08","typ":"tf","frage":"A passenger who finds a wallet with 300 € in the taxi can claim a halved finder's reward.","richtig":true,"erklaerung":"From a value of 50 €, the finder (who is not an employee) can claim a reward of half the normal rate if he hands in the item properly.","quelle":"§ 978 Abs. 2 BGB","lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Ein Fahrgast, der im Taxi ein Portemonnaie mit 300 € findet, kann einen halbierten Finderlohn verlangen.","erklaerung":"Ab einem Wert von 50 € hat der Finder (der kein Mitarbeiter ist) Anspruch auf Finderlohn in halber Höhe des normalen Satzes, wenn er die Sache ordnungsgemäß abgibt."}},{"id":"vh-09","typ":"single","frage":"An invoice for a company trip on 10 March 2026 is not paid. When does the claim become time-barred?","optionen":["10 March 2027","31 December 2027","31 December 2029","10 March 2036"],"richtig":2,"erklaerung":"Regular limitation 3 years, starting at the end of the year in which the claim arose: 31.12.2026 + 3 years = 31.12.2029.","quelle":"§§ 195, 199 BGB","lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Eine Taxirechnung aus einer Firmenfahrt vom 10. März 2026 wird nicht bezahlt. Wann verjährt die Forderung?","erklaerung":"Regelmäßige Verjährung 3 Jahre, Beginn am Schluss des Jahres der Entstehung: 31.12.2026 + 3 Jahre = 31.12.2029.","optionen":["10. März 2027","31. Dezember 2027","31. Dezember 2029","10. März 2036"]}},{"id":"vh-10","typ":"single","frage":"A 9-year-old child gets into a taxi alone and wants to go home. What is the legal situation?","optionen":["The child has full legal capacity.","The child has limited capacity. The contract is valid if the parents agree or it pays with its own money (pocket money).","Children may never take a taxi.","The child has no legal capacity; the contract is always void."],"richtig":1,"erklaerung":"7 to 17 years: limited capacity (§§ 106 ff. BGB), pocket money rule § 110 BGB.","quelle":"§§ 106, 107, 110 BGB","lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Ein 9-jähriges Kind steigt allein ins Taxi und will nach Hause fahren. Wie ist die rechtliche Lage?","erklaerung":"7 bis 17 Jahre: beschränkt geschäftsfähig (§§ 106 ff. BGB), Taschengeldparagraph § 110 BGB.","optionen":["Das Kind ist voll geschäftsfähig.","Das Kind ist beschränkt geschäftsfähig. Der Vertrag ist wirksam, wenn die Eltern zustimmen oder es mit eigenen Mitteln (Taschengeld) bezahlt.","Kinder dürfen nie Taxi fahren.","Das Kind ist geschäftsunfähig, der Vertrag ist immer nichtig."]}},{"id":"vh-11","typ":"offen","frage":"A taxi crashes without fault because another car ignores the right of way. A passenger is injured and his luggage damaged. Explain the liability towards the passenger.","muster":"<p>The keeper of the taxi is liable to the passenger under § 7 StVG even without fault (strict liability), except for force majeure. In paid transport, liability for personal injury may not be excluded (§ 8a StVG). For property damage it can only be excluded for the part above 1.000 € (§ 23 PBefG). The driver who caused the accident and his keeper are also liable (§§ 7, 18 StVG, § 823 BGB). The motor liability insurers settle the damage; liability shares are balanced between those involved.</p><p lang=\"de\"><i>Key German terms: Halterhaftung, Gefährdungshaftung, höhere Gewalt, Haftungsausschluss, Sachschaden.</i></p>","punkte_liste":[{"t":"Keeper's liability of the taxi without fault (§ 7 StVG)","p":1},{"t":"No exclusion for personal injury (§ 8a StVG)","p":1},{"t":"Property damage: exclusion only above 1.000 € (§ 23 PBefG)","p":1},{"t":"Liability of the other driver / insurance","p":1}],"quelle":"StVG, PBefG, BGB","lek":"vertraege-haftung","sg":"1.6","de":{"frage":"Ein Taxi verunglückt unverschuldet, weil ein anderes Auto die Vorfahrt missachtet. Ein Fahrgast wird verletzt, sein Gepäck beschädigt. Erläutern Sie die Haftung gegenüber dem Fahrgast.","muster":"<p>Der Halter des Taxis haftet gegenüber dem Fahrgast nach § 7 StVG auch ohne Verschulden (Gefährdungshaftung), außer bei höherer Gewalt. Bei entgeltlicher Beförderung darf die Haftung für Personenschäden nicht ausgeschlossen werden (§ 8a StVG). Für Sachschäden kann sie nur für den Teil über 1.000 € ausgeschlossen werden (§ 23 PBefG). Auch der Unfallverursacher und dessen Halter haften (§§ 7, 18 StVG, § 823 BGB). Die Kfz-Haftpflichtversicherungen regulieren den Schaden; Haftungsquoten werden zwischen den Beteiligten ausgeglichen.</p>","punkte_liste":["Halterhaftung des Taxis ohne Verschulden (§ 7 StVG)","Kein Ausschluss bei Personenschäden (§ 8a StVG)","Sachschäden: Ausschluss nur über 1.000 € (§ 23 PBefG)","Haftung des Unfallverursachers / Versicherung"]}},{"id":"wh-01","typ":"single","frage":"How often must a taxi go for its general inspection (HU)?","optionen":["Every 6 months","Every 12 months","Every 24 months","Every 36 months"],"fest":true,"richtig":1,"erklaerung":"Cars for passenger transport under the PBefG: 12 months.","quelle":"§ 29 StVZO, Anlage VIII","lc":true,"lek":"wartung-hu","sg":"3.2","de":{"frage":"In welchen Abständen muss ein Taxi zur Hauptuntersuchung?","erklaerung":"Pkw zur Personenbeförderung nach PBefG: 12 Monate.","optionen":["Alle 6 Monate","Alle 12 Monate","Alle 24 Monate","Alle 36 Monate"]}},{"id":"wh-02","typ":"zuordnung","frage":"How often must it be calibrated or inspected?","kategorien":["every year","every 2 years"],"paare":[{"t":"Taximeter","k":0,"w":"Calibration interval 1 year."},{"t":"Distance meter in a Mietwagen","k":1,"w":"Calibration interval 2 years."},{"t":"General inspection of a taxi","k":0,"w":"12 months."},{"t":"General inspection of a Mietwagen","k":0,"w":"Mietwagen under the PBefG too: 12 months."}],"erklaerung":"Don't mix them up: the HU (StVZO) and calibration (calibration law) are different checks.","quelle":"StVZO Anlage VIII, MessEV","lc":true,"lek":"wartung-hu","sg":"3.2","de":{"frage":"Wie oft muss geeicht bzw. geprüft werden?","erklaerung":"Nicht verwechseln: HU (StVZO) und Eichung (Eichrecht) sind verschiedene Prüfungen.","kategorien":["jedes Jahr","alle 2 Jahre"],"paare":["Fahrpreisanzeiger (Taxameter)","Wegstreckenzähler im Mietwagen","Hauptuntersuchung Taxi","Hauptuntersuchung Mietwagen"]}},{"id":"wh-03","typ":"multi","frage":"When must a taximeter be recalibrated before the calibration interval ends? Select all correct answers.","optionen":["After a repair of the device","After reprogramming because of a tariff change","After installation in a different vehicle","After every oil-change service","When the driver changes"],"richtig":[0,1,2],"erklaerung":"Every intervention in the measuring device or its adjustment to the vehicle requires new calibration.","quelle":"Eichrecht","lc":true,"lek":"wartung-hu","sg":"3.2","de":{"frage":"Wann muss ein Taxameter vor Ablauf der Eichfrist neu geeicht werden? Wähle alle richtigen.","erklaerung":"Jeder Eingriff in das Messgerät oder seine Anpassung an das Fahrzeug erfordert eine neue Eichung.","optionen":["Nach einer Reparatur am Gerät","Nach einer Neuprogrammierung wegen Tarifänderung","Nach Einbau in ein anderes Fahrzeug","Nach jeder Ölwechsel-Inspektion","Wenn der Fahrer wechselt"]}},{"id":"wh-04","typ":"tf","frage":"During the general inspection of a taxi it is also checked whether the vehicle complies with BOKraft.","richtig":true,"erklaerung":"§ 41 BOKraft.","quelle":"§ 41 BOKraft","lek":"wartung-hu","sg":"3.2","de":{"frage":"Bei der Hauptuntersuchung eines Taxis wird auch geprüft, ob das Fahrzeug den Vorschriften der BOKraft entspricht.","erklaerung":"§ 41 BOKraft."}},{"id":"wh-05","typ":"single","frage":"Who calibrates taximeters?","optionen":["The IHK","The state calibration office (Eichamt)","Any car workshop","The licensing authority"],"richtig":1,"erklaerung":"Calibration is the task of the calibration authorities of the federal states.","quelle":"Mess- und Eichgesetz","lek":"wartung-hu","sg":"3.2","de":{"frage":"Wer eicht Taxameter?","erklaerung":"Eichung ist Aufgabe der Eichbehörden der Länder.","optionen":["Die IHK","Das Eichamt des Landes","Jede Kfz-Werkstatt","Die Genehmigungsbehörde"]}},{"id":"wh-06","typ":"offen","frage":"Draw up a maintenance plan for a taxi that drives 80.000 km a year. Name at least five measures with timing.","muster":"<ul><li>Before every shift: pre-departure check (lights, tyres, brakes, equipment, taximeter)</li><li>Weekly: tyre pressure, fluids, cleaning</li><li>Service according to the manufacturer, at 80.000 km several times a year</li><li>Summer/winter tyre change, check tread depth</li><li>Yearly: HU with emissions test, report to the licensing authority</li><li>Yearly: taximeter calibration</li><li>Maintenance log with mileage and next dates</li></ul><p lang=\"de\"><i>Key German terms: Abfahrtkontrolle, Inspektion, Hauptuntersuchung, Eichung, Wartungsheft.</i></p>","punkte_liste":[{"t":"Daily pre-departure check","p":1},{"t":"Service by km / manufacturer","p":1},{"t":"Yearly HU","p":1},{"t":"Yearly taximeter calibration","p":1},{"t":"Another sensible measure (tyres, log …)","p":1}],"quelle":"StVZO, BOKraft, MessEV","lek":"wartung-hu","sg":"3.2","de":{"frage":"Stellen Sie einen Wartungsplan für ein Taxi mit 80.000 km Fahrleistung im Jahr auf. Nennen Sie mindestens fünf Maßnahmen mit Zeitpunkt.","muster":"<ul><li>Vor jeder Schicht: Abfahrtkontrolle (Licht, Reifen, Bremsen, Ausrüstung, Taxameter)</li><li>Wöchentlich: Reifendruck, Flüssigkeiten, Reinigung</li><li>Inspektion nach Herstellerangabe, bei 80.000 km mehrmals im Jahr</li><li>Reifenwechsel Sommer/Winter, Kontrolle Profiltiefe</li><li>Jährlich: HU mit AU, Bericht an Genehmigungsbehörde</li><li>Jährlich: Eichung Taxameter</li><li>Wartungsheft mit km-Stand und nächsten Terminen</li></ul>","punkte_liste":["Tägliche Abfahrtkontrolle","Inspektion nach km/Herstellerangabe","Jährliche HU","Jährliche Eichung Taxameter","Weitere sinnvolle Maßnahme (Reifen, Wartungsheft …)"]}},{"id":"zf-01","typ":"single","frage":"A customer reverses a SEPA core direct debit. Until when is this possible without giving reasons if a mandate existed?","optionen":["5 days","8 weeks","13 months","Not at all"],"fest":true,"richtig":1,"erklaerung":"8 weeks after debiting for an authorised core debit. Without a mandate: up to 13 months. B2B direct debit: no refund.","quelle":"§§ 675x, 676b BGB","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Ein Kunde lässt eine SEPA-Basislastschrift zurückbuchen. Bis wann ist das ohne Angabe von Gründen möglich, wenn ein Mandat vorlag?","erklaerung":"8 Wochen nach Belastung bei autorisierter Basislastschrift. Ohne Mandat: bis 13 Monate. Firmenlastschrift: keine Rückgabe.","optionen":["5 Tage","8 Wochen","13 Monate","Gar nicht"]}},{"id":"zf-02","typ":"single","frage":"A taxi operator finances his vehicle through the bank. The bank becomes owner, he may keep driving the taxi. The bank keeps the registration certificate part II. What is this collateral called?","optionen":["Personal guarantee (Bürgschaft)","Land charge (Grundschuld)","Transfer of ownership as security (Sicherungsübereignung)","Retention of title (Eigentumsvorbehalt)"],"richtig":2,"erklaerung":"With transfer of ownership as security, the bank becomes owner and the operator remains in possession.","quelle":"Kreditsicherheiten","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Ein Taxiunternehmer finanziert sein Fahrzeug über die Bank. Die Bank wird Eigentümerin, er darf das Taxi weiter fahren. Die Bank behält die Zulassungsbescheinigung Teil II. Wie heißt diese Sicherheit?","erklaerung":"Bei der Sicherungsübereignung wird die Bank Eigentümerin, der Unternehmer bleibt Besitzer.","optionen":["Bürgschaft","Grundschuld","Sicherungsübereignung","Eigentumsvorbehalt"]}},{"id":"zf-03","typ":"multi","frage":"Which disadvantages can leasing have for a taxi? Select all correct answers.","optionen":["Mileage limit with extra payment for extra km","Usually more expensive overall than buying with cash","Extra payment for damage when returning","You need more own capital than when buying","The payments are never tax-deductible"],"richtig":[0,1,2],"erklaerung":"Leasing needs little own capital and the payments are business expenses. For taxis with high mileage the km limit is an important issue.","quelle":"Finanzierung","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Welche Nachteile kann Leasing für ein Taxi haben? Wähle alle richtigen.","erklaerung":"Leasing braucht wenig Eigenkapital und die Raten sind Betriebsausgaben. Bei Taxis mit hoher Fahrleistung ist die km-Grenze ein wichtiges Thema.","optionen":["Kilometerbegrenzung mit Nachzahlung bei Mehr-km","Meist insgesamt teurer als ein Barkauf","Nachzahlung für Schäden bei Rückgabe","Man braucht mehr Eigenkapital als beim Kauf","Die Raten sind steuerlich nie absetzbar"]}},{"id":"zf-04","typ":"zahl","frage":"An operator uses an overdraft of 12.000 € for 60 days at 9 % interest. How much interest does he pay (commercial, 360 days)?","richtig":180,"einheit":"€","loesung":"12.000 × 9 × 60 ÷ (100 × 360) = 180,00 €","erklaerung":"Interest = K × p × t ÷ (100 × 360).","quelle":"Zinsrechnung","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Ein Unternehmer nutzt einen Kontokorrentkredit von 12.000 € für 60 Tage zu 9 % Zinsen. Wie viel Zinsen zahlt er (kaufmännisch, 360 Tage)?","erklaerung":"Zinsen = K × p × t ÷ (100 × 360).","loesung":"12.000 × 9 × 60 ÷ (100 × 360) = 180,00 €","einheit":"€"}},{"id":"zf-05","typ":"zahl","frage":"A garage invoice of 2.400 € is due in 30 days. If paid within 10 days there is a 3 % cash discount. What is the annual rate of the discount (approximation formula)?","richtig":54,"einheit":"%","tol":0.1,"dez":0,"loesung":"3 % × 360 ÷ (30 − 10) = 3 × 18 = 54 %","erklaerung":"Using cash discounts is almost always worth it.","quelle":"Skonto","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Eine Werkstattrechnung über 2.400 € ist in 30 Tagen fällig. Bei Zahlung innerhalb von 10 Tagen gibt es 3 % Skonto. Wie hoch ist der Skonto-Jahreszins (Näherungsformel)?","erklaerung":"Skonto zu nutzen lohnt sich fast immer.","loesung":"3 % × 360 ÷ (30 − 10) = 3 × 18 = 54 %","einheit":"%"}},{"id":"zf-06","typ":"zahl","frage":"A business has 25.000 € equity and 75.000 € debt. What is the equity ratio?","richtig":25,"einheit":"%","tol":0.1,"dez":0,"loesung":"Total capital = 25.000 + 75.000 = 100.000 €\n25.000 ÷ 100.000 × 100 = 25 %","erklaerung":"Equity ratio = equity ÷ total capital × 100.","quelle":"Kennzahlen","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Ein Betrieb hat 25.000 € Eigenkapital und 75.000 € Fremdkapital. Wie hoch ist die Eigenkapitalquote?","erklaerung":"Eigenkapitalquote = Eigenkapital ÷ Gesamtkapital × 100.","loesung":"Gesamtkapital = 25.000 + 75.000 = 100.000 €\n25.000 ÷ 100.000 × 100 = 25 %","einheit":"%"}},{"id":"zf-07","typ":"zahl","frage":"Cash 6.000 €, short-term receivables 9.000 €, short-term liabilities 12.000 €. What is the liquidity of the 2nd degree?","richtig":125,"einheit":"%","tol":0.1,"dez":0,"loesung":"(6.000 + 9.000) ÷ 12.000 × 100 = 125 %","erklaerung":"Liquidity 2nd degree = (cash + short-term receivables) ÷ short-term liabilities. Over 100 % is good.","quelle":"Kennzahlen","lc":true,"lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Flüssige Mittel 6.000 €, kurzfristige Forderungen 9.000 €, kurzfristige Verbindlichkeiten 12.000 €. Wie hoch ist die Liquidität 2. Grades?","erklaerung":"Liquidität 2. Grades = (flüssige Mittel + kurzfristige Forderungen) ÷ kurzfristige Verbindlichkeiten. Über 100 % ist gut.","loesung":"(6.000 + 9.000) ÷ 12.000 × 100 = 125 %","einheit":"%"}},{"id":"zf-08","typ":"zahl","frage":"A Mietwagen business has 180.000 € turnover and 18.000 € profit. What is the return on sales?","richtig":10,"einheit":"%","tol":0.1,"dez":0,"loesung":"18.000 ÷ 180.000 × 100 = 10 %","erklaerung":"Out of 100 € turnover, 10 € are profit.","quelle":"Kennzahlen","lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Ein Mietwagenbetrieb macht 180.000 € Umsatz und 18.000 € Gewinn. Wie hoch ist die Umsatzrentabilität?","erklaerung":"Von 100 € Umsatz bleiben 10 € Gewinn.","loesung":"18.000 ÷ 180.000 × 100 = 10 %","einheit":"%"}},{"id":"zf-09","typ":"single","frage":"What is an annuity loan (Annuitätendarlehen)?","optionen":["Loan with equal repayment, the instalment falls","Loan with an equal instalment of interest and repayment; the repayment share rises","Loan repaid in one sum at the end","Credit line on the current account"],"richtig":1,"erklaerung":"Annuity = constant instalment. The interest share falls, the repayment share rises.","quelle":"Kreditarten","lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Was ist ein Annuitätendarlehen?","erklaerung":"Annuität = gleichbleibende Rate. Der Zinsanteil sinkt, der Tilgungsanteil steigt.","optionen":["Darlehen mit gleich hoher Tilgung, die Rate sinkt","Darlehen mit gleich hoher Rate aus Zins und Tilgung; der Tilgungsanteil steigt","Darlehen, das am Ende in einer Summe zurückgezahlt wird","Kreditlinie auf dem Girokonto"]}},{"id":"zf-10","typ":"tf","frage":"Since October 2025, banks in the euro area may not charge more for instant transfers than for normal transfers.","richtig":true,"erklaerung":"The EU Instant Payments Regulation requires this. The money arrives within 10 seconds at most.","quelle":"VO (EU) 2024/886","lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Seit Oktober 2025 dürfen Banken im Euroraum für Echtzeitüberweisungen nicht mehr verlangen als für normale Überweisungen.","erklaerung":"Das schreibt die EU-Verordnung über Sofortzahlungen vor. Das Geld kommt in höchstens 10 Sekunden an."}},{"id":"zf-11","typ":"single","frage":"Which loan is suitable for short-term gaps, for example until a health insurer pays its collective invoice?","optionen":["Overdraft (Kontokorrentkredit)","Mortgage","Bullet loan over 10 years","Documentary credit"],"richtig":0,"erklaerung":"The overdraft is flexible but expensive. It is meant for short-term gaps.","quelle":"Kreditarten","lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Welcher Kredit eignet sich für kurzfristige Engpässe, zum Beispiel bis eine Krankenkasse ihre Sammelrechnung bezahlt?","erklaerung":"Der Kontokorrentkredit ist flexibel, aber teuer. Er ist für kurzfristige Lücken gedacht.","optionen":["Kontokorrentkredit","Hypothek","Fälligkeitsdarlehen über 10 Jahre","Dokumentenkredit"]}},{"id":"zf-12","typ":"zahl","frage":"An operator has invested 50.000 € equity and made 12.000 € profit. What is the return on equity?","richtig":24,"einheit":"%","tol":0.1,"dez":0,"loesung":"12.000 ÷ 50.000 × 100 = 24 %","erklaerung":"Return on equity = profit ÷ equity × 100.","quelle":"Kennzahlen","lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Ein Unternehmer hat 50.000 € Eigenkapital eingesetzt und 12.000 € Gewinn erzielt. Wie hoch ist die Eigenkapitalrentabilität?","erklaerung":"Eigenkapitalrentabilität = Gewinn ÷ Eigenkapital × 100.","loesung":"12.000 ÷ 50.000 × 100 = 24 %","einheit":"%"}},{"id":"zf-13","typ":"offen","frage":"A taxi operator wants to buy a new vehicle for 45.000 €. Compare buying with a bank loan and leasing. Name two advantages and two disadvantages each.","muster":"<p><b>Buying with a loan:</b> advantages: the vehicle belongs to the operator (after repayment), no km limit, depreciation usable for tax, usually cheaper overall. Disadvantages: the bank asks for collateral (transfer of ownership) and equity, interest and repayment burden, residual value risk with the operator.</p><p><b>Leasing:</b> advantages: little equity, predictable payments, payments are business expenses, often with service. Disadvantages: usually more expensive overall, km limit (critical for taxis), extra payments for extra km and damage, the vehicle does not belong to the operator.</p>","punkte_liste":[{"t":"Two advantages of buying/loan","p":1},{"t":"Two disadvantages of buying/loan","p":1},{"t":"Two advantages of leasing","p":1},{"t":"Two disadvantages of leasing (e.g. km limit)","p":1}],"quelle":"Finanzierung","lek":"zahlungsverkehr-finanzierung","sg":"2.1","de":{"frage":"Ein Taxiunternehmer will ein neues Fahrzeug für 45.000 € anschaffen. Vergleichen Sie Kauf mit Bankkredit und Leasing. Nennen Sie je zwei Vor- und Nachteile.","muster":"<p><b>Kauf mit Kredit:</b> Vorteile: Fahrzeug gehört (nach Tilgung) dem Unternehmer, keine km-Begrenzung, Abschreibung steuerlich nutzbar, meist günstiger insgesamt. Nachteile: Bank verlangt Sicherheiten (Sicherungsübereignung) und Eigenkapital, Zins- und Tilgungslast, Restwertrisiko beim Unternehmer.</p><p><b>Leasing:</b> Vorteile: wenig Eigenkapital, planbare Raten, Raten als Betriebsausgaben, oft mit Service. Nachteile: insgesamt meist teurer, km-Begrenzung (bei Taxis kritisch), Nachzahlungen für Mehr-km und Schäden, Fahrzeug gehört nicht dem Unternehmer.</p>","punkte_liste":["Zwei Vorteile Kauf/Kredit","Zwei Nachteile Kauf/Kredit","Zwei Vorteile Leasing","Zwei Nachteile Leasing (z. B. km-Grenze)"]}},{"id":"zl-01","typ":"single","frage":"Which document belongs in the vehicle and which in the office?","optionen":["Part I and part II both belong in the vehicle.","Part I (Fahrzeugschein) in the vehicle, part II (Fahrzeugbrief) in the office.","Part II in the vehicle, part I in the office.","Both belong to the registration authority."],"richtig":1,"erklaerung":"The vehicle title proves the right to dispose of the vehicle and must be kept safe, with financing often at the bank.","quelle":"FZV","lc":true,"lek":"zulassung","sg":"3.1","de":{"frage":"Welches Dokument gehört ins Fahrzeug, welches ins Büro?","erklaerung":"Der Fahrzeugbrief ist der Nachweis der Verfügungsberechtigung und gehört sicher verwahrt, bei Finanzierung oft bei der Bank.","optionen":["Teil I und Teil II gehören beide ins Fahrzeug.","Teil I (Fahrzeugschein) ins Fahrzeug, Teil II (Fahrzeugbrief) ins Büro.","Teil II ins Fahrzeug, Teil I ins Büro.","Beide gehören zur Zulassungsbehörde."]}},{"id":"zl-02","typ":"multi","frage":"What must happen before a newly registered vehicle may be used as a taxi? Select all correct answers.","optionen":["Calibration of the taximeter in the vehicle","General inspection under § 42 BOKraft with a report to the licensing authority","Entry of the vehicle (number plate) in the licence","Registration with the IHK","Acceptance by the police"],"richtig":[0,1,2],"erklaerung":"Before first use: equipment, calibration, BOKraft inspection, entry in the licence and licence number.","quelle":"§ 42 BOKraft, § 17 PBefG","lc":true,"lek":"zulassung","sg":"3.1","de":{"frage":"Was muss geschehen, bevor ein neu zugelassenes Fahrzeug als Taxi eingesetzt werden darf? Wähle alle richtigen.","erklaerung":"Vor dem ersten Einsatz: Ausrüstung, Eichung, BOKraft-Untersuchung, Eintragung in die Genehmigung und Ordnungsnummer.","optionen":["Eichung des Fahrpreisanzeigers im Fahrzeug","Hauptuntersuchung nach § 42 BOKraft mit Bericht an die Genehmigungsbehörde","Eintragung des Fahrzeugs (Kennzeichen) in die Genehmigung","Anmeldung bei der IHK","Abnahme durch die Polizei"]}},{"id":"zl-03","typ":"single","frage":"A taxi operator replaces an old taxi with a new one. What must he do towards the licensing authority?","optionen":["Nothing, the licence applies to the operator.","Present the licence document for amendment so that the new vehicle is entered.","Apply for a completely new licence with a hearing.","Only inform the insurer."],"richtig":1,"erklaerung":"§ 17 (2) PBefG. A pure vehicle exchange needs no hearing (§ 14 (3)).","quelle":"§§ 14, 17 PBefG","lc":true,"lek":"zulassung","sg":"3.1","de":{"frage":"Ein Taxiunternehmer ersetzt ein altes Taxi durch ein neues. Was muss er gegenüber der Genehmigungsbehörde tun?","erklaerung":"§ 17 Abs. 2 PBefG. Für den reinen Fahrzeugaustausch ist keine Anhörung nötig (§ 14 Abs. 3).","optionen":["Nichts, die Genehmigung gilt für den Unternehmer.","Die Genehmigungsurkunde zur Änderung vorlegen, damit das neue Fahrzeug eingetragen wird.","Eine komplett neue Genehmigung mit Anhörung beantragen.","Nur die Versicherung informieren."]}},{"id":"zl-04","typ":"single","frage":"Which authority registers vehicles?","optionen":["The IHK","The registration authority (Straßenverkehrsamt of the district or city)","The Federal Motor Transport Authority (KBA) directly","The licensing authority under the PBefG"],"richtig":1,"erklaerung":"Registration: registration authority. Licence under the PBefG: licensing authority. These can be two different offices.","quelle":"FZV","lek":"zulassung","sg":"3.1","de":{"frage":"Welche Behörde lässt Fahrzeuge zu?","erklaerung":"Zulassung: Zulassungsbehörde. Genehmigung nach PBefG: Genehmigungsbehörde. Das können zwei verschiedene Ämter sein.","optionen":["Die IHK","Die Zulassungsbehörde (Straßenverkehrsamt von Kreis oder kreisfreier Stadt)","Das Kraftfahrt-Bundesamt direkt","Die Genehmigungsbehörde nach PBefG"]}},{"id":"zl-05","typ":"tf","frage":"The taxi operator must present the general inspection report to the licensing authority (or the body named by the federal state) without delay.","richtig":true,"erklaerung":"§ 41 BOKraft requires a copy of the inspection report.","quelle":"§ 41 BOKraft","lek":"zulassung","sg":"3.1","de":{"frage":"Den Prüfbericht der Hauptuntersuchung muss der Taxiunternehmer unverzüglich der Genehmigungsbehörde (oder der vom Land bestimmten Stelle) vorlegen.","erklaerung":"§ 41 BOKraft verlangt eine Abschrift des Untersuchungsberichts."}},{"id":"zl-06","typ":"single","frage":"What is the eVB?","optionen":["The electronic insurance confirmation for motor liability, needed for registration","The calibration certificate of the taximeter","The income tax prepayment","A fine notice"],"richtig":0,"erklaerung":"No registration without proof of motor liability insurance.","quelle":"FZV, PflVG","lek":"zulassung","sg":"3.1","de":{"frage":"Was ist die eVB?","erklaerung":"Ohne Nachweis der Kfz-Haftpflicht keine Zulassung.","optionen":["Die elektronische Versicherungsbestätigung der Kfz-Haftpflicht, nötig für die Zulassung","Die Eichbescheinigung des Taxameters","Die Einkommensteuervorauszahlung","Ein Bußgeldbescheid"]}},{"id":"zl-07","typ":"offen","frage":"Describe the steps from buying a new vehicle to its first use as a Mietwagen.","muster":"<p>Buy a vehicle with type approval/COC; equip it (distance meter with TSE, alarm system, no taxi markings); insure it as a Mietwagen (eVB); register it with the registration authority; have the distance meter calibrated; general inspection under § 42 BOKraft before first use, report to the licensing authority; have the vehicle entered in the licence and attach the licence number; report the recording system to the tax office.</p><p lang=\"de\"><i>Key German terms: Zulassung, Eichung, Hauptuntersuchung nach BOKraft, Genehmigungsurkunde, Ordnungsnummer.</i></p>","punkte_liste":[{"t":"Equipment (distance meter, alarm system)","p":1},{"t":"Insurance and registration","p":1},{"t":"Calibration","p":1},{"t":"Inspection under BOKraft with report to the authority","p":1},{"t":"Entry in the licence / licence number","p":1}],"quelle":"FZV, BOKraft, PBefG","lek":"zulassung","sg":"3.1","de":{"frage":"Beschreiben Sie die Schritte von der Anschaffung eines neuen Fahrzeugs bis zum ersten Einsatz als Mietwagen.","muster":"<p>Fahrzeug mit Typgenehmigung/COC kaufen; ausrüsten (Wegstreckenzähler mit TSE, Alarmanlage, keine Taxi-Kennzeichen); als Mietwagen versichern (eVB); bei der Zulassungsbehörde zulassen; Wegstreckenzähler eichen lassen; Hauptuntersuchung nach § 42 BOKraft vor dem ersten Einsatz, Bericht an die Genehmigungsbehörde; Fahrzeug in die Genehmigung eintragen lassen, Ordnungsnummer anbringen; Aufzeichnungssystem beim Finanzamt melden.</p>","punkte_liste":["Ausrüstung (Wegstreckenzähler, Alarmanlage)","Versicherung und Zulassung","Eichung","HU nach BOKraft mit Bericht an die Behörde","Eintragung in die Genehmigung / Ordnungsnummer"]}}];
